export const recipes: CountryRecipe[] = [{"country":"my","id":"nasi-lemak","slug":"nasi-lemak","title":{"zh-TW":"大馬國寶椰漿飯 (辣死你媽)","en":"Classic Malaysian Nasi Lemak","ms":"Nasi Lemak Sambal Ikan Bilis Tradisional","ja":"ナシレマ（ココナッツライス＆サンバル定食）","ko":"클래식 말레이시아 나시 레막"},"subtitle":{"zh-TW":"斑蘭椰香熱飯・酥脆小魚乾花生・靈魂香辣甜參巴醬","en":"Coconut Pandan Fragrant Rice with Crispy Anchovies & Sweet-Spicy Sambal","ms":"Nasi Santan Pandan Wangi dengan Sambal Tumis Ikan Bilis Rangup","ja":"パンダン香るココナッツご飯、カリカリ小魚ピーナッツと甘辛サンバル","ko":"판단잎 코코넛 향기 가득한 밥과 바삭한 멸치 땅콩, 매콤달콤 삼발"},"tagline":{"zh-TW":"跨越四大族群的全民信仰！大馬無可爭議的第一國民美食","en":"The undisputed national dish of Malaysia loved across all ethnic cultures","ms":"Hidangan kebangsaan Malaysia yang menyatukan segenap lapisan masyarakat","ja":"民族を超えて全国民に愛されるマレーシアの絶対的ソウルフード","ko":"말레이시아 전 국민이 사랑하는 독보적인 국민 대표 요리"},"heroImage":"/images/my/nasi-lemak.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":35,"defaultServings":2,"caloriesPerServing":620,"category":"mains","dietaryTags":["classic","halal"],"supportedCookware":["traditional","airFryer","instantPot"],"culture":{"originRegion":{"zh-TW":"全馬全境・發源於馬來鄉村 (Kampung)","en":"Nationwide / Kampung Roots","ms":"Seluruh Malaysia / Asal Usul Kampung","ja":"マレーシア全土・マレー伝統村落発祥","ko":"말레이시아 전역 / 전통 캄퐁(마을) 유래"},"famousStreetMarkets":[{"zh-TW":"吉隆坡白沙羅 Village Park","en":"Village Park Damansara Utama","ms":"Village Park Damansara","ja":"ビレッジパーク（ダマンサラ）","ko":"빌리지 파크 (다만사라)"},{"zh-TW":"吉蘭丹茜蒂卡迪查大巴剎","en":"Pasar Siti Khadijah, Kelantan","ms":"Pasar Siti Khadijah","ja":"シティ・ハディジャ中央市場","ko":"시티 카디자 중앙 시장"}],"historyStory":{"zh-TW":"早年馬來農夫在破曉下田前，需要高熱量、耐存放且美味的早餐。主婦便用椰漿與芳香香蘭葉煮飯，搭配耐貯存的炸江魚仔、烤花生與香辣參巴，包裹在芭蕉葉中攜帶。中文諧音「辣死你媽」更成為海內外旅人朗朗上口的幽默稱號。","en":"Originally prepared by rural farmers needing dense, sustained energy before dawn fieldwork. Fragrant coconut-pandan rice with mineral-rich fried anchovies and sambal wrapped in banana leaves became an iconic, unifying staple.","ms":"Bermula sebagai sarapan petani desa yang memerlukan tenaga mencukupi sebelum turun ke sawah. Nasi berlemak santan dibungkus daun pisang kini menjadi simbol perpaduan negara.","ja":"夜明け前に畑へ向かう農民たちの活力源として誕生。ココナッツミルクとパンダンリーフで炊いたご飯を、長持ちする煮干しやサンバルと共にバナナの葉で包んだのが原点です。","ko":"이른 아침 논밭으로 일하러 가던 농부들의 든든한 아침 식사에서 유래했습니다. 바나나 잎에 코코넛 밥과 바삭한 멸치, 삼발을 싸서 먹던 전통이 국민 요리가 되었습니다."},"malayScript":"Nasi Lemak Sambal","malayPhonetics":"Nah-see Leh-mahk Sahm-bahl","audioPronunciationText":"Boss, Nasi Lemak satu bungkus, sambal lebih, telur mata satu!","communityHeritage":"Malay","nativeName":"Nasi Lemak Sambal","nativePhonetics":"Nasi Lemak Sambal"},"ingredients":[{"id":"jasmine-rice","name":{"zh-TW":"優質香米或長粒米","en":"Jasmine Rice or Long Grain Rice","ms":"Beras Wangi","ja":"ジャスミンライスまたは長粒米","ko":"자스민 라이스 또는 장립종 쌀"},"amount":250,"unitMetric":"g","unitUS":"1.25 cup","isKeyFlavor":false,"malayName":"Beras Wangi","malayPronunciation":"Beh-rahs Wah-ngee"},{"id":"coconut-milk","name":{"zh-TW":"純濃椰漿 (Santan)","en":"Pure Coconut Milk / Santan","ms":"Pati Santan Kelapa","ja":"高濃度ココナッツミルク","ko":"진한 코코넛 밀크"},"amount":150,"unitMetric":"ml","unitUS":"5 fl oz","isKeyFlavor":true,"malayName":"Santan Kelapa","malayPronunciation":"Sahn-tahn Keh-lah-pah"},{"id":"pandan-leaves","name":{"zh-TW":"新鮮香蘭葉 (打結)","en":"Fresh Pandan Leaves (Knotted)","ms":"Daun Pandan (Disimpul)","ja":"生パンダンリーフ（結び目を作る）","ko":"신선한 판단잎 (매듭지음)"},"amount":3,"unitMetric":"stalk","unitUS":"3 pcs","isKeyFlavor":true,"malayName":"Daun Pandan","malayPronunciation":"Dah-oon Pahn-dahn","substitute":{"substituteName":{"zh-TW":"天然香蘭精 1/3 茶匙","en":"Natural Pandan Extract 1/3 tsp","ms":"Ekstrak Pandan","ja":"天然パンダンエキス 1/3小さじ","ko":"천연 판단 추출액 1/3작은술"},"ratio":"1/3 tsp per cup rice","explanation":{"zh-TW":"若買不到生鮮香蘭葉，在煮飯時加入數滴天然香蘭精萃取即可重現香氣。","en":"If fresh leaves are unavailable, a few drops of natural extract replicates the floral aroma.","ms":"Gunakan beberapa titis ekstrak pandan jika tiada daun segar.","ja":"生葉がない場合は天然パンダンエッセンスを少量加えて香りを再現。","ko":"신선한 잎이 없을 경우 천연 추출액 몇 방울로 향을 낼 수 있습니다."},"whereToBuy":{"zh-TW":"亞洲超市冷凍庫或烘焙店","en":"Asian grocer freezer or bakery supply","ms":"Pasar raya atau kedai bakeri","ja":"アジアンスーパー冷凍コーナー","ko":"아시안 마트 냉동 코너"}}},{"id":"dried-anchovies","name":{"zh-TW":"大馬特產白肚丁香江魚仔 (去內臟)","en":"Malaysian Dried Anchovies (Ikan Bilis, split)","ms":"Ikan Bilis Kopek Rangup","ja":"マレーシア産煮干し小魚（イカン・ビリス）","ko":"말레이시아산 건조 멸치 (이칸 빌리스)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"malayName":"Ikan Bilis","malayPronunciation":"Ee-kahn Bee-lees"},{"id":"raw-peanuts","name":{"zh-TW":"生花生米 (帶紅皮)","en":"Raw Peanuts (Skin-on)","ms":"Kacang Tanah Mentah","ja":"生落花生（薄皮つきピーナッツ）","ko":"생땅콩 (껍질째)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":false,"malayName":"Kacang Tanah","malayPronunciation":"Kah-chahng Tah-nah"},{"id":"dried-chilies","name":{"zh-TW":"乾辣椒 (剪段去籽泡軟)","en":"Dried Red Chilies (Boiled & softened)","ms":"Cili Kering Rebus","ja":"乾燥赤唐辛子（湯戻しして種抜き）","ko":"건고추 (물에 불려 씨 제거)"},"amount":15,"unitMetric":"piece","unitUS":"15 pcs","isKeyFlavor":true,"malayName":"Cili Kering","malayPronunciation":"Chee-lee Keh-ring"},{"id":"shallots","name":{"zh-TW":"紅蔥頭 (去皮研磨)","en":"Shallots (Peeled)","ms":"Bawang Merah Kecil","ja":"エシャロット（赤わけぎ）","ko":"샬롯 (작은 붉은 양파)"},"amount":8,"unitMetric":"piece","unitUS":"8 pcs","isKeyFlavor":true,"malayName":"Bawang Merah","malayPronunciation":"Bah-wahng Meh-rah"},{"id":"belacan-paste","name":{"zh-TW":"乾焙 Belacan 蝦膏","en":"Toasted Belacan Shrimp Paste","ms":"Belacan Bakar","ja":"軽く炙ったブラチャン","ko":"구운 벨라찬 새우 페이스트"},"amount":10,"unitMetric":"g","unitUS":"0.35 oz","isKeyFlavor":true,"malayName":"Belacan","malayPronunciation":"Beh-lah-chahn"},{"id":"gula-melaka","name":{"zh-TW":"馬六甲椰糖 (切碎)","en":"Gula Melaka Palm Sugar (Shaved)","ms":"Gula Melaka Cincang","ja":"マラッカ産パームシュガー（刻み）","ko":"굴라 말라카 흑당 (다짐)"},"amount":25,"unitMetric":"g","unitUS":"1 tbsp","isKeyFlavor":true,"malayName":"Gula Melaka","malayPronunciation":"Goo-lah Meh-lah-kah"}],"steps":[{"stepNumber":1,"image":"/images/my/nasi-lemak-step1.jpg","title":{"zh-TW":"烹煮靈魂斑蘭椰漿香飯","en":"Cook Fragrant Coconut Pandan Rice","ms":"Masak Nasi Santan Pandan Wangi","ja":"パンダンココナッツご飯を炊く","ko":"판단 코코넛 밥 짓기"},"instruction":{"zh-TW":"香米洗淨瀝乾放入電鍋或飯煲。倒入 150ml 濃椰漿、180ml 清水、1/2 茶匙海鹽與 2 片拍破老薑。將 3 根香蘭葉打結揉出青香後壓入米中。按下煮飯鍵，煮熟後保溫燜蒸 10 分鐘，用飯匙輕柔拌散米粒使其油亮分明。","en":"Wash rice and place in cooker. Add 150ml coconut milk, 180ml water, 1/2 tsp salt, and bruised ginger slices. Tie 3 pandan leaves into tight knots, bruise lightly to release oils, and tuck into rice. Cook until fluffy, rest for 10 mins, then gently fluff with paddle.","ms":"Cuci beras bersih. Masukkan santan, air, garam dan hirisan halia. Simpul daun pandan dan masukkan ke dalam periuk nasi. Masak sehingga tanak dan gemburkan nasi perlahan.","ja":"米を研ぎ、ココナッツミルク、水、塩、叩いた生姜を入れます。パンダンリーフを結んで米に埋め込み、通常炊飯。炊き上がったら10分蒸らし、優しくほぐします。","ko":"쌀을 씻어 밥솥에 안치고 코코넛 밀크, 물, 소금, 으깬 생강을 넣습니다. 판단잎을 매듭지어 쌀 속에 넣고 취사 후 10분간 뜸을 들여 고슬고슬하게 섞어줍니다."},"durationSeconds":1500,"crucialTips":{"zh-TW":"椰漿油脂豐富易沉底結焦，煮飯前務必將椰漿、水與鹽攪拌均勻再通電！","en":"Coconut milk fats tend to settle at the bottom. Stir thoroughly with water and salt before starting the cooker to avoid burning.","ms":"Kacau rata santan bersama air dan garam sebelum mula masak supaya bahagian bawah tidak hangit.","ja":"ココナッツミルクは底に沈みやすいため、スイッチを入れる前に水と塩をしっかり混ぜ合わせるのが焦げ付き防止のコツ。","ko":"코코넛 밀크는 바닥에 가라앉아 타기 쉬우므로 취사 전 물과 소금을 고루 섞어주세요."},"cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: High Pressure 5 mins + Natural Release 10 mins","instructionOverride":{"zh-TW":"壓力鍋模式：內膽塗薄油，米水椰漿比例 1:1.1，高壓 5 分鐘後自然洩壓 10 分鐘，米飯極其彈牙飽滿。","en":"Instant Pot: 1:1.1 rice-to-liquid ratio. High pressure for 5 mins, natural release for 10 mins.","ms":"Periuk Tekanan: Tekanan tinggi 5 minit, biarkan wap keluar sendiri 10 minit.","ja":"電気圧力鍋：高圧5分＋自然減圧10分。粒立ちが極めて良く仕上がります。","ko":"인스턴트팟: 고압 5분 + 자연 김빼기 10분으로 지으면 밥알이 탱글탱글합니다."}}]},{"stepNumber":2,"image":"/images/my/nasi-lemak-step2.jpg","title":{"zh-TW":"炸製酥脆江魚仔與紅皮花生","en":"Fry Golden Crispy Anchovies & Peanuts","ms":"Goreng Ikan Bilis & Kacang Tanah Rangup","ja":"小魚とピーナッツをカリカリに揚げる","ko":"바삭한 멸치와 땅콩 튀기기"},"instruction":{"zh-TW":"油鍋溫熱（約 150°C），先下生花生慢火煸炸 3-4 分鐘至外皮深紅香脆，撈出瀝油撒微量鹽。接著下江魚仔中火酥炸約 2 分鐘至金黃透亮、氣泡變小，立刻撈出瀝乾，冷卻後極度酥脆！","en":"Heat 3 tbsp oil. Fry raw peanuts on medium-low for 3-4 mins until skins deepen. Drain and sprinkle a touch of salt. In the same fragrant oil, fry anchovies for 2 mins until golden and bubbles subside. Drain immediately.","ms":"Panaskan minyak. Goreng kacang tanah atas api sederhana hingga rangup, angkat. Kemudian goreng ikan bilis hingga garing keemasan. Toskan minyak.","ja":"フライパンに油を熱し、ピーナッツを中弱火で3〜4分カリッとするまで揚げて取り出します。同じ油で小魚を約2分、気泡が小さくなるまで香ばしく揚げます。","ko":"팬에 기름을 두르고 생땅콩을 중약불에서 3-4분간 노릇하게 튀겨냅니다. 같은 기름에 멸치를 넣고 기포가 잦아들 때까지 2분간 바삭하게 튀겨 건집니다."},"durationSeconds":360,"dangerWarnings":{"zh-TW":"江魚仔極易過焦變苦！顏色一旦轉為淺金黃即需離火起鍋，餘溫會繼續上色。","en":"Anchovies burn in seconds! Remove as soon as they turn light golden; residual heat will finish browning them.","ms":"Ikan bilis cepat hangus! Angkat sebaik sahaja bertukar keemasan kerana haba baki akan terus memasaknya.","ja":"煮干しは焦げると強い苦味が出ます！薄いきつね色になった瞬間に引き上げるのが鉄則。","ko":"멸치는 순식간에 타서 쓴맛이 날 수 있으니 옅은 황금빛이 돌 때 즉시 건져내세요."},"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 160°C (320°F) 6-8 mins","instructionOverride":{"zh-TW":"氣炸鍋模式：江魚仔與花生拌入 1 茶匙油，鋪平在炸籃 160°C 氣炸 6-8 分鐘，中途搖晃一次，低油極度爽脆！","en":"Air Fryer: Toss with 1 tsp oil, spread in basket. Air fry at 160°C (320°F) for 6-8 mins, shaking halfway.","ms":"Air Fryer: Gaulkan bersama 1 sk minyak, bakar 160°C selama 6-8 minit, goncang separuh masa.","ja":"エアフライヤー：油小さじ1を絡めて160℃で6〜8分加熱。途中で一度振ると均一にカリカリになります。","ko":"에어프라이어: 오일 1작은술을 버무려 160℃에서 6-8분간 조리 (중간에 한 번 흔들어주기)."}}]},{"stepNumber":3,"image":"/images/my/nasi-lemak-step3.jpg","title":{"zh-TW":"慢炒靈魂香辣甜參巴醬 (Sambal Tumis)","en":"Slow-Cook the Soul-Stirring Sweet-Spicy Sambal","ms":"Tumis Sambal Bilis Pekat Pecah Minyak","ja":"極上サンバルソースをじっくり炒める","ko":"영혼을 울리는 매콤달콤 삼발 소스 볶기"},"instruction":{"zh-TW":"將泡軟乾辣椒、紅蔥頭、大蒜、石栗與烘烤過的 Belacan 蝦膏加少許油用調理機打成細緻辣醬。利用剛剛炸魚油熱鍋，倒入辣醬慢火煸炒 15-20 分鐘，直到辣油析出（Pecah Minyak）。加入馬六甲椰糖、羅望子汁、洋蔥絲與 1 茶匙鹽，小火慢煨至醬汁濃稠如紅寶石般黑紅油亮！","en":"Blend soaked dried chilies, shallots, garlic and toasted belacan into a smooth paste. Fry in remaining anchovy oil over medium-low for 15-20 mins until deep crimson oil separates (Pecah Minyak). Add shaved Gula Melaka, tamarind pulp juice, sliced onions and salt. Simmer until thick, glossy and fragrant.","ms":"Kisar cili kering, bawang merah, bawang putih dan belacan bakar. Tumis dengan minyak lebihan ikan bilis hingga pecah minyak. Masukkan gula Melaka, air asam jawa dan bawang besar hiris. Masak hingga pekat berkilat.","ja":"戻した赤唐辛子、エシャロット、ニンニク、炙りブラチャンをペースト状に撹拌。魚油で15〜20分じっくり炒め、赤く澄んだ油が分離（プチャ・ミニャッ）するまで加熱。パームシュガー、タマリンド汁、スライス玉ねぎを加えて煮詰めます。","ko":"불린 건고추, 샬롯, 마늘, 구운 벨라찬을 곱게 갈아 페이스트를 만듭니다. 멸치를 튀겼던 기름에 넣고 중약불에서 15-20분간 붉은 기름이 배어나올 때까지 충분히 볶은 뒤 굴라 말라카 흑당, 타마린드 즙, 양파를 넣고 걸쭉해질 때까지 조립니다."},"durationSeconds":1200,"crucialTips":{"zh-TW":"大馬煮參巴最高境界「Pecah Minyak」（出油透香）是關鍵！絕不能著急，必須慢火炒出水份，辣椒才能甘甜不嗆喉。","en":"Achieving \"Pecah Minyak\" (oil separation) is the gold standard of Malay cooking! It caramelizes the chili sugars and eliminates raw chili bite.","ms":"Pastikan sambal ditumis sehingga betul-betul pecah minyak agar sambal tahan lama, tidak sakit perut dan harum karamel.","ja":"「プチャ・ミニャッ（油の分離）」こそマレー料理の真髄！水分が飛び、赤油が浮き出るまで根気強く炒めることで唐辛子の甘みが引き出されます。","ko":"말레이 요리의 핵심인 \"쁘짜 미냑(기름 분리 현상)\"이 일어날 때까지 충분히 볶아야 고추의 풋내가 사라지고 깊은 단맛이 우러납니다."}},{"stepNumber":4,"image":"/images/my/nasi-lemak-step4.jpg","title":{"zh-TW":"經典芭蕉葉排盤大功告成","en":"Assemble the Iconic Banana Leaf Platter","ms":"Hidang Atas Daun Pisang Tradisional","ja":"バナナの葉に盛り付けて完成","ko":"바나나 잎 위에 정갈하게 플레이팅"},"instruction":{"zh-TW":"在盤中鋪上烤熱拭淨的芭蕉葉。用碗盛起熱騰騰的斑蘭椰漿飯倒扣在中央。周圍環繞擺上金黃江魚仔、香脆花生、水煮蛋切半、新鮮黃瓜厚片，以及一大勺黑紅光澤的靈魂參巴醬。趁熱拌勻享用！","en":"Line plate with warmed banana leaf. Invert a bowl of fragrant coconut rice into center. Flank with crispy anchovies, roasted peanuts, halved hard-boiled egg, cool cucumber slices, and a generous ladle of glistening ruby sambal.","ms":"Alas pinggan dengan daun pisang. Sendukkan nasi lemak panas di tengah. Susun ikan bilis, kacang, telur rebus, timun dan sesudu besar sambal tumis panas.","ja":"軽く炙ったバナナの葉を敷き、中央にココナッツご飯を盛ります。周りに小魚、ピーナッツ、ゆで卵、きゅうりを配置し、艶やかなサンバルをたっぷり添えて完成です！","ko":"살짝 구운 바나나 잎을 접시에 깔고 중앙에 밥을 봉긋하게 담습니다. 둘레에 바삭한 멸치, 땅콩, 삶은 계란, 오이 슬라이스를 두르고 삼발을 듬뿍 얹어냅니다."},"durationSeconds":180}],"troubleshooting":[{"id":"rice-mushy","problem":{"zh-TW":"椰漿飯煮出來過於濕黏軟爛","en":"Rice turns out mushy and sticky","ms":"Nasi lembik dan melekit","ja":"ココナッツご飯がベチャつく","ko":"밥이 질고 떡지는 현상"},"cause":{"zh-TW":"水份與椰漿總量過多，或未適當燜蒸","en":"Excess total liquid or inadequate resting time","ms":"Cecair berlebihan atau tidak direhatkan","ja":"水分量が多すぎる、または蒸らし不足","ko":"수분량이 너무 많거나 뜸 들이기가 부족함"},"solution":{"zh-TW":"椰漿本身具稠度，水與椰漿總液體量與米體積比約為 1.1:1。煮好後勿立即開蓋，務必關火燜 10-15 分鐘吸收餘溫水氣。","en":"Maintain 1:1.1 rice-to-total-liquid volume. Rest covered for 10-15 mins after cooking.","ms":"Kekalkan nisbah 1:1.1 dan rehatkan nasi 10-15 minit sebelum gembur.","ja":"米に対する総水分量を1.1倍に抑え、炊飯後必ず10〜15分蒸らします。","ko":"쌀 대비 총 액체 비율을 1.1:1로 맞추고 취사 완료 후 10-15분간 꼭 뜸을 들이세요."}},{"id":"sambal-too-spicy","problem":{"zh-TW":"參巴辣椒醬辣度過猛嗆喉","en":"Sambal is overwhelmingly fiery","ms":"Sambal terlalu pedas menyengat","ja":"サンバルの辛さが強すぎる","ko":"삼발 소스가 지나치게 매움"},"cause":{"zh-TW":"乾辣椒未去籽或未加入足夠椰糖中和","en":"Chili seeds not removed or insufficient palm sugar","ms":"Biji cili tidak dibuang atau kurang gula","ja":"唐辛子の種が多い、またはパームシュガー不足","ko":"고추씨를 덜 털어냈거나 흑당이 부족함"},"solution":{"zh-TW":"煮乾辣椒時用剪刀縱剖搖出辣椒籽；炒製時追加 1 大匙馬六甲椰糖與半顆切碎洋蔥提甘。","en":"Slit dried chilies to discard seeds before boiling; add more Gula Melaka and caramelized onions.","ms":"Buang biji cili sebelum rebus dan tambahkan lebih gula Melaka serta bawang besar.","ja":"乾燥唐辛子は茹でる前に種を振り落とし、黒糖と炒め玉ねぎの量を増やして甘みで中和します。","ko":"건고추를 데치기 전 씨를 완전히 털어내고, 굴라 말라카 흑당과 양파를 추가해 단맛으로 감싸주세요."}}],"proTips":[{"zh-TW":"老饕吃法：吃 Nasi Lemak 時不要把參巴醬全倒在飯上拌成紅飯，而是每一口飯舀取一點參巴、配上一小撮小魚乾與花生，感受冷脆、熱糯與辛香在口中迸發！","en":"Local Pro-Tip: Don’t mix the whole plate into red mush! Spoon a forkful of rice, dab a dollop of sambal, and cap with a few crunchy anchovies for the ultimate texture clash.","ms":"Petua Otai: Jangan gaul semua sambal ke atas nasi! Ambil sesuap nasi, calit sedikit sambal bersama ikan bilis rangup untuk kenikmatan rasa berperingkat.","ja":"地元民の食べ方：最初から全部混ぜず、スプーンの上にひと口のご飯、少量のサンバル、カリカリの小魚とピーナッツを乗せて食べるのが本場のスタイル！","ko":"현지식 꿀팁: 전체를 비비지 마세요! 숟가락에 코코넛 밥 한 입, 삼발 살짝, 바삭한 멸치와 땅콩을 얹어 식감과 풍미의 조화를 즐겨보세요."}]},{"country":"my","id":"char-kway-teow","slug":"char-kway-teow","title":{"zh-TW":"檳城極致鑊氣鴨蛋炒粿條","en":"Penang Wok-Hei Char Kway Teow","ms":"Char Kway Teow Telur Itik Pulau Pinang","ja":"ペナン名物・強火鴨卵チャークエティオ","ko":"페낭 오리알 차퀘이테오 (불맛 볶음 쌀국수)"},"subtitle":{"zh-TW":"極限鑊氣・鮮甜血蛤大蝦・焦香豬油渣與濃郁鴨蛋黃","en":"Blistering Wok Hei, Plump Prawns, Blood Cockles & Duck Egg Emulsion","ms":"Aroma Kuali Kuat, Udang Segar, Kerang Basah & Telur Itik Lemak","ja":"熱気あふれる鍋気（ウォックヘイ）、大エビと生赤貝、芳醇な鴨卵","ko":"강렬한 웍 불맛, 통통한 새우, 피꼬막과 고소한 오리알의 조화"},"tagline":{"zh-TW":"世界公認街頭炒粉殿堂級傑作，炭火與鐵鑊碰撞的靈魂絕響","en":"The undisputed global champion of stir-fried rice noodles","ms":"Juara masakan mi goreng jalanan yang diiktiraf di persada antarabangsa","ja":"世界中の美食家を唸らせる屋台炒め麺の頂点。鉄鍋の焦げ香が命","ko":"전 세계 미식가들이 인정하는 볶음 쌀국수의 정점이자 전설적인 요리"},"heroImage":"/images/my/char-kway-teow.jpg","difficulty":"hard","prepTimeMinutes":20,"cookTimeMinutes":6,"defaultServings":2,"caloriesPerServing":590,"category":"noodles","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"北馬・檳城喬治市 (Penang Georgetown)","en":"Northern Malaysia / Penang","ms":"Pulau Pinang","ja":"北部・ペナン島ジョージタウン","ko":"말레이시아 북부 / 페낭 조지타운"},"famousStreetMarkets":[{"zh-TW":"檳城新關仔角熟食中心","en":"Gurney Drive Hawker, Penang","ms":"Anjung Gurney","ja":"ガーニードライブ屋台街","ko":"거니 드라이브 호커 센터"},{"zh-TW":"檳城光華興檳茶室 (阿聯炒粿條)","en":"Ah Leng Char Kway Teow, Penang","ms":"Ah Leng Char Kway Teow","ja":"アーレン・チャークエティオ","ko":"아렝 차퀘이테오"}],"historyStory":{"zh-TW":"發源於 19 世紀下南洋的潮州與閩南移民。碼頭苦力在烈日下揮汗搬運貨物，需要極高的熱量補充。攤販便將寬扁的米漿粿條，加入自煉豬油渣、韭菜、豆芽、鮮蝦與鮮活血蛤（Siham），在猛火鐵鑊中快速爆炒，以芭蕉葉盛裝，香氣四溢。","en":"Created by Teochew and Hokkien dockworkers in 19th-century Penang. Strenuous harbor work demanded cheap, instant caloric power. Hawkers transformed flat rice noodles with rendered lard cracklings, fat sea prawns, garlic chives and fresh blood cockles over raging fires.","ms":"Bermula daripada komuniti nelayan dan pekerja pelabuhan Teochew di Pulau Pinang. Kuali besi panas membakar kway teow bersama minyak babi/sayur, udang dan kerang dalam beberapa minit.","ja":"19世紀ペナンの港湾労働者のスタミナ食として潮州・福建移民が考案。平打ちの米粉麺を、強火の鉄鍋でラード、大エビ、赤貝、ニラと共に一気に炒め上げます。","ko":"19세기 페낭 항구 노동자들의 기력 보충을 위해 조주 및 복건 출신 화교들이 개발한 요리입니다. 강한 불꽃 위에서 굵은 쌀국수를 해산물과 함께 볶아냅니다."},"malayScript":"Char Kway Teow Penang","malayPhonetics":"Chahr Kway Tee-ow Peh-nahng","audioPronunciationText":"Uncle, Char Kway Teow tambah telur itik satu, siham lebih, pedas!","communityHeritage":"Chinese","nativeName":"Char Kway Teow Penang","nativePhonetics":"Char Kway Teow Penang"},"ingredients":[{"id":"flat-rice-noodles","name":{"zh-TW":"新鮮寬米粉 (粿條 / 沙河粉)","en":"Fresh Flat Rice Noodles (Kway Teow)","ms":"Kuey Teow Segar Lebar","ja":"生・平打ちライスヌードル（クエティオ）","ko":"신선한 납작 쌀국수 면 (퀘이테오)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"malayName":"Kuey Teow Segar","malayPronunciation":"Kway Tee-ow Seh-gahr"},{"id":"duck-eggs","name":{"zh-TW":"新鮮生鴨蛋 (極致濃郁乳化)","en":"Fresh Raw Duck Eggs (or rich farm eggs)","ms":"Telur Itik Segar","ja":"新鮮な生鴨卵（または濃厚地鶏卵）","ko":"신선한 생오리알 (또는 신선한 계란)"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":true,"malayName":"Telur Itik","malayPronunciation":"Teh-loor Ee-teek"},{"id":"tiger-prawns","name":{"zh-TW":"新鮮大草蝦或海白蝦 (開背去腸)","en":"Jumbo Sea Prawns (Peeled, deveined, tail-on)","ms":"Udang Harimau Laut Segar","ja":"新鮮な大エビ（背わた取り・尾つき）","ko":"신선한 대하 또는 중하 (손질 새우)"},"amount":8,"unitMetric":"piece","unitUS":"8 pcs","isKeyFlavor":true,"malayName":"Udang Laut","malayPronunciation":"Oo-dahng Lah-oot"},{"id":"blood-cockles","name":{"zh-TW":"新鮮生血蛤肉 (鮮螄蚶 / Siham)","en":"Fresh Blood Cockles (Siham / Kerang)","ms":"Kerang Bulu Segar (Siham)","ja":"新鮮な赤貝（サルボウ貝 / シーハム）","ko":"신선한 피꼬막 살 (시함)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"malayName":"Isi Kerang","malayPronunciation":"Ee-see Keh-rahng"},{"id":"chinese-sausage","name":{"zh-TW":"廣式玫瑰露臘腸 (切薄斜片)","en":"Chinese Cured Sausage (Lap Cheong, thinly sliced)","ms":"Lap Cheong Ayam / Daging","ja":"中華ソーセージ（腸詰・薄切り）","ko":"중화 소시지 (랍청, 얇게 편 썬 것)"},"amount":1,"unitMetric":"stalk","unitUS":"1 pc","isKeyFlavor":false,"malayName":"Lap Cheong","malayPronunciation":"Lahp Chee-ong"},{"id":"lard-crisps","name":{"zh-TW":"現煉豬油與金黃脆豬油渣","en":"Rendered Lard & Golden Pork Cracklings (or peanut oil)","ms":"Minyak Masak & Bawang Goreng","ja":"自家製ラード＆豚油かす（または高発煙点油）","ko":"돼지기름(라드) & 바삭한 돼지껍질 크랙클링"},"amount":40,"unitMetric":"g","unitUS":"3 tbsp","isKeyFlavor":true,"malayName":"Minyak Masak Wangi","malayPronunciation":"Meen-yahk Mah-sahk"},{"id":"garlic-chives","name":{"zh-TW":"新鮮青韭菜 (切段)","en":"Fresh Chinese Garlic Chives (Ku Chai, cut into 4cm)","ms":"Kucai Segar","ja":"ニラ（4cm長さにカット）","ko":"신선한 부추 (4cm 길이로 썬 것)"},"amount":50,"unitMetric":"g","unitUS":"1.7 oz","isKeyFlavor":true,"malayName":"Daun Kucai","malayPronunciation":"Dah-oon Koo-chai"},{"id":"bean-sprouts","name":{"zh-TW":"飽滿爽脆銀芽 (綠豆芽菜)","en":"Plump Bean Sprouts (Taugeh, rinsed)","ms":"Taugeh Gemuk Segar","ja":"シャキシャキ太もやし","ko":"통통하고 아삭한 숙주나물"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":false,"malayName":"Taugeh","malayPronunciation":"Tah-oo-geh"},{"id":"dark-caramel-sauce","name":{"zh-TW":"大馬特級焦香黑醬油 (晒油)","en":"Thick Caramel Dark Soy Sauce (Kicap Pekat)","ms":"Kicap Pekat Karamel","ja":"マレーシア特選カラメル黒醤油（晒油）","ko":"말레이시아 전통 캐러멜 흑간장 (사이유)"},"amount":20,"unitMetric":"ml","unitUS":"1.5 tbsp","isKeyFlavor":true,"malayName":"Kicap Pekat","malayPronunciation":"Kee-chahp Peh-kaht"},{"id":"light-soy-fish-sauce","name":{"zh-TW":"特調生抽與純魚露","en":"Light Soy Sauce & Pure Fish Sauce","ms":"Kicap Cair & Sos Ikan","ja":"薄口生醤油＆ナンプラー","ko":"양조 진간장 & 피시소스"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","isKeyFlavor":false,"malayName":"Kicap Cair","malayPronunciation":"Kee-chahp Chah-eer"},{"id":"chili-bo","name":{"zh-TW":"自製乾辣椒炒醬 (Cili Bo)","en":"Malaysian Homemade Chili Bo Paste","ms":"Pes Cili Giling (Cili Bo)","ja":"自家製チリ・ボー唐辛子ペースト","ko":"칠리 보 (말레이시아 고추 페이스트)"},"amount":20,"unitMetric":"g","unitUS":"1 tbsp","isKeyFlavor":true,"malayName":"Cili Boh","malayPronunciation":"Chee-lee Boh"}],"steps":[{"stepNumber":1,"image":"/images/my/char-kway-teow-step1.jpg","title":{"zh-TW":"單人單份高溫炙熱鐵鑊","en":"Blaze the Cast Iron Wok for Single Serving","ms":"Panaskan Kuali Besi Sehingga Berasap Tebal","ja":"鉄鍋から煙が出るまで強火で空焼きする","ko":"무쇠 웍을 연기가 날 때까지 강불로 달구기"},"instruction":{"zh-TW":"【秘訣：炒粿條必須一人份單獨炒，不可雙人份一鍋下！】鐵鑊大火燒至劇烈冒青煙，倒入 1.5 大匙豬油（或耐高溫花生油）。下蒜碎、臘腸薄片與大蝦快速煸煎 30 秒，直至蝦身泛紅、臘腸油脂微焦飄香。","en":"[Golden Rule: Cook ONE serving at a time!] Heat carbon steel wok until smoking furiously. Add 1.5 tbsp lard. Toss in minced garlic, sliced lap cheong and sea prawns. Sear for 30 secs until prawns curl pink and sausage edges crisp.","ms":"[Peraturan Emas: Masak SATU pinggan setiap kali!] Panaskan kuali sehingga berasap. Masukkan minyak/minyak babi, bawang putih, sosej dan udang. Tumis 30 saat sehingga udang kemerahan.","ja":"【最重要鉄則：必ず1人前ずつ炒めること！】鉄鍋から煙が立ち上るまで熱し、ラード大さじ1.5を投入。ニンニク、中華ソーセージ、エビを30秒強火で炒め、香ばしい脂を引き出します。","ko":"【황금 법칙: 반드시 1인분씩 볶아낼 것!】웍에서 연기가 솟구칠 때까지 달군 후 라드 1.5큰술을 두릅니다. 다진 마늘, 랍청 소시지, 새우를 넣고 30초간 강불에서 빠르게 볶아 향을 냅니다."},"durationSeconds":45,"crucialTips":{"zh-TW":"鑊氣（Wok Hei）來自極限高溫下的油脂氣化。家裡瓦斯爐請開到極限大火！","en":"Wok Hei is generated by aerosolized oil droplets vaporizing at super high temperatures. Maximize your burner output!","ms":"Aroma kuali wangi terhasil daripada wap minyak pada suhu teramat tinggi. Gunakan api paling kuat di dapur anda!","ja":"「鍋気（ウォックヘイ）」は超高温で油の微粒子が気化することで生まれます。コンロの火力を最大に！","ko":"웍헤이(불맛)는 초고온에서 증발하는 오일 미립자에서 탄생합니다. 가정용 가스레인지의 화력을 최대로 올리세요!"}},{"stepNumber":2,"image":"/images/my/char-kway-teow-step2.jpg","title":{"zh-TW":"粿條下鍋與焦糖黑醬油極速翻拋","en":"Toss Kway Teow with Caramel Black Sauce at High Heat","ms":"Masukkan Kuey Teow & Kicap Karamel, Goreng Pantas","ja":"麺を投入しカラメル黒醤油を一気に焼き付ける","ko":"국수 투하 후 캐러멜 흑간장으로 고속 볶기"},"instruction":{"zh-TW":"放入 150g 新鮮粿條與 1 大匙辣椒醬（Cili Bo）。沿著鍋邊淋入 1 大匙焦香黑醬油、1 茶匙生抽與 1/2 茶匙純魚露。鐵鏟快速翻炒、將粿條在滾燙鐵鍋底攤平貼燙 10 秒形成焦香金邊，隨後劇烈拋鍋 15 秒！","en":"Toss in 150g fresh noodles and 1 tbsp chili bo paste. Swirl 1 tbsp dark caramel sauce, 1 tsp light soy and 1/2 tsp fish sauce along the scorching wok edges. Press noodles flat against the hot metal for 10 secs to sear blistered edges, then flip furiously for 15 secs!","ms":"Masukkan 150g kuey teow dan pes cili. Renjiskan kicap pekat karamel, kicap cair dan sos ikan di tepi kuali. Tekan kuey teow pada kuali 10 saat sebelum digaul pantas.","ja":"麺150gとチリペーストを投入。鍋肌から黒醤油、薄口醤油、ナンプラーを回し入れます。麺を鍋肌に押し当てて10秒焼き色をつけ、一気に煽ります！","ko":"면 150g과 칠리 페이스트를 넣고 웍 가장자리를 따라 흑간장, 진간장, 피시소스를 둘러줍니다. 면을 달궈진 웍 바닥에 10초간 눌러붙이듯 지져 불맛을 입힌 뒤 15초간 격렬하게 볶습니다."},"durationSeconds":60,"dangerWarnings":{"zh-TW":"切忌加水！一旦加水，鍋溫暴跌，粿條立刻碎斷成糊且全無鍋氣！","en":"NEVER add water! Adding water plunges wok temp, breaking noodles into mush and killing the wok hei instantly.","ms":"JANGAN sesekali tambah air! Air akan menjatuhkan suhu kuali, menyebabkan kuey teow hancur dan hilang bau kuali.","ja":"絶対に水を差さないでください！鍋の温度が一気に下がり、麺が千切れてベチャベチャになり台無しになります。","ko":"절대 물을 붓지 마세요! 물이 들어가면 웍 온도가 급락해 면이 뚝뚝 끊어지고 불맛이 완전히 사라집니다."}},{"stepNumber":3,"image":"/images/my/char-kway-teow-step3.jpg","title":{"zh-TW":"推開炒鴨蛋・融入豆芽韭菜鮮螄蚶","en":"Crack Duck Egg, Fold in Chives, Sprouts & Cockles","ms":"Pecahkan Telur Itik, Masukkan Kucai, Taugeh & Kerang","ja":"鴨卵を割り入れ、ニラ・もやし・赤貝を一気に絡める","ko":"오리알 깨 넣고 부추, 숙주, 피꼬막 넣어 마무리"},"instruction":{"zh-TW":"將粿條推至鑊邊，在中央露出的滾燙油面打入 1 顆生鴨蛋。用鏟輕輕戳破蛋黃使其微凝固，隨即將上方的熱粿條翻蓋在蛋液上。迅速撒入韭菜段、綠豆芽、豬油渣與新鮮血蛤。最後全力翻炒 20 秒，讓濃郁鴨蛋黃如金色絲絨般乳化包裹每根麵條，血蛤剛好半熟爆汁！","en":"Push noodles to side, crack raw duck egg into hot oiled center. Poke yolk lightly to half-set, then fold hot noodles over the egg. Drop in garlic chives, crunchy bean sprouts, pork lard cracklings and fresh cockles. Searing stir-fry for final 20 secs so creamy duck yolk emulsifies every noodle while cockles remain juicy!","ms":"Tolak kuey teow ke tepi, pecahkan telur itik di tengah. Lipat kuey teow atas telur, masukkan kucai, taugeh, minyak garing dan kerang. Gaul laju 20 saat sahaja!","ja":"麺を鍋の端に寄せ、中央に鴨卵を割り入れます。黄身を軽く崩して半熟になったら麺を上から被せ、ニラ、もやし、豚脂かす、赤貝を一気に投入。最後20秒強火で煽れば完成！","ko":"면을 웍 한쪽으로 밀고 중앙에 오리알을 깨 넣습니다. 노른자를 살짝 터뜨려 반숙이 되면 면을 덮어준 뒤 부추, 숙주, 돼지기름 크랙클링, 피꼬막을 투하합니다. 20초간 빠르게 볶아내면 오리알이 면에 윤기 있게 코팅됩니다!"},"durationSeconds":45,"crucialTips":{"zh-TW":"血蛤（螄蚶）切勿炒太久，只要 15-20 秒斷生即可，維持鮮紅微生帶血汁最為鮮甜軟嫩！","en":"Never overcook the cockles! 15-20 secs is plenty; they should remain plump, juicy and rare for maximum sweetness.","ms":"Kerang jangan dimasak terlalu lama! 15-20 saat sahaja sudah cukup agar isinya kekal manis berjus.","ja":"赤貝は火を通しすぎないのが鉄則！15〜20秒でレア気味に仕上げることで極上の甘みが楽しめます。","ko":"피꼬막은 오래 익히면 질겨집니다! 15-20초만 살짝 볶아 육즙이 촉촉하게 살아있을 때 드셔야 최고입니다."}},{"stepNumber":4,"image":"/images/my/char-kway-teow-step4.jpg","title":{"zh-TW":"滑入芭蕉葉熱盤趁熱出鍋","en":"Slide Onto Banana Leaf Plate and Serve Instantly","ms":"Tuang Atas Pinggan Daun Pisang Panas","ja":"バナナの葉を敷いた皿に盛り付け即座にいただく","ko":"바나나 잎을 깐 접시에 담아 즉시 서빙"},"instruction":{"zh-TW":"關火，立即將鑊氣蒸騰的炒粿條滑入墊有芭蕉葉的餐盤中。趁著剛出鍋十秒內的滾燙鑊氣大口享用，感受脆、滑、香、焦的多重感官震撼！","en":"Slide the piping hot noodles straight onto a banana-leaf-lined plate. Dig in within seconds while the wok hei is at its sensational peak!","ms":"Tuang terus atas daun pisang panas. Nikmati dalam masa beberapa saat selagi aroma kuali masih berwap panas!","ja":"火を止め、バナナの葉を敷いた器に滑らせるように盛り付けます。出来立ての熱気と香ばしさを逃さずすぐにお召し上がりください！","ko":"불을 끄고 바나나 잎이 깔린 접시로 쏟아내듯 담습니다. 웍헤이가 가시기 전 뜨거울 때 바로 드세요!"},"durationSeconds":15}],"troubleshooting":[{"id":"no-wok-hei","problem":{"zh-TW":"炒出的粿條水汪汪，完全沒有街頭鑊氣","en":"Noodles are soggy with zero smoky wok hei","ms":"Kuey teow berair dan tiada bau kuali","ja":"水っぽく仕上がり、鍋気（スモーキーな香り）がない","ko":"국수가 축축하고 웍의 불맛이 전혀 나지 않음"},"cause":{"zh-TW":"鍋不夠熱、一次炒超過 1 人份、或使用了不沾鍋","en":"Wok not hot enough, cooked too large a batch, or used non-stick pan","ms":"Kuali tidak cukup panas, masak terlalu banyak sekali gus","ja":"鍋の予熱不足、一度に2人前以上を炒めた、またはテフロン鍋の使用","ko":"팬 온도가 낮거나 한 번에 너무 많은 양을 볶음, 코팅팬 사용"},"solution":{"zh-TW":"務必使用生鐵鍋/碳鋼鍋，燒至白煙升騰；嚴格堅持「一人份單炒」，炒完一盤再炒下一盤！","en":"Must use carbon steel or cast iron; heat until visibly smoking; strictly cook ONE portion per run!","ms":"Gunakan kuali besi/keluli, panaskan hingga berasap dan masak 1 hidangan setiap kali!","ja":"必ず鉄鍋を使用し、煙が出るまで熱してください。面倒でも「1人前ずつ」炒めるのが絶対条件です。","ko":"반드시 탄소강 웍이나 무쇠 팬을 사용하고 연기가 날 때까지 달군 뒤, 반드시 \"1인분씩\" 따로 볶아내세요."}}],"proTips":[{"zh-TW":"老饕認證：傳統炒粿條一定要找炒鍋師傅「手邊備著一整箱生鴨蛋」的攤位！鴨蛋黃的卵磷脂與脂肪含量是雞蛋的兩倍，才能在大火中瞬間與黑醬油乳化，黏裹在每條粿條上而不出湯。","en":"Master Secret: True Penangites only visit stalls with stacks of raw duck eggs! Duck egg yolk has double the fat and lecithin of chicken eggs, creating an instant creamy glaze that clings to the noodles.","ms":"Rahsia Pakar: Peminat sejati hanya makan di gerai yang menggunakan telur itik! Kuning telur itik lebih pekat berlemak untuk menyalut setiap urat kuey teow.","ja":"大師の秘訣：本場ペナンの名店は必ず「鴨卵（ダックエッグ）」を使用します。鶏卵に比べて黄身の脂肪分が濃く、強火でタレと見事に乳化して麺をコーティングします。","ko":"마스터의 비법: 진정한 페낭 맛집은 닭알 대신 오리알을 고집합니다! 오리알 노른자는 지방 함량이 훨씬 높아 강한 불에서 간장 소스와 유화되어 면에 완벽히 밀착됩니다."}]},{"country":"my","id":"bak-kut-teh","slug":"bak-kut-teh","title":{"zh-TW":"巴生正宗瓦煲藥膳肉骨茶","en":"Authentic Klang Herbal Bak Kut Teh","ms":"Bak Kut Teh Herba Asli Pekan Klang","ja":"クラン発祥・本格土鍋薬膳肉骨茶（バクテー）","ko":"클랑 원조 뚝배기 한방 바쿠테 (돼지갈비 보양탕)"},"subtitle":{"zh-TW":"百年當歸藥膳濃黑湯頭・軟爛脫骨排骨・吸汁油豆腐炸油條","en":"Dark Angelica Herbal Broth, Fall-Apart Pork Ribs & Crispy Youtiao","ms":"Kuah Herba Pekat Dang Gui, Rusuk Daging Empuk & Cakoi Rangup","ja":"当帰香る濃厚な黒い薬膳スープ、ホロホロの豚スペアリブと油条","ko":"진한 당귀 한방 약재 육수, 부드럽게 뼈가 발라지는 돼지갈비와 유탸오"},"tagline":{"zh-TW":"大馬華人最深沉的鄉愁之味，雪蘭莪巴生碼頭工人的百年能量傳奇","en":"The definitive herbal elixir of Malaysian Chinese heritage from Klang port","ms":"Warisan masakan herba Cina Malaysia yang melegenda dari pelabuhan Klang","ja":"マレーシア華人の誇る伝統の味。クラン港の苦力たちを支えた奇跡のスープ","ko":"말레이시아 화교의 정체성이 담긴 보양식. 클랑 항구 노동자들의 100년 전설"},"heroImage":"/images/my/bak-kut-teh.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":75,"defaultServings":2,"caloriesPerServing":580,"category":"soups","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中馬・雪蘭莪巴生 (Klang, Selangor)","en":"Central Malaysia / Klang, Selangor","ms":"Klang, Selangor","ja":"中部・セランゴール州クラン","ko":"말레이시아 중부 / 셀랑고르 클랑"},"famousStreetMarkets":[{"zh-TW":"巴生盛發 (橋底肉骨茶)","en":"Seng Huat Bak Kut Teh (Under Bridge), Klang","ms":"Seng Huat Klang","ja":"スンファッ（橋底肉骨茶）","ko":"성홧 바쿠테 (다리 밑)"},{"zh-TW":"巴生奇香肉骨茶老店","en":"Kee Hiong Bak Kut Teh, Klang","ms":"Kee Hiong Klang","ja":"奇香バクテー本店","ko":"기흥 바쿠테 본점"}],"historyStory":{"zh-TW":"20 世紀初，下南洋的苦力工人聚集在巴生港碼頭搬運沉重橡膠與錫礦。為了驅散海港晨霧的濕寒並強健筋骨，祖籍福建同安的李文地收集藥行散碎的當歸、川芎、玉竹與甘草，與肉骨同熬成濃湯給苦力補氣補力，流傳為舉世聞名的巴生肉骨茶。","en":"In the early 1900s, Chinese coolies endured grueling manual labor at Port Klang. Founder Lee Boon Teh combined discarded herbal scraps (dang gui, licorice, solomon’s seal) with pork bones into a restorative dark broth to dispel damp chills, creating Malaysia’s most iconic soul broth.","ms":"Bermula di pelabuhan Klang pada awal kurun ke-20. Diasaskan oleh Lee Boon Teh yang merebus herba herba Cina bersama rusuk babi untuk memulihkan tenaga kuli pelabuhan.","ja":"20世紀初頭、クラン港で過酷な荷揚げ作業に従事した華人労働者のために、李文地が漢方薬材と豚骨を長時間煮込んで活力源としたのが始まり。シンガポールの白胡椒クリアスープとは異なり、濃厚な黒い薬膳スープが特徴です。","ko":"20세기 초 포트 클랑의 화교 노동자들을 위해 이문지(Lee Boon Teh)가 한약재와 돼지갈비를 푹 고아낸 것에서 유래했습니다. 싱가포르식의 맑은 백후추탕과 달리 진하고 깊은 검은 한방 육수가 특징입니다."},"malayScript":"Bak Kut Teh Herba Klang","malayPhonetics":"Bahk Koot Teh Hehr-bah Klahng","audioPronunciationText":"Tauke, Bak Kut Teh satu mangkuk besar, tambah tauhu pok, youtiao satu pinggan!","communityHeritage":"Chinese","nativeName":"Bak Kut Teh Herba Klang","nativePhonetics":"Bak Kut Teh Herba Klang"},"ingredients":[{"id":"pork-ribs","name":{"zh-TW":"優質帶肉豬小排或肉骨","en":"Meaty Pork Spare Ribs (cut into 6cm segments)","ms":"Rusuk Daging Pilihan (Daging Lembut)","ja":"豚スペアリブ（6cm幅カット）","ko":"살코기 듬뿍 돼지갈비 (6cm 토막)"},"amount":600,"unitMetric":"g","unitUS":"21 oz","isKeyFlavor":true,"malayName":"Tulang Rusuk Daging","malayPronunciation":"Too-lahng Roo-sook Dah-geeng"},{"id":"bkt-herb-pack","name":{"zh-TW":"巴生正宗肉骨茶藥膳包 (A1/奇香)","en":"Traditional Klang BKT Herb Spice Sachet","ms":"Rempah Herba Bak Kut Teh Klang","ja":"クラン正宗バクテー漢方スパイスパック","ko":"클랑 전통 한방 바쿠테 약재 티백"},"amount":1,"unitMetric":"piece","unitUS":"1 pack","isKeyFlavor":true,"malayName":"Rempah Herba","malayPronunciation":"Rehm-pah Hehr-bah","substitute":{"substituteName":{"zh-TW":"中藥行抓藥：當歸10g、川芎5g、玉竹15g、甘草5g、八角2粒、桂皮1支","en":"DIY Herbs: 10g dang gui, 5g chuan xiong, 15g solomon’s seal, 5g licorice, 2 star anise, 1 cinnamon stick","ms":"Campuran herba sendiri","ja":"自家調合漢方","ko":"직접 조합 한약재"},"ratio":"1:1","explanation":{"zh-TW":"在任何中藥行直接抓此份量，包入棉布袋即可。","en":"Any traditional Chinese herb dispensary can assemble this in minutes.","ms":"Boleh didapati di kedai ubat tradisional Cina.","ja":"漢方薬局で手軽に揃えられます。","ko":"한약방에서 쉽게 구입 가능한 구성입니다."},"whereToBuy":{"zh-TW":"中藥行或亞洲超市","en":"Asian supermarkets or herb stores","ms":"Pasar raya Cina","ja":"中華食材店・漢方薬局","ko":"아시안 마트 또는 한약재상"}}},{"id":"whole-garlic","name":{"zh-TW":"整顆大蒜帶皮 (洗淨不剝瓣)","en":"Whole Garlic Bulbs (Skin-on, washed)","ms":"Bawang Putih Bulat (Cuci Bersih)","ja":"丸ごと皮付きニンニク（皮ごと洗う）","ko":"통마늘 껍질째 (깨끗이 세척)"},"amount":3,"unitMetric":"piece","unitUS":"3 whole heads","isKeyFlavor":true,"malayName":"Bawang Putih Bulat","malayPronunciation":"Bah-wahng Poo-teeh Boo-laht"},{"id":"thick-dark-soy","name":{"zh-TW":"大馬老老字號黑醬油 (晒油)","en":"Thick Caramel Dark Soy Sauce (Sai Yau)","ms":"Kicap Pekat Karamel Manisan","ja":"マレーシア濃厚カラメル黒醤油","ko":"말레이시아 전통 흑간장 (사이유)"},"amount":35,"unitMetric":"ml","unitUS":"2.5 tbsp","isKeyFlavor":true,"malayName":"Kicap Pekat","malayPronunciation":"Kee-chahp Peh-kaht"},{"id":"light-soy-sauce","name":{"zh-TW":"特級釀造生抽醬油","en":"Premium Light Soy Sauce","ms":"Kicap Cair Manis Wangi","ja":"特選生醤油","ko":"양조 진간장"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":false,"malayName":"Kicap Cair","malayPronunciation":"Kee-chahp Chah-eer"},{"id":"oyster-sauce","name":{"zh-TW":"舊庄蠔油","en":"Premium Oyster Sauce","ms":"Sos Tiram Pekat","ja":"オイスターソース","ko":"굴소스"},"amount":20,"unitMetric":"ml","unitUS":"1.5 tbsp","isKeyFlavor":false,"malayName":"Sos Tiram","malayPronunciation":"Sohs Tee-rahm"},{"id":"tofu-puffs","name":{"zh-TW":"油豆腐角 (豆腐卜 / 切半)","en":"Fried Tofu Puffs (Tauhu Pok, halved)","ms":"Tauhu Pok Goreng","ja":"油揚げ・厚揚げ（豆腐卜）","ko":"유부 조각 (타우후 뽁)"},"amount":8,"unitMetric":"piece","unitUS":"8 pcs","isKeyFlavor":false,"malayName":"Tauhu Pok","malayPronunciation":"Tah-oo-hoo Pohk"},{"id":"button-mushrooms","name":{"zh-TW":"鮮香菇或金針菇","en":"Fresh Shiitake or Enoki Mushrooms","ms":"Cendawan Shiitake / Enoki","ja":"生椎茸またはエノキタケ","ko":"신선한 표고버섯 또는 팽이버섯"},"amount":6,"unitMetric":"piece","unitUS":"6 pcs","isKeyFlavor":false,"malayName":"Cendawan","malayPronunciation":"Chehn-dah-wahn"},{"id":"youtiao","name":{"zh-TW":"金黃香酥油條 (切段沾湯)","en":"Crispy Fried Dough Fritters (Youtiao / Cakoi)","ms":"Cakoi Rangup Potong","ja":"中華揚げパン（油条・ヤウチャアクワイ）","ko":"바삭한 중화식 꽈배기 튀김 (유탸오)"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":true,"malayName":"Cakoi","malayPronunciation":"Chah-koy"}],"steps":[{"stepNumber":1,"image":"/images/my/bak-kut-teh-step1.jpg","title":{"zh-TW":"排骨汆燙血水與清洗","en":"Blanch Pork Ribs to Purify Broth Base","ms":"Celur Rusuk Daging Bersih","ja":"豚スペアリブを湯通ししてアクを抜く","ko":"돼지갈비 데쳐서 핏물 제거하기"},"instruction":{"zh-TW":"排骨冷水下鍋，加入 2 匙料酒與薑片。大火煮沸後浮沫湧出，持續滾煮 3 分鐘。撈出排骨在流動溫水下徹底洗淨骨渣與血污，瀝乾備用。如此熬出的肉骨茶湯清澈純厚無腥氣。","en":"Place pork ribs in cold pot with 2 tbsp cooking wine. Bring to full boil over high heat, skimming off scum for 3 mins. Drain and rinse ribs thoroughly under warm running water to remove impurities.","ms":"Rebus rusuk dalam air sejuk bersama halia hingga mendidih selama 3 minit. Buang buih kotor, angkat dan cuci bersih dengan air suam.","ja":"鍋に豚肉、水、料理酒、生姜を入れ強火にかけます。沸騰後3分間アクをしっかり取り除き、肉を取り出してぬるま湯で綺麗に洗います。","ko":"찬물에 돼지갈비와 청주, 생강을 넣고 끓입니다. 끓어오르면 3분간 거품을 걷어낸 후 갈비를 건져 미온수에 깨끗이 헹궈냅니다."},"durationSeconds":360},{"stepNumber":2,"image":"/images/my/bak-kut-teh-step2.jpg","title":{"zh-TW":"瓦煲下藥膳與帶皮蒜頭釋放醇香","en":"Simmer Herbal Sachet & Whole Garlic Bulbs in Claypot","ms":"Reneh Herba & Bawang Putih Dalam Periuk Tanah","ja":"土鍋に薬膳パックと丸ごとニンニクを入れて煮出す","ko":"뚝배기에 한약재 팩과 통마늘 넣고 우려내기"},"instruction":{"zh-TW":"深鍋或砂鍋中倒入 1600ml 清水，放入肉骨茶藥膳包與 3 整顆洗淨的帶皮大蒜。大火燒滾後轉中小火蓋蓋熬煮 15 分鐘，直至湯水轉為透亮的紅褐色，當歸與川芎甘醇香氣瀰漫全屋。","en":"In claypot or deep soup pot, bring 1600ml water to rolling boil. Add herbal spice pack and 3 whole washed garlic heads (skin-on). Simmer covered on medium-low for 15 mins until the water transforms into an aromatic crimson amber broth.","ms":"Didihkan 1600ml air dalam periuk tanah. Masukkan pek herba dan 3 labu bawang putih bulat. Reneh bertutup 15 minit sehingga kuah berwarna perang gelap harum.","ja":"土鍋に水1600ml、薬膳パック、皮付きニンニク3玉を入れ沸騰させます。中弱火で15分煮込み、当帰や川芎の甘く深い香りをしっかり引き出します。","ko":"뚝배기에 물 1600ml, 한방 팩, 껍질째 씻은 통마늘 3개를 넣고 끓입니다. 중약불로 15분간 끓여 붉은빛 한방 육수를 우려냅니다."},"durationSeconds":900,"crucialTips":{"zh-TW":"大蒜千萬不要剝皮！整顆帶皮大蒜慢燉會化為奶油般軟糯香甜，且能保持湯頭清透不混濁。","en":"Never peel the garlic! The papery skin keeps the cloves intact, melting them into sweet garlic butter without clouding the broth.","ms":"Jangan kopek kulit bawang putih! Kulit mengekalkan bentuk bawang agar menjadi lembut berkrim tanpa mengeruhkan kuah.","ja":"ニンニクの薄皮は剥かないでください！皮ごと煮込むことで煮崩れを防ぎ、スープを濁らせずに甘みを引き出せます。","ko":"통마늘 껍질을 절대 벗기지 마세요! 껍질째 끓여야 마늘이 으깨지지 않고 크림처럼 부드러워지며 국물이 맑게 유지됩니다."}},{"stepNumber":3,"image":"/images/my/bak-kut-teh-step3.jpg","title":{"zh-TW":"下肉骨慢火醇煨與調色調味","en":"Slow-Braise Pork Ribs with Dark Soy Sauce & Seasonings","ms":"Masukkan Daging, Renjis Kicap Pekat & Reneh Empuk","ja":"スペアリブを投入し黒醤油でじっくり煮込む","ko":"갈비 투하 후 흑간장 양념하여 푹 끓이기"},"instruction":{"zh-TW":"將洗淨的排骨放入沸騰藥膳湯中。調入黑醬油 35ml、生抽 30ml、蠔油 20ml、冰糖 10g 與 1/2 茶匙白胡椒粉。大火煮沸後轉微火，加蓋慢燉 50-60 分鐘，直到排骨肉質軟嫩至能輕易骨肉分離。","en":"Add blanched ribs into simmering herbal broth. Stir in thick dark soy sauce (35ml), light soy (30ml), oyster sauce (20ml), rock sugar (10g) and white pepper. Simmer covered on low heat for 50-60 mins until meat is meltingly tender and slips off bone with chopstick pressure.","ms":"Masukkan rusuk daging ke dalam kuah. Tambah kicap pekat karamel, kicap cair, sos tiram, gula batu dan lada putih. Reneh api kecil 50-60 minit sehingga daging empuk tercabut tulang.","ja":"肉を加え、黒醤油35ml、薄口醤油30ml、オイスターソース20ml、氷砂糖、白胡椒を入れます。極弱火で蓋をして50〜60分コトコト煮込み、骨から肉がするりと外れる柔らかさにします。","ko":"갈비를 넣고 흑간장 35ml, 진간장 30ml, 굴소스 20ml, 빙탕 10g, 백후추를 넣습니다. 뚜껑을 덮고 약불에서 50-60분간 푹 조려 고기가 부드럽게 뼈에서 분리되도록 합니다."},"durationSeconds":3300,"cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Meat/Stew Mode 25 mins + 15 mins Natural Release","instructionOverride":{"zh-TW":"電子壓力鍋模式：全部食材與醬料入內膽，水量減至 1200ml。高壓 25 分鐘後自然洩壓，省時一半且骨肉入口即化！","en":"Instant Pot: Reduce water to 1200ml. High Pressure 25 mins + Natural Release 15 mins. Immense time saver with fall-apart texture!","ms":"Periuk Tekanan: Kurangkan air ke 1200ml. Tekanan tinggi 25 minit, biarkan wap keluar sendiri.","ja":"電気圧力鍋：水を1200mlに減らし、高圧25分＋自然減圧15分。半分の時間でとろける柔らかさに。","ko":"인스턴트팟: 물을 1200ml로 줄이고 고압 25분 + 자연 김빼기 15분. 시간이 절반으로 단축됩니다!"}}]},{"stepNumber":4,"image":"/images/my/bak-kut-teh-step4.jpg","title":{"zh-TW":"入油豆腐鮮菇吸汁・盛裝油條上桌","en":"Simmer Tofu Puffs & Serve with Crispy Youtiao","ms":"Masukkan Tauhu Pok, Cendawan & Hidang Bersama Cakoi","ja":"油揚げとキノコを加えて仕上げ、油条を添えて完成","ko":"유부와 버섯 넣어 한소끔 끓이고 유탸오 곁들여 완성"},"instruction":{"zh-TW":"起鍋前 8 分鐘，放入切半油豆腐（豆腐卜）與鮮香菇。蓋蓋讓油豆腐像海綿般吸飽黑濃肉骨湯汁。撒上一把香菜與白胡椒粉。桌旁備好切段酥脆油條、生抽切片指天椒碎，沾著吃、淋著喝，身心溫暖暢快！","en":"In final 8 mins, drop in halved tofu puffs and shiitake mushrooms. Let the puffs sponge up the dark, restorative herbal broth. Garnish with fresh cilantro. Serve alongside sliced golden youtiao fritters and fresh bird’s eye chilies steeped in light soy sauce.","ms":"8 minit sebelum siap, masukkan tauhu pok dan cendawan. Biarkan tauhu pok menyerap kuah herba. Tabur daun ketumbar dan hidang panas bersama cakoi serta cili padi kicap.","ja":"完成8分前に油揚げと椎茸を加え、スープの旨味をたっぷり吸わせます。パクチーを散らし、カリカリの油条（揚げパン）と刻み唐辛子の醤油ダレを添えて熱々を召し上がれ！","ko":"완성 8분 전 유부와 버섯을 넣어 국물이 듬뿍 배어들게 끓입니다. 고수를 얹고 바삭한 유탸오와 청양고추 간장 소스를 곁들여 서빙합니다."},"durationSeconds":480}],"troubleshooting":[{"id":"soup-bitter","problem":{"zh-TW":"肉骨茶湯頭苦澀味太重","en":"Broth tastes harsh and overly medicinal bitter","ms":"Kuah terlalu pahit herba","ja":"スープの苦味が強すぎる","ko":"국물에서 쓴맛이 너무 강하게 남"},"cause":{"zh-TW":"藥材包浸泡滾煮時間過長，或當歸比例過高","en":"Herb pack boiled too long or excessive dang gui","ms":"Rempah herba direbus terlalu lama","ja":"薬膳パックを長時間煮込みすぎた","ko":"약재 팩을 너무 오래 끓였거나 당귀 함량이 높음"},"solution":{"zh-TW":"熬煮 40 分鐘後可先將藥材包撈出丟棄；加入 1 塊冰糖與 1 大匙黑醬油可完美中和回甘。","en":"Remove herb sachet after 40 mins; add a cube of rock sugar and splash of thick sweet soy to balance sweetness.","ms":"Keluarkan pek herba selepas 40 minit dan tambahkan seketul gula batu.","ja":"煮込み始めて40分でパックを取り出してください。氷砂糖を1粒足すとまろやかな甘みが戻ります。","ko":"40분 정도 끓인 뒤 약재 팩을 먼저 건져내고, 빙탕 한 조각을 넣어 은은한 단맛으로 조화롭게 맞추세요."}}],"proTips":[{"zh-TW":"正宗巴生人吃法：桌上必有一壺濃滾滾的熱鐵觀音或普洱茶！吃完肥腴軟爛的豬肉骨，喝一口深黑藥膳湯，再呷一口苦甘熱茶，生津解膩、通體舒暢。油條務必浸入湯中 3 秒撈起，外酥內爆汁！","en":"Klang Tradition: Always pair Bak Kut Teh with a piping hot pot of Tie Guan Yin or Pu-erh tea! Dip youtiao for exactly 3 seconds so the exterior stays crisp while the inside erupts with herbal gold.","ms":"Tradisi Klang Asli: Nikmati bersama secawan teh Cina pekat panas untuk membuang lemak. Celup cakoi selama 3 saat sahaja agar rangup di luar dan berjus di dalam!","ja":"クラン流の作法：必ず熱々の鉄観音茶やプーアル茶と一緒にいただきます。脂の乗った豚肉を食べた後、濃厚スープをすすり、熱い茶を飲むのが最高の解毒＆消化促進。油条はスープに3秒だけ浸して食べるのが至高！","ko":"클랑 현지식 전통: 바쿠테는 언제나 뜨거운 철관음차나 보이차와 함께 즐깁니다! 유탸오는 국물에 딱 3초만 담갔다 건져 겉은 바삭하고 속은 국물을 머금은 상태로 드세요!"}]},{"country":"my","id":"penang-asam-laksa","slug":"penang-asam-laksa","title":{"zh-TW":"檳城極品亞參叻沙","en":"Penang Tangy Asam Laksa","ms":"Asam Laksa Ikan Kembung Pulau Pinang","ja":"ペナン名物・アッサムラクサ（酸辛魚スープ米麺）","ko":"페낭 아삼 락사 (새콤매콤 생선 쌀국수)"},"subtitle":{"zh-TW":"甘榜魚酸辣濃湯・粉紅火炬薑花香・濃黑蝦膏提鮮","en":"Mackerel Tamarind Broth, Torch Ginger Flower & Fermented Shrimp Molasses","ms":"Kuah Asam Ikan Pekat, Bunga Kantan Harum & Petis Udang Pekat","ja":"鯖とタマリンドの濃厚酸辛スープ、トーチジンジャーの香りと特濃海老ペースト","ko":"고등어 타마린드 육수, 토치 진저 꽃의 향과 진한 새우장(헤코)"},"tagline":{"zh-TW":"CNN 評選全球 50 大美食第 7 名！娘惹酸辣開胃極致藝術","en":"Ranked #7 on CNN’s World’s 50 Best Foods! The supreme zenith of Peranakan sour-spicy noodles","ms":"Tersohor di tangga ke-7 Makanan Terbaik Dunia CNN! Kesenian rasa masam pedas terulung","ja":"CNN世界美食ランキング第7位！ババ・ニョニャが育んだ酸辛の至宝","ko":"CNN 선정 세계 50대 음식 7위! 페라나칸 문화가 낳은 최고의 새콤매콤한 걸작"},"heroImage":"/images/my/penang-asam-laksa.jpg","difficulty":"hard","prepTimeMinutes":30,"cookTimeMinutes":45,"defaultServings":2,"caloriesPerServing":480,"category":"noodles","dietaryTags":["classic","pescatarian","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"北馬・檳城亞依淡 (Air Itam, Penang)","en":"Penang / Air Itam","ms":"Air Itam, Pulau Pinang","ja":"ペナン・極楽寺アイルイタム","ko":"페낭 / 에어 이탐"},"famousStreetMarkets":[{"zh-TW":"檳城極樂寺山腳亞依淡巴剎","en":"Air Itam Pasar Laksa (Kek Lok Si Temple), Penang","ms":"Pasar Air Itam Laksa","ja":"アイルイタム市場ラクサ","ko":"에어 이탐 시장 락사"},{"zh-TW":"檳城汕頭街","en":"Kimberley Street Penang","ms":"Lebuh Kimberley","ja":"キンバリー通り","ko":"킴벌리 거리"}],"historyStory":{"zh-TW":"大馬娘惹文化的巔峰結晶。早期沿海漁民將盛產的鯖魚（甘榜魚 / Ikan Kembung）拆骨碎肉，與羅望子、亞參果片（Asam Gelugur）、火炬薑花（Bunga Kantan）及水蓼叻沙葉同熬，誕生了酸甜微辛、鮮美衝擊的獨特魚湯。盛碗時淋上一勺黑如濃墨的「蝦膏 / 蝦膏油 (Hae Ko)」，鹹鮮回甘，令人神魂顛倒。","en":"The crown jewel of Penang Peranakan cuisine. Coastal fisherfolk flaked poached wild mackerel and simmered it with tamarind pulp, asam gelugur peel, torch ginger buds (bunga kantan) and laksa mint. Finished with a spoonful of black fermented sweet shrimp paste (Hae Ko).","ms":"Kemuncak warisan Nyonya Pulau Pinang. Isi ikan kembung segar direbus bersama asam jawa, asam gelugur, daun kesum dan bunga kantan. Dihidang bersama petis udang likat yang memikat selera.","ja":"ペナンのニョニャ（華人とマレーの混血）文化の最高傑作。新鮮なサバをほぐし、タマリンド、アサム・フルグラ、トーチジンジャー、ラクサリーフで煮込んだ酸味と辛みが融合した極上魚介スープ。黒い特濃エビ味噌（ヘーコー）を溶かして食すのが本場流。","ko":"페낭 페라나칸 문화의 정수. 신선한 고등어를 으깨어 타마린드, 아삼 젤루구르, 생강꽃 봉오리, 락사 잎과 함께 끓여낸 중독성 있는 국물입니다. 먹기 전 달콤 짭조름한 흑새우 페이스트를 풀어먹습니다."},"malayScript":"Asam Laksa Pulau Pinang","malayPhonetics":"Ah-sahm Lahk-sah Poo-lah-oo Pee-nahng","audioPronunciationText":"Boss, Asam Laksa satu mangkuk, petis udang taruk lebih ya!","communityHeritage":"Peranakan","nativeName":"Asam Laksa Pulau Pinang","nativePhonetics":"Asam Laksa Pulau Pinang"},"ingredients":[{"id":"mackerel-fish","name":{"zh-TW":"新鮮鯖魚或甘榜魚 (去骨撕粗碎肉)","en":"Fresh Mackerel or Sardines (Ikan Kembung, flaked)","ms":"Ikan Kembung Segar Rebus","ja":"新鮮なサバまたはアジ（骨抜き粗ほぐし肉）","ko":"신선한 고등어 (가시 발라 굵게 찢은 살)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"malayName":"Ikan Kembung","malayPronunciation":"Ee-kahn Kehm-boong"},{"id":"laksa-noodles","name":{"zh-TW":"粗圓米粉 (瀨粉 / 叻沙粉)","en":"Thick Round Rice Noodles (Lai Fun / Laksa Noodles)","ms":"Mee Laksa Beras Kasar","ja":"極太丸米麺（ラクサヌードル / ライファン）","ko":"굵은 원형 쌀국수 면 (락사 누들)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":false,"malayName":"Mee Laksa","malayPronunciation":"Mee Lahk-sah"},{"id":"tamarind-pulp","name":{"zh-TW":"天然羅望子膏 (Asam Jawa) 兌溫水出濃汁","en":"Tamarind Pulp (Asam Jawa) strained into liquid","ms":"Air Asam Jawa Pekat","ja":"タマリンドペースト（ぬるま湯で揉み出した果汁）","ko":"타마린드 펄프 (미온수에 푼 농축액)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":true,"malayName":"Air Asam Jawa","malayPronunciation":"Ah-yeer Ah-sahm Jah-wah"},{"id":"asam-keping","name":{"zh-TW":"南洋亞參果乾片 (Asam Gelugur)","en":"Dried Garcinia Atroviridis Slices (Asam Gelugur / Keping)","ms":"Asam Keping / Gelugur","ja":"アサム・クピン（乾燥ガルシニア果皮片）","ko":"아삼 크핑 (말린 가르시니아 조각)"},"amount":4,"unitMetric":"piece","unitUS":"4 slices","isKeyFlavor":true,"malayName":"Asam Keping","malayPronunciation":"Ah-sahm Keh-peeng"},{"id":"torch-ginger","name":{"zh-TW":"粉紅火炬薑花苞 (切半與切細絲)","en":"Torch Ginger Flower Bud (Bunga Kantan, sliced)","ms":"Bunga Kantan Wangi","ja":"トーチジンジャーの蕾（ブンガ・カンタン・細切り）","ko":"토치 진저 꽃 봉오리 (붕가 칸탄, 채 썬 것)"},"amount":1,"unitMetric":"stalk","unitUS":"1 bud","isKeyFlavor":true,"malayName":"Bunga Kantan","malayPronunciation":"Boon-gah Kahn-tahn"},{"id":"daun-kesum","name":{"zh-TW":"新鮮叻沙葉 (水蓼 / Daun Kesum)","en":"Fresh Laksa Leaves (Vietnamese Mint / Daun Kesum)","ms":"Daun Kesum Segar","ja":"生ラクサリーフ（ベトナムミント）","ko":"신선한 락사 리프 (다운 크숨)"},"amount":30,"unitMetric":"g","unitUS":"1 oz","isKeyFlavor":true,"malayName":"Daun Kesum","malayPronunciation":"Dah-oon Keh-soom"},{"id":"belacan-sambal-paste","name":{"zh-TW":"紅蔥頭、乾辣椒、香茅、烤 Belacan 辛香醬","en":"Spice Paste: Shallots, chilies, lemongrass, toasted belacan","ms":"Pes Rempah Kisar (Bawang, Cili, Serai, Belacan)","ja":"香辛ペースト（エシャロット、唐辛子、レモングラス、ブラチャン）","ko":"향신 페이스트 (샬롯, 고추, 레몬그라스, 벨라찬)"},"amount":120,"unitMetric":"g","unitUS":"4 oz","isKeyFlavor":true,"malayName":"Rempah Kisar","malayPronunciation":"Rehm-pah Kee-sahr"},{"id":"hae-ko","name":{"zh-TW":"檳城極品黑蝦膏 (Hae Ko / Petis Udang)","en":"Penang Fermented Thick Shrimp Molasses (Hae Ko / Petis Udang)","ms":"Petis Udang / Otak Udang Asli Pulau Pinang","ja":"ペナン特産・濃厚発酵黒エビペースト（ヘーコー）","ko":"페낭 발효 흑새우 진액 (헤코 / 쁘티스 우당)"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"malayName":"Petis Udang","malayPronunciation":"Peh-tees Oo-dahng"},{"id":"toppings-garnish","name":{"zh-TW":"配菜：鳳梨切丁、黃瓜切絲、紅洋蔥絲、生薄荷葉","en":"Garnish: Diced fresh pineapple, julienned cucumber, mint & onion","ms":"Ulaman: Nanas, timun, bawang merah dan daun pudina","ja":"トッピング：角切りパイナップル、千切りきゅうり、赤玉ねぎ、ミント","ko":"고명: 깍둑썬 파인애플, 오이채, 적양파채, 신선한 민트"},"amount":150,"unitMetric":"g","unitUS":"5 oz","isKeyFlavor":false,"malayName":"Ulaman Segar","malayPronunciation":"Oo-lah-mahn Seh-gahr"}],"steps":[{"stepNumber":1,"image":"/images/my/penang-asam-laksa-step1.jpg","title":{"zh-TW":"煮熟鯖魚・拆取粗肉與熬煮魚骨鮮湯","en":"Poach Mackerel, Flake Flesh & Simmer Fish Bone Stock","ms":"Rebus Ikan Kembung, Asingkan Tulang & Ambil Stok","ja":"サバを茹でて骨を外し、魚骨スープを煮出す","ko":"고등어 데쳐서 살을 바르고 생선 뼈 육수 내기"},"instruction":{"zh-TW":"鍋中加水 1500ml 煮沸，放入整條洗淨的鮮鯖魚與 2 片亞參果乾片。水滾煮 8 分鐘至魚肉熟透，撈出魚放涼。將魚肉粗撕成塊狀留存，魚頭魚骨丟回原湯中，用勺背稍微搗爛骨髓，加蓋小火熬煮 15 分鐘，過濾出極其鮮濃的魚高湯備用。","en":"Boil 1500ml water with 2 slices of asam gelugur. Gently poach whole mackerel for 8 mins until cooked. Lift fish out to cool. Flake off tender meat into rough bite-sized chunks. Toss heads and bones back into stock, crush slightly with spoon to release marrow, simmer 15 mins and strain.","ms":"Didihkan 1500ml air bersama 2 keping asam keping. Rebus ikan kembung 8 minit hingga masak. Angkat dan asingkan isi kasar. Masukkan semula tulang ke dalam air rebusan, reneh 15 minit dan tapis kuahnya.","ja":"水1500mlに乾燥アサム果皮を入れサバを8分茹でます。魚を取り出して粗くほぐし、頭と骨を鍋に戻して15分煮込んで漉し、濃厚な魚出汁を作ります。","ko":"물 1500ml에 아삼 조각 2개를 넣고 고등어를 8분간 삶아 건집니다. 살은 큼직하게 바르고, 머리와 뼈는 냄비에 다시 넣어 15분간 더 끓인 뒤 체에 걸러 진한 육수를 만듭니다."},"durationSeconds":1380},{"stepNumber":2,"image":"/images/my/penang-asam-laksa-step2.jpg","title":{"zh-TW":"香料辣椒醬入鍋與草本慢熬酸辣魚湯","en":"Infuse Spice Paste, Tamarind & Herbs into Tangy Broth","ms":"Tumis Pes Rempah & Reneh Bersama Daun Kesum & Bunga Kantan","ja":"スパイスペーストとタマリンド、ハーブを加えて煮込む","ko":"향신 페이스트, 타마린드와 허브 넣어 깊게 끓이기"},"instruction":{"zh-TW":"將過濾好的魚高湯倒回大鍋中。加入研磨好的辛香辣椒醬、濃羅望子酸汁（Asam Jawa）、其餘亞參果片、整株切半的火炬薑花及整大把新鮮叻沙葉（Daun Kesum）。大火煮沸後轉小火滾燉 25 分鐘，滿屋飄散出如甘露般的酸草清香！加入撕碎的鯖魚肉再慢熬 10 分鐘，加 1 大匙糖與 1 茶匙鹽調和酸鹹度。","en":"Pour strained fish broth back into pot. Stir in blended spice paste, concentrated tamarind liquid, remaining asam gelugur, halved torch ginger buds, and a huge handful of fresh laksa leaves (daun kesum). Simmer over medium-low for 25 mins until herbs perfume the broth. Add flaked mackerel back in for 10 mins; season with 1 tbsp sugar and salt.","ms":"Tuang stok ikan ke dalam periuk. Masukkan pes rempah cili, air asam jawa, daun kesum dan bunga kantan. Reneh 25 minit. Masukkan isi ikan kembung kasar, gula dan garam.","ja":"魚出汁を鍋に戻し、ペースト、タマリンド汁、トーチジンジャー、たっぷりのラクサリーフを投入。25分煮込んでハーブの香りを移し、ほぐしたサバ肉を戻してさらに10分煮込みます。","ko":"생선 육수에 향신 페이스트, 타마린드 즙, 반으로 가른 토치 진저 꽃, 락사 잎을 듬뿍 넣고 25분간 끓입니다. 바른 고등어 살을 다시 넣고 10분간 더 조린 뒤 설탕과 소금으로 간을 맞춥니다."},"durationSeconds":2100,"crucialTips":{"zh-TW":"火炬薑花（Bunga Kantan）與叻沙葉（Daun Kesum）是不可取代的靈魂草本，能徹底降伏鯖魚的野性油脂，轉化為神級清甜！","en":"Torch ginger and laksa mint are strictly non-negotiable! Their volatile citrus-pepper oils neutralize oily fish notes into pure refreshing nectar.","ms":"Bunga kantan dan daun kesum adalah jiwa Asam Laksa yang tidak boleh diganti untuk menghilangkan hanyir ikan.","ja":"トーチジンジャーとラクサリーフは必須の命！これらが青魚特有のクセを完全に消し去り、爽快な旨味へと昇華させます。","ko":"토치 진저 꽃과 락사 리프는 대체 불가능한 핵심 허브입니다! 고등어의 비린 맛을 지우고 청량한 감칠맛으로 바꿔줍니다."}},{"stepNumber":3,"image":"/images/my/penang-asam-laksa-step3.jpg","title":{"zh-TW":"燙粗米粉・盛裝配料淋熱湯","en":"Blanch Thick Rice Noodles & Garnish Platter","ms":"Celur Mee Laksa & Susun Ulaman Segar","ja":"太米麺を茹で、フレッシュな具材と熱々スープをかける","ko":"굵은 쌀국수 데쳐 그릇에 담고 고명 올리기"},"instruction":{"zh-TW":"滾水中放入粗瀨粉燙熱 30 秒，撈起瀝乾放入大湯碗。在粉條上排上新鮮黃瓜絲、鳳梨切丁、紅洋蔥絲與新鮮薄荷葉。舀入滾燙、滿載鯖魚碎肉的紅褐色亞參酸辣魚湯，澆滿粉碗！","en":"Blanch thick rice noodles in boiling water for 30 secs, drain and place into deep bowl. Layer fresh cucumber batons, sweet diced pineapple, purple onion slivers and aromatic mint leaves over noodles. Ladle bubbling, mackerel-packed amber asam broth all over.","ms":"Celur mee laksa 30 saat, toskan ke dalam mangkuk. Susun timun, nanas manis, bawang dan daun pudina. Sendukkan kuah asam laksa panas bersama isi ikan ke atas mee.","ja":"太米麺を30秒湯通しして丼へ。千切りきゅうり、角切りパイナップル、赤玉ねぎ、生ミントを乗せ、サバの身がたっぷり入った熱々の酸辛スープを注ぎます。","ko":"굵은 쌀국수를 끓는 물에 30초간 데쳐 그릇에 담습니다. 오이채, 파인애플, 적양파, 민트 잎을 얹고 고등어 살이 가득한 뜨거운 아삼 육수를 붓습니다."},"durationSeconds":120},{"stepNumber":4,"image":"/images/my/penang-asam-laksa-step4.jpg","title":{"zh-TW":"點睛一勺檳城黑蝦膏 (Hae Ko) 攪勻開吃","en":"Crown with Penang Hae Ko Shrimp Molasses & Slurp","ms":"Titik Petis Udang Pekat & Nikmati Panas","ja":"仕上げに黒エビペーストをひとさじ落として完成","ko":"페낭 흑새우 페이스트(헤코)를 한 스푼 얹어 완성"},"instruction":{"zh-TW":"吃亞參叻沙的最高儀式：在熱湯中央挖入一大茶匙濃黑亮澤的檳城發酵蝦膏（Hae Ko）。用筷子將蝦膏緩緩在酸湯中攪化開來——原本偏酸的魚湯瞬間化為甘醇厚重、深邃海味的極致甘露！大口啜吸彈牙米粉，暢快淋漓！","en":"The golden finale: Plop a glossy tablespoon of sweet black shrimp molasses (Hae Ko) right into the piping bowl. Swirl it into the soup with chopsticks—the pungent molasses mellows the tart acid into a mesmerizing, addictive umami bomb!","ms":"Kemuncak rasa: Letakkan sesudu petis udang likat di tengah mangkuk. Kacau perlahan bersama kuah asam panas untuk membangkitkan rasa lemak manis yang mengasyikkan!","ja":"最高の瞬間：黒く艶めく特濃エビペースト（ヘーコー）をスプーンひとさじ落とします。お箸で熱いスープに溶かし込むと、酸味がまろやかになり驚異的なコクと深みが爆発します！","ko":"하이라이트: 달콤하고 쫀득한 흑새우 페이스트(헤코)를 한 숟갈 얹습니다. 젓가락으로 국물에 살살 풀어내면 새콤한 국물에 극강의 감칠맛이 더해집니다!"},"durationSeconds":30}],"troubleshooting":[{"id":"fishy-smell","problem":{"zh-TW":"魚湯腥味明顯","en":"Fish broth tastes unpleasantly fishy","ms":"Kuah berbau hanyir ikan","ja":"スープに生臭さが残る","ko":"생선 비린내가 남"},"cause":{"zh-TW":"鯖魚未去內臟洗淨，或未加足羅望子與亞參片果酸壓制","en":"Fish innards not cleaned thoroughly or lack of tamarind acidity","ms":"Ikan tidak dicuci bersih atau kurang asam","ja":"内臓の下処理不足、またはタマリンドの酸味不足","ko":"생선 내장 손질이 미흡했거나 산미가 부족함"},"solution":{"zh-TW":"確保去除鯖魚腹內黑膜；熬湯時多補 1 片亞參果乾片與 1 大匙羅望子濃汁，果酸能瞬間分解三甲胺魚腥。","en":"Scrape black membrane from fish belly; add 1 extra asam keping slice and fresh lime juice to neutralize amines.","ms":"Buang darah beku dalam perut ikan dan tambah lebih asam keping.","ja":"腹の内側の黒い薄膜を綺麗に洗い落とし、タマリンド果汁を足して酸で臭みを中和してください。","ko":"생선 내장의 검은 막을 깨끗이 긁어내고, 아삼 조각과 타마린드 즙을 조금 더 넣어 산미로 비린내를 잡으세요."}}],"proTips":[{"zh-TW":"老饕鑑定守則：黑蝦膏（Hae Ko / Petis Udang）絕對不能省！沒有這勺蝦膏，它只是一碗酸魚湯；一旦拌入黑蝦膏，才是名震全球的檳城亞參叻沙！","en":"Penang Hawker Law: Never skip the Hae Ko (Petis Udang)! Without this fermented black shrimp molasses, it’s just sour fish water. The moment you swirl it in, it becomes the world-conquering Asam Laksa.","ms":"Undang-undang Penang: Jangan sesekali tinggalkan Petis Udang! Tanpa cecair likat ini, ia hanyalah sup ikan masam biasa. Petis udang inilah yang mencipta magis keagungan Asam Laksa!","ja":"ペナン屋台の鉄則：黒エビペースト（ヘーコー）は絶対に抜かないでください！これを溶かす前と後で味が180度激変し、世界の美食へと完成します。","ko":"페낭 현지인의 철칙: 흑새우 페이스트(헤코)는 절대 빠뜨리면 안 됩니다! 이 한 스푼이 들어가야 비로소 평범한 생선탕이 세계적인 아삼 락사로 완성됩니다."}]},{"country":"my","id":"curry-laksa","slug":"curry-laksa","title":{"zh-TW":"娘惹濃香咖哩叻沙","en":"Rich Nyonya Curry Laksa","ms":"Kari Laksa Santan Nyonya Berkrim","ja":"濃厚ニョニャ・カレーラクサ（ココナッツカレー麺）","ko":"진한 뇨냐 커리 락사 (코코넛 커리 쌀국수)"},"subtitle":{"zh-TW":"黃金椰漿咖哩湯・吸汁豆腐卜・鮮蝦嫩雞鮮血蛤雙拼麵","en":"Creamy Coconut Curry Broth, Tofu Puffs, Prawns, Shredded Chicken & Yellow Mee","ms":"Kuah Kari Santan Pekat, Tauhu Pok Berjus, Udang Manis & Mee Hoon Campur","ja":"黄金ココナッツカレースープ、旨味を吸った油揚げ、エビと蒸し鶏の合盛り麺","ko":"황금빛 코코넛 커리 육수, 국물을 머금은 유부, 새우와 닭고기 생면"},"tagline":{"zh-TW":"孤獨星球 Lonely Planet 評選全球第二大美食體驗！南洋椰奶咖哩極致饗宴","en":"Ranked #2 on Lonely Planet’s Ultimate Eatlist! The quintessential coconut noodle broth","ms":"Tempat ke-2 dalam Lonely Planet Ultimate Eatlist! Kehangatan rempah santan yang memikat","ja":"ロンリープラネット世界究極の食体験第2位！ココナッツとスパイスの至福の一杯","ko":"론리플래닛 세계 미식 버킷리스트 2위! 코코넛 밀크와 향신료의 완벽한 하모니"},"heroImage":"/images/my/curry-laksa.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":35,"defaultServings":2,"caloriesPerServing":640,"category":"noodles","dietaryTags":["classic","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"南馬・馬六甲與吉隆坡 (Melaka & KL)","en":"Melaka & Kuala Lumpur","ms":"Melaka & Kuala Lumpur","ja":"マラッカおよびクアラルンプール","ko":"말라카 & 쿠알라룸푸르"},"famousStreetMarkets":[{"zh-TW":"吉隆坡半山芭大巴剎咖哩麵","en":"ICC Pudu Curry Mee, Kuala Lumpur","ms":"ICC Pudu Curry Laksa","ja":"ICCプドゥ・カレーラクサ","ko":"ICC 푸두 커리 락사"},{"zh-TW":"馬六甲雞場街娘惹老店","en":"Jonker Street Nyonya Laksa, Melaka","ms":"Jonker Walk Laksa Melaka","ja":"ジョンカーストリート・ニョニャラクサ","ko":"존커 워크 뇨냐 락사"}],"historyStory":{"zh-TW":"明代鄭和下西洋後，華人移民與馬來原住民通婚誕生了「娘惹文化」。娘惹主婦將南印度的芳香咖哩辛香料，融入南洋盛產的濃醇椰漿、石栗與香茅，創造出金黃誘人、香氣撲鼻的咖哩叻沙。大馬傳統習慣將油麵（Mee）與米粉（Bee Hoon）以「米粉麵雙拼」一同入碗，雙重口感無懈可擊。","en":"Born from 15th-century maritime trade intermarriages between Chinese settlers and indigenous Malays. Nyonya matrons wedded Indian curry spices with luscious local coconut milk, lemongrass, candlenuts and fresh seafood. Traditionally served with \"Mee Hoon + Mee\" (mixed rice vermicelli and yellow egg noodles) for contrast.","ms":"Hasil pertembungan budaya Baba Nyonya kurun ke-15. Gabungan rempah ratus kari, santan kelapa pekat, serai dan buah keras. Lazimnya dihidang dengan mee kuning dan bihun campur.","ja":"15世紀のマラッカ王国時代、華人と現地女性の婚姻から生まれたババ・ニョニャの傑作。インド系カレースパイスと南国の新鮮なココナッツミルクを融合させました。太い中華麺と極細ビーフンを「半々」で合わせるのが大馬流。","ko":"15세기 명나라 정화의 원정 이후 화교와 현지인이 어우러진 뇨냐 문화에서 탄생했습니다. 인도풍 커리 향신료에 풍부한 코코넛 밀크를 더해 고소하면서도 칼칼한 맛을 냅니다."},"malayScript":"Kari Laksa Nyonya","malayPhonetics":"Kah-ree Lahk-sah Nyohn-yah","audioPronunciationText":"Boss, Curry Laksa mee campur bihun satu, kerang lebih, sambal asing!","communityHeritage":"Peranakan","nativeName":"Kari Laksa Nyonya","nativePhonetics":"Kari Laksa Nyonya"},"ingredients":[{"id":"noodle-mix","name":{"zh-TW":"黃麵與米粉各半 (米粉麵雙拼)","en":"Yellow Egg Noodles + Rice Vermicelli (50/50 mix)","ms":"Mee Kuning & Bihun Campur","ja":"黄色い中華麺＆米ビーフン（半々盛り）","ko":"노란 에그누들 + 쌀버미셀리 반반"},"amount":250,"unitMetric":"g","unitUS":"9 oz","isKeyFlavor":false,"malayName":"Mee & Bihun","malayPronunciation":"Mee dahn Bee-hoon"},{"id":"coconut-cream","name":{"zh-TW":"純特濃椰漿 (Santan Pekat)","en":"Rich Pure Coconut Milk (Santan)","ms":"Pati Santan Kelapa Pekat","ja":"濃厚ココナッツミルク","ko":"진한 순수 코코넛 밀크"},"amount":250,"unitMetric":"ml","unitUS":"8.5 fl oz","isKeyFlavor":true,"malayName":"Santan Pekat","malayPronunciation":"Sahn-tahn Peh-kaht"},{"id":"curry-paste-laksa","name":{"zh-TW":"南洋咖哩叻沙香料醬 (紅蔥、蒜、辣椒、薑黃、香茅、石栗、石膏蝦膏)","en":"Laksa Rempah: Shallots, garlic, dried chili, turmeric, lemongrass, candlenut, belacan","ms":"Pes Rempah Kari Laksa Kisar","ja":"ラクサ特製カレースパイスペースト","ko":"락사 커리 렘파 페이스트"},"amount":150,"unitMetric":"g","unitUS":"5 oz","isKeyFlavor":true,"malayName":"Pes Rempah Laksa","malayPronunciation":"Pehs Rehm-pah Lahk-sah"},{"id":"chicken-stock","name":{"zh-TW":"慢熬雞湯或蝦高湯","en":"Rich Chicken or Prawn Stock","ms":"Stok Ayam / Udang","ja":"濃厚チキンまたはエビの出汁","ko":"진한 닭 또는 새우 육수"},"amount":800,"unitMetric":"ml","unitUS":"27 fl oz","isKeyFlavor":false,"malayName":"Stok Ayam","malayPronunciation":"Stohk Ah-yahm"},{"id":"tofu-puffs-laksa","name":{"zh-TW":"炸豆腐卜 (吸湯豆腐泡 / 對半切)","en":"Fried Tofu Puffs (Tauhu Pok, sliced)","ms":"Tauhu Pok Goreng Lembut","ja":"油揚げ（スープが染み込む豆腐卜）","ko":"유부 (국물을 가득 흡수하는 튀김 두부)"},"amount":8,"unitMetric":"piece","unitUS":"8 pcs","isKeyFlavor":true,"malayName":"Tauhu Pok","malayPronunciation":"Tah-oo-hoo Pohk"},{"id":"shredded-chicken","name":{"zh-TW":"水煮滑嫩雞胸肉或雞腿 (撕絲)","en":"Poached Tender Chicken (Shredded)","ms":"Isi Ayam Rebus Carik","ja":"茹で鶏（細かく割いたチキン）","ko":"삶은 닭가슴살/다리살 (결대로 찢은 것)"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":false,"malayName":"Isi Ayam","malayPronunciation":"Ee-see Ah-yahm"},{"id":"fresh-prawns-laksa","name":{"zh-TW":"海白蝦 (川燙去殼留尾)","en":"Plump Sea Prawns (Poached, peeled, tail-on)","ms":"Udang Laut Celur Segar","ja":"茹でエビ（殻むき・尾つき）","ko":"삶은 새우 (껍질 벗기고 꼬리 유지)"},"amount":6,"unitMetric":"piece","unitUS":"6 pcs","isKeyFlavor":false,"malayName":"Udang Celur","malayPronunciation":"Oo-dahng Cheh-loor"},{"id":"calamansi-lime","name":{"zh-TW":"新鮮青金桔 (酸柑 / 擠汁提味)","en":"Fresh Calamansi Limes (Limau Kasturi, halved)","ms":"Limau Kasturi Segar","ja":"カラマンシー（すだちライム・半分切り）","ko":"칼라만시 라임 (반으로 자른 것)"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":true,"malayName":"Limau Kasturi","malayPronunciation":"Lee-mah-oo Kahs-too-ree"}],"steps":[{"stepNumber":1,"image":"/images/my/curry-laksa-step1.jpg","title":{"zh-TW":"慢火煸炒香濃咖哩香料醬 (Rempah Tumis)","en":"Sauté Aromatic Curry Rempah until Fragrant & Oil Separates","ms":"Tumis Pes Rempah Kari Sehingga Pecah Minyak Wangi","ja":"カレースパイスペーストをじっくり炒めて香りを立たせる","ko":"카레 페이스트를 약불에서 볶아 기름 분리시키기"},"instruction":{"zh-TW":"深鍋中倒入 3 大匙油，加入研磨好的咖哩香料醬（Rempah）與拍破的 2 根香茅。中小火慢炒 10-12 分鐘，不斷攪動防止焦鍋，直至水分揮發、表面析出濃紅晶亮的咖哩油，滿室芬芳。","en":"Heat 3 tbsp oil in soup pot over medium-low heat. Add blended curry spice paste and 2 bruised lemongrass stalks. Sauté patiently for 10-12 mins, stirring continuously until the raw spice edge softens and bright red aromatic oil separates on top.","ms":"Panaskan 3 sb minyak. Tumis pes rempah kari dan serai titik atas api sederhana kecil selama 10-12 minit hingga terbit minyak merah yang wangi.","ja":"鍋に油大さじ3を熱し、スパイスペーストと叩いたレモングラスを投入。焦がさないよう弱火で10〜12分じっくり炒め、赤い油が分離するまで香りを引き出します。","ko":"냄비에 기름 3큰술을 두르고 커리 페이스트와 으깬 레몬그라스를 넣습니다. 타지 않게 저어가며 약불에서 10-12분간 붉은 오일이 배어날 때까지 충분히 볶아줍니다."},"durationSeconds":720},{"stepNumber":2,"image":"/images/my/curry-laksa-step2.jpg","title":{"zh-TW":"注入鮮高湯煨煮豆腐卜","en":"Pour in Chicken Stock & Simmer Tofu Puffs","ms":"Tuang Stok Ayam & Masukkan Tauhu Pok Menyerap Kuah","ja":"チキン出汁を注ぎ、油揚げにスープを吸わせる","ko":"닭 육수를 붓고 유부에 국물이 배어들게 끓이기"},"instruction":{"zh-TW":"倒入 800ml 雞高湯（或鮮蝦湯），大火煮沸。轉小火慢滾 15 分鐘讓香料精華完全融解於湯中。放入對半切開的炸豆腐卜，用勺子輕輕下壓，讓豆腐卜如同海綿般吸飽熱辣咖哩湯汁。","en":"Pour in 800ml chicken stock. Bring to rolling boil, then reduce to medium-low simmer for 15 mins to marry flavors. Toss in halved fried tofu puffs, pressing them down lightly so they sponge up the fragrant curry stock.","ms":"Masukkan 800ml stok ayam, didihkan dan reneh 15 minit. Masukkan tauhu pok belah dua dan tekan lembut agar menyerap kuah kari beraroma.","ja":"チキン出汁800mlを注ぎ入れ沸騰させます。弱火で15分煮込んでスパイスを馴染ませ、半分に切った油揚げを投入。スープをたっぷり吸わせます。","ko":"닭 육수 800ml를 붓고 끓어오르면 약불로 줄여 15분간 우려냅니다. 반으로 가른 유부를 넣고 살짝 눌러 커리 육수를 듬뿍 흡수시킵니다."},"durationSeconds":900},{"stepNumber":3,"image":"/images/my/curry-laksa-step3.jpg","title":{"zh-TW":"微火慢入純濃椰漿・調配絲滑黃金湯","en":"Stir in Rich Coconut Milk over Gentle Heat for Silky Emulsion","ms":"Tuang Pati Santan Perlahan & Kawal Api Lembut","ja":"弱火で濃厚ココナッツミルクを注ぎ、まろやかに仕上げる","ko":"약불에서 코코넛 밀크를 부어 부드러운 황금빛 국물 완성"},"instruction":{"zh-TW":"【關鍵秘訣：火力調至微火！】緩緩倒入 250ml 純濃椰漿，順時針輕柔攪拌使其與咖哩油充分乳化。調入 1 茶匙糖與適量海鹽。微滾 3 分鐘即可關火（切勿大火滾沸以免椰漿油水分離結塊！）。","en":"[Crucial Tip: Lower to gentle simmer!] Slowly stream in 250ml pure coconut cream, stirring continuously to create a velvety, golden orange emulsion. Season with 1 tsp sugar and sea salt. Keep at bare simmer for 3 mins, never rapid boil to prevent curdling.","ms":"Kecilkan api. Tuang santan pekat perlahan sambil dikacau rata supaya kuah berkrim cantik. Perasakan dengan garam dan gula. Jangan biarkan mendidih buak agar santan tidak pecah minyak.","ja":"【超重要：弱火に落とすこと！】ココナッツミルク250mlをゆっくり注ぎ、円を描くように優しく混ぜて乳化させます。塩と砂糖で味を調え、沸騰させずに3分温めて火を止めます。","ko":"【핵심 팁: 불을 약하게 줄일 것!】진한 코코넛 밀크 250ml를 천천히 부으며 저어줍니다. 설탕과 소금으로 간을 맞추고, 팔팔 끓이지 않고 은근히 3분간 데워 분리를 방지합니다."},"durationSeconds":240,"dangerWarnings":{"zh-TW":"椰漿加入後絕對不能大火爆滾！否則蛋白質會凝結成白渣、油脂散開，破壞絲絨般滑順口感。","en":"Never boil violently after adding coconut cream! High heat curdles the proteins into gritty flakes and breaks the velvety suspension.","ms":"Jangan biarkan santan mendidih menggelegak! Haba tinggi akan menyebabkan santan berketul dan rosak tekstur berkrimnya.","ja":"ココナッツミルク投入後は絶対に強火で沸騰させないでください！タンパク質が分離して白いモロモロができ、舌触りが台無しになります。","ko":"코코넛 밀크를 넣은 후 절대 센 불로 끓이지 마세요! 단백질이 분리되어 응고되면서 부드러운 식감을 망치게 됩니다."}},{"stepNumber":4,"image":"/images/my/curry-laksa-step4.jpg","title":{"zh-TW":"雙拼麵條盛碗・配料齊備淋湯出餐","en":"Blanch Dual Noodles, Top with Garnishes & Pour Curry","ms":"Celur Mee Campur Bihun & Tuang Kuah Kari Panas","ja":"麺を湯通しして器に盛り、熱々カレースープを注いで完成","ko":"면을 데쳐 담고 고명을 얹은 뒤 뜨거운 커리 육수 붓기"},"instruction":{"zh-TW":"滾水燙熟黃麵與米粉（約 40 秒），瀝乾盛入大湯碗。頂部鋪排撕碎雞肉、鮮甜大蝦、燙熟鮮血蛤、吸飽汁的豆腐卜與綠豆芽。將滾燙金黃濃郁的咖哩椰漿湯均勻淋滿整碗。附上切半青金桔與一小碟參巴辣椒醬，擠入金桔酸汁拌勻開動！","en":"Blanch mixed yellow noodles and rice vermicelli for 40 secs, shake dry and drop into serving bowl. Arrange shredded chicken, sweet prawns, cockles, juicy tofu puffs and crisp bean sprouts on top. Ladle bubbling golden curry broth lavishly over everything. Serve with halved calamansi lime and sambal on the side.","ms":"Celur mee kuning dan bihun 40 saat, toskan ke dalam mangkuk. Susun isi ayam, udang, kerang, tauhu pok dan taugeh. Sendukkan kuah kari pekat panas ke atasnya. Hidang bersama perahan limau kasturi dan sambal.","ja":"中華麺とビーフンを40秒茹でて丼へ。蒸し鶏、エビ、赤貝、ジューシーな豆腐卜、生もやしをトッピング。黄金色の熱々カレースープをたっぷり注ぎ、すだちライムをキュッと絞っていただきます！","ko":"에그누들과 쌀국수를 40초간 데쳐 그릇에 담습니다. 닭고기, 새우, 피꼬막, 유부, 숙주를 얹고 뜨거운 황금빛 커리 국물을 듬뿍 붓습니다. 칼라만시 즙을 짜 넣어 드세요!"},"durationSeconds":120}],"troubleshooting":[{"id":"curry-too-heavy","problem":{"zh-TW":"咖哩湯頭口感過於厚重膩口","en":"Curry soup feels too thick and cloying","ms":"Kuah rasa muak terlalu berlemak","ja":"スープが重すぎてくどい","ko":"국물이 너무 묵직하고 느끼함"},"cause":{"zh-TW":"椰漿比例過高或缺少酸味平衡","en":"Excessive coconut fat without citrus acidity","ms":"Terlebih santan tanpa asid limau","ja":"ココナッツミルクの多すぎ、または酸味の不足","ko":"코코넛 밀크가 과하거나 상큼한 산미가 부족함"},"solution":{"zh-TW":"食用時務必將附帶的 2 顆青金桔（Limau Kasturi）汁擠入湯中，天然果酸能瞬間化解厚膩，提拔出香料的清新層次！","en":"Squeeze in fresh calamansi lime juice! The bright citric acid cuts through richness and lifts the spices brilliantly.","ms":"Perah jus 2 biji limau kasturi ke dalam kuah sebelum makan untuk memotong lemak.","ja":"食べる直前にライム（カラマンシー）果汁をたっぷり絞ってください。柑橘の酸味が油っこさを切り裂き、爽快な旨味に変わります。","ko":"드실 때 반드시 칼라만시 라임 즙을 짜 넣으세요! 산뜻한 과일 산미가 느끼함을 싹 잡아줍니다."}}],"proTips":[{"zh-TW":"大馬老饕暗號「米粉麵」（Mee-Hoon-Mee）：點咖哩叻沙時一定要要求「米粉加黃麵」！細米粉負責吸飽鮮甜咖哩湯汁，粗黃麵負責提供扎實咀嚼筋道，一口咬下雙重爆汁享受！","en":"Hawker Secret \"Mee-Hoon-Mee\": Always order the dual noodle combo! Delicate rice vermicelli drinks up the curry broth like a sponge, while springy yellow noodles provide chewy toothsome satisfaction in every single bite.","ms":"Kod Rahsia Warung: Sentiasa pesan \"Mee campur Bihun\"! Bihun halus menyerap kuah kari dengan padu manakala mee kuning memberi kepuasan kunyahan yang kenyal.","ja":"屋台の合言葉「ミーフン・ミー」：カレーラクサは必ず「ビーフンと黄色い麺のミックス」で頼みましょう！細いビーフンがスープを吸い上げ、太麺が食べ応えをプラスする無敵の組み合わせです。","ko":"현지식 주문 암호 \"미훈 미\": 락사는 꼭 쌀국수와 에그누들을 반반 섞어서 주문하세요! 얇은 쌀국수가 국물을 듬뿍 머금고 굵은 노란 면이 쫄깃한 씹는 맛을 더해줍니다."}]},{"country":"my","id":"rendang-daging","slug":"rendang-daging","title":{"zh-TW":"仁當乾咖哩慢燉牛肉","en":"Authentic Caramelized Beef Rendang","ms":"Rendang Daging Tok Kerisik Asli","ja":"ルンダン・ダギン（牛肉のスパイスココナッツ煮込み）","ko":"른당 다깅 (말레이시아 전통 소고기 른당)"},"subtitle":{"zh-TW":"乾煎烘烤椰蓉・南薑香茅檸檬葉・小火慢煨焦糖化極致肉質","en":"Dry-Toasted Kerisik Coconut, Galangal, Lemongrass & Slow-Caramelized Beef","ms":"Kerisik Kelapa Wangi, Lengkuas, Serai & Daging Lembut Berkaramel","ja":"乾煎りココナッツ（クリシック）、ガランガルとレモングラスで煮崩れる牛肉","ko":"볶은 코코넛(크리식), 갈랑갈, 레몬그라스 향이 밴 캐러멜라이징 소고기"},"tagline":{"zh-TW":"CNN 讀者票選全球第一名終極美食！耗時數小時慢火煨燉的南洋神話","en":"Voted #1 on CNN’s World’s 50 Best Foods! The supreme pinnacle of slow-braised beef","ms":"Juara #1 Makanan Terbaik Dunia Pilihan Pembaca CNN! Keagungan masakan warisan turun-temurun","ja":"CNN世界一美味しい料理ランキング第1位！何時間もかけて旨味を凝縮した至宝","ko":"CNN 전 세계 최고의 음식 투표 1위! 오랜 시간 정성으로 졸여낸 궁극의 소고기 요리"},"heroImage":"/images/my/rendang-daging.jpg","difficulty":"hard","prepTimeMinutes":30,"cookTimeMinutes":120,"defaultServings":4,"caloriesPerServing":680,"category":"mains","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"森美蘭與霹靂・米南加保與馬來皇室傳承 (Negeri Sembilan & Perak)","en":"Negeri Sembilan & Perak / Minangkabau Roots","ms":"Negeri Sembilan & Perak","ja":"ネグリ・スンビラン州およびペラ州","ko":"느그리 슴빌란 & 페락"},"famousStreetMarkets":[{"zh-TW":"吉隆坡甘榜峇魯夜市","en":"Kampung Baru Night Market, KL","ms":"Pasar Malam Kampung Baru","ja":"カンポン・バル夜市","ko":"캄퐁 바루 야시장"},{"zh-TW":"森美蘭芙蓉大巴剎","en":"Seremban Pasar Besar, Negeri Sembilan","ms":"Pasar Besar Seremban","ja":"スレンバン大市場","ko":"스름반 중앙 시장"}],"historyStory":{"zh-TW":"源自米南加保（Minangkabau）族人。古代熱帶氣候炎熱且無冷藏設備，水手與遠行商人在出海前，將整塊牛肉在大量濃椰漿與防腐抗菌的南薑、薑黃、香茅與辣椒中，耗費 3-4 小時慢火翻炒熬乾。水分完全蒸發後，椰油轉化為天然焦糖覆裹每塊牛肉，可在常溫下保存數週不腐且越陳越香！","en":"Originated by Minangkabau people as a preserved traveling ration for long oceanic voyages. Before refrigeration, beef was slow-simmered in vast volumes of coconut milk and antimicrobial spices (galangal, turmeric, lemongrass) for 3-4 hours until all water evaporated and the coconut oil fried and caramelized the meat into a dark, crumbly crust that lasted weeks.","ms":"Masakan tradisi Minangkabau yang dimasak berjam-jam untuk bekal perantau. Santan dimasak sehingga kering dan minyaknya menggoreng daging menjadi gelap berkilat tanpa basi.","ja":"冷蔵庫がなかった時代、航海に出る旅人の保存食として誕生。スパイスとココナッツミルクで水分が蒸発するまで3〜4時間じっくり煮込み、最後はココナッツオイル自身で肉をキャラメリゼさせて仕上げる究極のスローフードです。","ko":"항해를 떠나는 선원들의 보존식에서 출발했습니다. 수분이 완전히 날아갈 때까지 코코넛 밀크와 향신료로 장시간 졸여, 코코넛 오일로 고기를 캐러멜라이징하여 상온에서도 오래 보관할 수 있습니다."},"malayScript":"Rendang Daging Tok","malayPhonetics":"Rehn-dahng Dah-geeng Tohk","audioPronunciationText":"Makcik, nasi dengan rendang daging satu pinggan, kuah rendang taruk lebih!","communityHeritage":"Malay","nativeName":"Rendang Daging Tok","nativePhonetics":"Rendang Daging Tok"},"ingredients":[{"id":"beef-chuck","name":{"zh-TW":"牛腱肉或牛肩胛肉 (切 4cm 大厚方塊)","en":"Beef Chuck Roast or Shank (cut into 4cm cubes)","ms":"Daging Lembu Peha / Batang Pinang (Potong Kiub 4cm)","ja":"牛すね肉または肩ロース（4cm角切り）","ko":"소고기 사태 또는 척아이롤 (4cm 큼직한 깍둑썰기)"},"amount":800,"unitMetric":"g","unitUS":"28 oz","isKeyFlavor":true,"malayName":"Daging Lembu","malayPronunciation":"Dah-geeng Lehm-boo"},{"id":"kerisik-coconut","name":{"zh-TW":"黃金烘烤椰絲蓉 (Kerisik / 乾煸現磨)","en":"Toasted Grated Coconut Butter (Kerisik)","ms":"Kerisik Kelapa Tumbuk Wangi","ja":"乾煎りココナッツペースト（クリシック）","ko":"볶은 코코넛 페이스트 (크리식)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":true,"malayName":"Kerisik","malayPronunciation":"Keh-ree-seek","substitute":{"substituteName":{"zh-TW":"無糖乾燥椰子粉乾鍋小火乾炒至金黃微焦，用研磨機打出油成膏狀","en":"Pan-toast unsweetened shredded coconut over low heat until deep golden brown, then blend until oily","ms":"Goreng kelapa parut kering tanpa minyak hingga keperangan dan kisar","ja":"無糖ココナッツファインを乾煎りして油が出るまでミルで粉砕","ko":"무가당 코코넛 가루를 팬에 노릇하게 볶은 뒤 블렌더로 기름이 돌 때까지 갈기"},"ratio":"1:1","explanation":{"zh-TW":"Kerisik 是 Rendang 最深邃堅果焦香與深黑褐色的靈魂源泉！","en":"Kerisik is the nutty, dark golden flavor engine of genuine Rendang.","ms":"Kerisik memberi warna gelap dan rasa berlemak khas rendang.","ja":"クリシックがルンダン特有のナッツのような香ばしさと深いコクを生み出します。","ko":"크리식은 른당 고유의 고소한 풍미와 짙은 갈색 빛깔을 완성하는 핵심 재료입니다."},"whereToBuy":{"zh-TW":"東南亞雜貨店或自製","en":"Southeast Asian grocer or DIY","ms":"Kedai runcit atau buat sendiri","ja":"東南アジア食材店または自家製","ko":"동남아 식료품점 또는 직접 제조"}}},{"id":"coconut-milk-rendang","name":{"zh-TW":"濃純椰漿 (Santan)","en":"Pure Thick Coconut Milk (Santan)","ms":"Pati Santan Kelapa Asli","ja":"無添加・高濃度ココナッツミルク","ko":"진한 무첨가 코코넛 밀크"},"amount":500,"unitMetric":"ml","unitUS":"17 fl oz","isKeyFlavor":true,"malayName":"Pati Santan","malayPronunciation":"Pah-tee Sahn-tahn"},{"id":"rendang-spice-paste","name":{"zh-TW":"香料泥：紅蔥頭、大蒜、南薑、新鮮薑黃、香茅、乾辣椒","en":"Spice Paste: Shallots, garlic, galangal, fresh turmeric, lemongrass, dried chilies","ms":"Pes Kisar: Bawang, lengkuas, kunyit hidup, serai, cili kering","ja":"香辛ペースト：エシャロット、ニンニク、ガランガル、生ウコン、レモングラス、唐辛子","ko":"향신 페이스트: 샬롯, 마늘, 갈랑갈, 생강황, 레몬그라스, 건고추"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"malayName":"Pes Rendang","malayPronunciation":"Pehs Rehn-dahng"},{"id":"turmeric-leaves","name":{"zh-TW":"新鮮薑黃葉 (撕細絲 / Daun Kunyit)","en":"Fresh Turmeric Leaves (Torn finely / Daun Kunyit)","ms":"Daun Kunyit Hiris Halus","ja":"生ターメリックリーフ（細切り）","ko":"신선한 강황잎 (잘게 찢은 것)"},"amount":2,"unitMetric":"piece","unitUS":"2 leaves","isKeyFlavor":true,"malayName":"Daun Kunyit","malayPronunciation":"Dah-oon Koon-yeet"},{"id":"kaffir-lime-leaves","name":{"zh-TW":"新鮮馬蜂橙檸檬葉 (去梗撕碎 / Daun Limau Purut)","en":"Kaffir Lime Leaves (Torn & bruised)","ms":"Daun Limau Purut Segar","ja":"バイマックルー（こぶみかんの葉）","ko":"카피르 라임 리프 (가운데 줄기 제거)"},"amount":5,"unitMetric":"piece","unitUS":"5 leaves","isKeyFlavor":true,"malayName":"Daun Limau Purut","malayPronunciation":"Dah-oon Lee-mah-oo Poo-root"},{"id":"gula-melaka-rendang","name":{"zh-TW":"馬六甲純椰糖","en":"Pure Gula Melaka Palm Sugar","ms":"Gula Melaka Cincang","ja":"パームシュガー（グラ・マラッカ）","ko":"굴라 말라카 흑당"},"amount":30,"unitMetric":"g","unitUS":"1.2 oz","isKeyFlavor":false,"malayName":"Gula Melaka","malayPronunciation":"Goo-lah Meh-lah-kah"}],"steps":[{"stepNumber":1,"image":"/images/my/rendang-daging-step1.jpg","title":{"zh-TW":"乾鍋煸香純椰絲製作黑金 Kerisik","en":"Pan-Toast Grated Coconut to Golden Kerisik Paste","ms":"Goreng Kelapa Parut Menjadi Kerisik Perang","ja":"ココナッツを油なしで乾煎りし香ばしいクリシックを作る","ko":"마른 팬에 코코넛 가루를 볶아 크리식 만들기"},"instruction":{"zh-TW":"乾燥平底鍋無油下 60g 新鮮椰絲或無糖椰蓉。開極小火慢炒約 15 分鐘，不停翻動防止局部焦黑，直到顏色轉為如深巧克力般的紅褐色並散發狂野椰油香。趁熱倒入石臼或研磨機搗磨成流質膏狀（Kerisik），備用。","en":"In dry pan over low heat, toss 60g shredded unsweetened coconut for 15 mins, stirring constantly until deep toasty chocolate brown. Transfer to mortar or food processor while warm and grind until natural oils release into a dense, fragrant brown paste (Kerisik).","ms":"Goreng kelapa parut dalam kuali tanpa minyak atas api kecil sehingga bertukar perang gelap harum. Tumbuk panas-panas dalam lesung batu hingga keluar minyak berkilat.","ja":"フライパンにココナッツファイン60gを油を引かずに入れ、弱火で絶えず混ぜながら15分乾煎り。チョコレート色になったら温かいうちにすり鉢やミルで油が滲み出るまで粉砕します。","ko":"기름 없는 마른 팬에 코코넛 가루 60g을 넣고 약불에서 15분간 저어가며 볶습니다. 짙은 초콜릿빛 갈색이 되면 따뜻할 때 분쇄기에 넣고 기름이 배어나올 때까지 갈아줍니다."},"durationSeconds":900},{"stepNumber":2,"image":"/images/my/rendang-daging-step2.jpg","title":{"zh-TW":"牛肉、香料泥與特濃椰漿同煮 (Gulai 階段)","en":"Simmer Beef, Spice Paste & Coconut Milk (Gulai Phase)","ms":"Didihkan Daging Bersama Rempah Kisar & Santan","ja":"牛肉、スパイス、ココナッツミルクを一鍋で煮始める","ko":"소고기, 향신료, 코코넛 밀크를 한 냄비에 넣고 끓이기"},"instruction":{"zh-TW":"大深鍋中放入切厚塊的牛腱肉、打碎的香料泥（Rempah）、撕碎檸檬葉、切細絲薑黃葉與 500ml 純椰漿。大火煮沸後轉中火，不加鍋蓋慢煮 45-50 分鐘，中途每隔幾分鐘輕輕翻底攪動，讓牛肉纖維逐漸吸飽香料與椰汁。","en":"Combine 800g beef cubes, blended spice paste, torn kaffir lime leaves, shredded turmeric leaves, and 500ml pure coconut cream in wide pot. Bring to boil, then reduce to active medium simmer uncovered for 45-50 mins, stirring occasionally to prevent sticking as liquid thickens.","ms":"Masukkan daging, pes rempah, daun limau purut, daun kunyit hiris dan 500ml santan ke dalam kuali. Masak tanpa tutup atas api sederhana selama 45-50 minit sambil dikacau sekali-sekala.","ja":"深鍋に牛肉、スパイスペースト、こぶみかんの葉、細切りウコンの葉、ココナッツミルク500mlを入れ沸騰させます。蓋をせず中火で45〜50分煮詰め、肉に味を染み込ませます。","ko":"넓은 냄비에 소고기, 향신 페이스트, 라임 잎, 강황 잎, 코코넛 밀크 500ml를 넣고 끓입니다. 뚜껑을 열고 중불에서 45-50분간 저어가며 국물이 졸아들 때까지 끓입니다."},"durationSeconds":2700,"cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Meat/Stew Mode 35 mins + Sauté reduction 20 mins","instructionOverride":{"zh-TW":"壓力鍋模式：椰漿減至 350ml，高壓燉煮 35 分鐘使牛肉軟爛。洩壓後開大火 Sauté 模式翻炒收汁 20 分鐘即可！","en":"Instant Pot: Reduce coconut milk to 350ml. High Pressure 35 mins, then Sauté mode for 20 mins to evaporate sauce.","ms":"Periuk Tekanan: Santan 350ml. Tekanan tinggi 35 minit, kemudian mod Sauté 20 minit untuk keringkan kuah.","ja":"電気圧力鍋：ココナッツミルクを350mlに減らし高圧35分。減圧後Sauté（炒め）モードで20分煮詰めます。","ko":"인스턴트팟: 코코넛 밀크를 350ml로 줄이고 고압 35분 조리 후, 소테(볶음) 모드로 20분간 수분을 날리며 조립니다."}}]},{"stepNumber":3,"image":"/images/my/rendang-daging-step3.jpg","title":{"zh-TW":"轉入 Kalio 階段・加入 Kerisik 椰油析出","en":"Transition to Kalio Phase & Fold in Kerisik Paste","ms":"Fasa Kalio: Masukkan Kerisik & Kacau Cermat","ja":"カリオ段階：クリシックペーストを投入し油を分離させる","ko":"칼리오 단계: 크리식 페이스트를 넣고 볶기"},"instruction":{"zh-TW":"當湯汁縮減至原本的三分之一、質地轉為濃稠金黃泥狀（此為 Kalio 濕咖哩階段），加入準備好的純椰蓉膏（Kerisik）、馬六甲椰糖與 1 茶匙鹽。轉小火繼續慢炒，此時椰漿中的天然椰油開始大量析出，浸潤著牛肉。","en":"When liquid reduces by two-thirds into a thick golden gravy (the Kalio phase), stir in the toasted Kerisik paste, shaved Gula Melaka, and salt. Lower to gentle heat. Pure coconut oil begins to separate out and shallow-fry the beef in its own lipids.","ms":"Apabila kuah pekat dan memekat (fasa Kalio), masukkan kerisik, gula Melaka dan garam. Kacau atas api kecil sehingga minyak kelapa keluar berkilat.","ja":"煮汁が1/3に煮詰まって黄金色のとろみが出たら（カリオ段階）、作っておいたクリシック、パームシュガー、塩を加えます。弱火で炒め続けると、ココナッツ油が大量に分離してきます。","ko":"국물이 1/3로 줄어들어 걸쭉한 상태(칼리오 단계)가 되면 크리식 페이스트, 굴라 말라카 흑당, 소금을 넣습니다. 약불에서 볶으면 코코넛 오일이 분리되어 고기를 튀기듯 조려줍니다."},"durationSeconds":1500},{"stepNumber":4,"image":"/images/my/rendang-daging-step4.jpg","title":{"zh-TW":"微火乾煎慢炒出黑金深褐油光 (Rendang 成型)","en":"Slow-Fry to Deep Dark Mahogany Crust (True Dry Rendang)","ms":"Kacau Perlahan Sehingga Kering Gelap Berkilat (Rendang)","ja":"弱火で炒め続け、黒褐色の艶やかなドライルンダンに仕上げる","ko":"약불에서 수분을 날려 짙은 갈색빛의 드라이 른당 완성"},"instruction":{"zh-TW":"【關鍵收尾】：維持極小火，用鍋鏟不斷輕推翻拌 25-30 分鐘，讓析出的高溫椰油把牛肉表面與辛香料粒乾煎烘烤（Goreng Rendang），顏色逐漸由金黃蛻變為極致沉穩的黑黑紅褐色！當水分完全消失、醬料緊緊包裹在每塊酥爛牛肉表面時，即告大功告成！","en":"[Grand Finale]: Keep flame on bare minimum. Stir gently for final 25-30 mins as the rendered coconut oil pan-fries the spices onto the beef cubes. The color miraculously transforms from orange to deep, glistening, mahogany black-brown. Remove when zero liquid remains and beef is cloaked in intensely aromatic spice crust!","ms":"Kawal api paling kecil. Kacau tanpa henti selama 25-30 minit sehingga minyak kelapa menggoreng rempah hingga berwarna coklat gelap berkilat tanpa sebarang air. Angkat bila rendang kering sempurna!","ja":"【最高潮の仕上げ】：極弱火を保ち、25〜30分間優しく炒め続けます。分離したココナッツオイルが肉の表面を香ばしく焼き付け、色がオレンジから見事な深黒褐色へと変化。水分が完全に飛び、スパイスが肉に絡みついたら完成！","ko":"【대단원의 완성】: 불을 가장 약하게 유지하고 25-30분간 천천히 저어줍니다. 코코넛 오일이 고기와 양념을 볶아내며 주황빛에서 매혹적인 흑갈색으로 변합니다. 수분이 완전히 날아가고 양념이 고기에 코팅되면 완성입니다!"},"durationSeconds":1800,"crucialTips":{"zh-TW":"最後半小時切勿偷懶離鍋！必須守在鍋旁翻炒，否則底部容易焦糊發苦。","en":"Never abandon the pot during the final 30 mins! Constant gentle stirring prevents scorching.","ms":"Jangan tinggalkan kuali dalam 30 minit terakhir! Kacau berterusan agar rendang tidak hangit.","ja":"最後の30分は絶対に鍋から離れないでください！絶えず優しく底をこそげるように混ぜるのが焦がさない秘訣。","ko":"마지막 30분 동안은 팬 곁을 떠나지 마세요! 타지 않도록 바닥을 긁어가며 천천히 저어주어야 합니다."}}],"troubleshooting":[{"id":"beef-tough","problem":{"zh-TW":"牛肉燉煮後依舊偏硬不夠軟爛","en":"Beef remains tough and chewy","ms":"Daging masih liat dan keras","ja":"牛肉が固くてパサつく","ko":"소고기가 부드럽지 않고 질김"},"cause":{"zh-TW":"火候過大導致水分過早燒乾，肉質纖維尚未膠化","en":"Heat too high; liquid evaporated before collagen broke down","ms":"Api terlalu besar sehingga kuah kering awal","ja":"火が強すぎて水分が早く飛び、ゼラチン化する前に煮詰まった","ko":"불이 너무 세서 콜라겐이 녹기 전에 수분이 날아감"},"solution":{"zh-TW":"補入 150ml 熱水或椰漿，加蓋轉極微火再慢燜 25 分鐘，直到用叉子可輕易穿透肉塊。","en":"Splash in 150ml hot water, cover and simmer on ultra-low for 25 mins until tender.","ms":"Tambah 150ml air panas, tutup dan reneh api kecil 25 minit.","ja":"お湯150mlを足して蓋をし、極弱火で25分追加で蒸し煮にしてください。","ko":"따뜻한 물 150ml를 보충하고 뚜껑을 덮은 뒤 약불에서 25분간 더 뜸을 들이세요."}}],"proTips":[{"zh-TW":"神級美味秘密：Rendang 煮好的「隔天」比當天好吃十倍！經過一晚冷卻靜置，牛肉細胞徹底吸飽香茅、椰糖與焦香椰油精華，配白飯、椰漿飯或竹筒飯（Lemang）美味到令人落淚！","en":"The Golden Rule of Rendang: It tastes 10x better the NEXT DAY! Resting overnight lets the cooled beef fibers vacuum up the concentrated coconut essence. Reheat gently and serve with Nasi Lemak or Lemang for pure euphoria.","ms":"Rahsia Agung: Rendang lebih sedap dimakan pada \"KEESOKAN HARINYA\"! Perapan semalaman membolehkan daging menyerap pati rempah hingga ke tulang.","ja":"大師の至言：ルンダンは「翌日」が10倍美味しい！一晩寝かせることで肉が冷める際にスパイスとココナッツの旨味を芯まで吸い込み、驚くほど芳醇に仕上がります。","ko":"최고의 꿀팁: 른당은 만든 \"다음 날\" 먹으면 10배 더 맛있습니다! 하룻밤 식으면서 고기 결 사이사이로 진한 코코넛 오일과 향신료가 완전히 스며듭니다."}]},{"country":"my","id":"satay-chicken","slug":"satay-chicken","title":{"zh-TW":"加影炭烤沙爹雞肉串佐沙爹醬","en":"Kajang Charcoal Chicken Satay & Peanut Sauce","ms":"Sate Ayam Kajang Kuah Kacang Pedas Manis","ja":"カジャン名物・炭火焼きチキンサテ＆特製ピーナッツだれ","ko":"카장 숯불 치킨 사테 (말레이시아식 꼬치구이 & 땅콩 소스)"},"subtitle":{"zh-TW":"薑黃香茅醃汁・炭火微焦香脆・顆粒濃郁花生沾醬佐馬來米糕","en":"Turmeric Lemongrass Glaze, Smoky Charred Skewers & Chunky Peanut Sauce","ms":"Perapan Kunyit & Serai, Bakar Arang Wangi & Kuah Kacang Berlemak","ja":"ターメリックとレモングラスのタレ、香ばしい炭火焼きと濃厚ピーナッツだれ","ko":"강황과 레몬그라스 양념, 불향 가득한 숯불구이와 고소한 땅콩 소스"},"tagline":{"zh-TW":"大馬沙爹之都加影（Kajang）傳奇配方！夜市炭火煙霧下的無敵誘惑","en":"Legendary recipe from Kajang, the official Satay Capital of Malaysia","ms":"Resipi legenda dari Kajang, ibu kota sate terulung di Malaysia","ja":"マレーシアのサテの聖地「カジャン」直伝！夜市の煙が食欲をそそる逸品","ko":"말레이시아 사테의 성지 카장(Kajang)의 전설적인 숯불 꼬치구이 레시피"},"heroImage":"/images/my/satay-chicken.jpg","difficulty":"medium","prepTimeMinutes":30,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":490,"category":"streetSnacks","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"中馬・雪蘭莪加影 (Kajang, Selangor)","en":"Kajang, Selangor (Satay Capital)","ms":"Kajang, Selangor","ja":"セランゴール州カジャン","ko":"셀랑고르 카장"},"famousStreetMarkets":[{"zh-TW":"加影沙爹王子老店","en":"Restoran Sate Kajang Hj Samuri","ms":"Sate Kajang Hj Samuri","ja":"サテ・カジャン・サモリ本店","ko":"사테 카장 사무리 본점"},{"zh-TW":"吉隆坡阿羅街夜市沙爹攤","en":"Jalan Alor Satay Hawkers, KL","ms":"Gerai Sate Jalan Alor","ja":"アロー通りサテ屋台","ko":"잘란 알로 사테 노점"}],"historyStory":{"zh-TW":"沙爹起源於爪哇商旅受中東烤肉串（Kebab）啟發所創，傳入大馬後在雪蘭莪加影（Kajang）發揚光大。加影沙爹的獨特之處在於每串肉之間夾入一片肥腴雞皮或牛脂，在長條炭爐上邊扇風邊刷香茅油，肉汁淋在炭火上爆發出陣陣白煙與狂野肉香。佐以大塊花生碎炒成的甜辣沙爹醬、馬來蒸米糕（Ketupat）與生黃瓜生洋蔥，百吃不厭。","en":"Derived from Middle Eastern kebabs brought by Muslim traders, then elevated into an art form in Kajang, Selangor. Kajang satay skewers a morsel of skin/fat between meat for juiciness, basted with lemongrass oil over narrow charcoal troughs. Served with thick, spicy-sweet peanut sauce, ketupat rice cubes and crisp red onions.","ms":"Berasal daripada pedagang Jawa yang terinspirasi kebab Arab, kemudian dimartabatkan di Kajang oleh Haji Samuri. Daging ayam diperap rempah wangi dan dibakar atas bara api arang bersama kuah kacang pekat.","ja":"アラブのケバブに由来し、マレーシアのカジャンで独自の進化を遂げた国民的串焼き料理。鶏肉の間に皮や脂身を挟んで炭火で炙り、香ばしい煙をまとわせます。ピーナッツの粒々が残る甘辛ダレと角切り餅（クトゥパ）を添えていただきます。","ko":"중동의 케밥에서 유래하여 말레이시아 카장에서 꽃을 피운 꼬치구이 요리입니다. 닭고기 사이사이에 닭 껍질을 끼워 구워 육즙이 마르지 않으며, 고소한 땅콩 소스와 끄투팟(쌀떡)을 곁들입니다."},"malayScript":"Sate Ayam Kajang","malayPhonetics":"Sah-teh Ah-yahm Kah-jahng","audioPronunciationText":"An-neh, Sate Ayam sepuluh cucuk, kuah kacang lebih, ketupat satu!","communityHeritage":"Malay","nativeName":"Sate Ayam Kajang","nativePhonetics":"Sate Ayam Kajang"},"ingredients":[{"id":"chicken-thigh","name":{"zh-TW":"去骨去皮鮮嫩雞腿肉 (切 2cm 方塊)","en":"Boneless Skinless Chicken Thighs (cut into 2cm cubes)","ms":"Isi Paha Ayam Segar (Potong Dadu 2cm)","ja":"鶏もも肉（2cm角切り）","ko":"닭다리살 정육 (2cm 깍둑썰기)"},"amount":500,"unitMetric":"g","unitUS":"18 oz","isKeyFlavor":true,"malayName":"Isi Paha Ayam","malayPronunciation":"Ee-see Pah-hah Ah-yahm"},{"id":"satay-marinade","name":{"zh-TW":"沙爹醃醬：新鮮薑黃粉、香茅碎、紅蔥頭、芫荽籽粉、小茴香、黃糖、海鹽","en":"Marinade: Turmeric, lemongrass, shallots, coriander seed, cumin, brown sugar, salt","ms":"Perapan: Serbuk kunyit, serai, bawang merah, ketumbar, jintan manis, gula perang","ja":"漬けダレ：ターメリック、レモングラス、エシャロット、コリアンダー、クミン、黒糖、塩","ko":"사테 마리네이드: 강황가루, 레몬그라스, 샬롯, 코리앤더 가루, 큐민, 황설탕, 소금"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"malayName":"Pes Perapan Sate","malayPronunciation":"Pehs Peh-rah-pahn Sah-teh"},{"id":"bamboo-skewers","name":{"zh-TW":"竹籤 (預先泡水 30 分鐘防烤焦)","en":"Bamboo Skewers (Soaked in water 30 mins)","ms":"Lidi Sate (Rendam Air)","ja":"竹串（焦げ防止のため30分水につける）","ko":"대나무 꼬치 (타지 않게 30분간 물에 불림)"},"amount":16,"unitMetric":"piece","unitUS":"16 skewers","isKeyFlavor":false,"malayName":"Lidi Sate","malayPronunciation":"Lee-dee Sah-teh"},{"id":"roasted-peanuts","name":{"zh-TW":"熟花生米 (粗壓研碎留顆粒感)","en":"Roasted Peanuts (Coarsely crushed for texture)","ms":"Kacang Tanah Sangai (Tumbuk Kasar)","ja":"ローストピーナッツ（粗く砕いて粒感を残す）","ko":"구운 땅콩 (식감이 살아있게 굵게 으깸)"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"malayName":"Kacang Tanah Tumbuk","malayPronunciation":"Kah-chahng Tah-nah Toom-book"},{"id":"peanut-sauce-spices","name":{"zh-TW":"沙爹醬底料：乾辣椒醬、紅蔥蒜末、香茅、羅望子汁、椰糖","en":"Sauce Base: Dried chili paste, shallots, garlic, lemongrass, tamarind, palm sugar","ms":"Rempah Kuah: Pes cili kering, serai, air asam jawa, gula Melaka","ja":"ソース調味料：唐辛子ペースト、エシャロット、タマリンド汁、パームシュガー","ko":"소스 베이스: 건고추 페이스트, 샬롯, 레몬그라스, 타마린드 즙, 흑당"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"malayName":"Pes Kuah Kacang","malayPronunciation":"Pehs Koo-ah Kah-chahng"},{"id":"ketupat-rice","name":{"zh-TW":"馬來蒸米糕塊 (Ketupat) 或白飯塊","en":"Pressed Rice Cakes (Ketupat / Nasi Impit, cubed)","ms":"Ketupat / Nasi Impit Potong","ja":"マレー伝統圧縮米ケーキ（クトゥパ / ナシ・インピット）","ko":"말레이식 압축 쌀떡 (끄투팟 / 나시 임핏)"},"amount":150,"unitMetric":"g","unitUS":"5 oz","isKeyFlavor":false,"malayName":"Nasi Impit","malayPronunciation":"Nah-see Eem-peet"},{"id":"onion-cucumber-sides","name":{"zh-TW":"紫洋蔥厚切塊與鮮黃瓜厚角","en":"Red Onions (Cut into large petals) & Cucumber Chunks","ms":"Bawang Merah & Timun Potong Dadu","ja":"紫玉ねぎ角切り＆きゅうりぶつ切り","ko":"적양파 큼직하게 썬 것 & 오이 조각"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":false,"malayName":"Ulam Bawang Timun","malayPronunciation":"Oo-lahm Bah-wahng Tee-moon"}],"steps":[{"stepNumber":1,"image":"/images/my/satay-chicken-step1.jpg","title":{"zh-TW":"雞肉切塊・香茅薑黃深度醃製","en":"Marinate Chicken with Turmeric, Lemongrass & Aromatics","ms":"Perap Daging Ayam Bersama Kunyit & Serai Wangi","ja":"鶏肉を角切りにし、ターメリックとレモングラスで漬け込む","ko":"닭고기를 썰어 강황과 레몬그라스 양념에 재우기"},"instruction":{"zh-TW":"將去骨雞腿肉切成 2 公分方塊。加入研磨好的香茅碎、生薑黃粉、紅蔥碎、芫荽粉、小茴香、2 大匙黃糖與 1 茶匙海鹽。用手抓勻按摩 3 分鐘讓醃料滲透，密封冷藏醃製至少 4 小時（隔夜更香）。","en":"Cut chicken thigh into 2cm cubes. Toss with blended lemongrass, turmeric, shallots, ground coriander, cumin, 2 tbsp brown sugar and salt. Massage thoroughly for 3 mins. Cover and chill for at least 4 hours, preferably overnight.","ms":"Potong isi ayam dadu 2cm. Gaulkan bersama serai kisar, serbuk kunyit, bawang merah, ketumbar, jintan, gula perang dan garam. Perap sekurang-kurangnya 4 jam atau semalaman.","ja":"鶏肉を2cm角に切り、レモングラス、ターメリック、エシャロット、コリアンダー、クミン、黒糖、塩を揉み込みます。4時間以上（できれば一晩）冷蔵庫で寝かせます。","ko":"닭다리살을 2cm 크기로 깍둑썰기합니다. 레몬그라스, 강황, 샬롯, 코리앤더, 큐민, 설탕, 소금을 넣고 조물조물 버무려 최소 4시간 이상 냉장 숙성합니다."},"durationSeconds":300},{"stepNumber":2,"image":"/images/my/satay-chicken-step2.jpg","title":{"zh-TW":"串肉上竹籤・製作香茅刷油器","en":"Skewer Chicken onto Soaked Bamboo Sticks","ms":"Cucuk Daging Pada Lidi & Sedia Berus Serai","ja":"肉を竹串に刺し、レモングラスの刷毛を用意する","ko":"꼬치에 고기를 꿰고 레몬그라스 오일 붓 준비"},"instruction":{"zh-TW":"將泡透水的竹籤取出，每根竹籤緊湊串上 4-5 塊醃好的雞肉，壓實並撫平表面。取一根整香茅，用刀背將根部拍碎成刷子狀（Serai Brush），沾取植物油混少許蜂蜜，作為烤製時的增香刷油器！","en":"Thread 4-5 cubes of marinated chicken onto each soaked skewer, packing snugly. Bruise the root end of a fresh lemongrass stalk into a fibrous brush (Serai Brush) to dab oil and honey onto the skewers during grilling!","ms":"Cucuk 4-5 ketul ayam pada setiap lidi sate. Titik hujung batang serai menjadi berus untuk menyapu minyak wangi semasa membakar.","ja":"水につけておいた竹串に肉を4〜5個ずつ隙間なく刺します。レモングラスの根元を叩いてブラシ状にし、油とハチミツを塗る特製ハケを作ります。","ko":"불려둔 꼬치에 닭고기를 4-5개씩 단단하게 꾑니다. 레몬그라스 줄기 끝을 칼등으로 두드려 붓 모양으로 만들어 굽는 동안 오일을 바르는 솔로 사용합니다."},"durationSeconds":600},{"stepNumber":3,"image":"/images/my/satay-chicken-step3.jpg","title":{"zh-TW":"熬製香濃顆粒花生沙爹沾醬 (Kuah Kacang)","en":"Simmer Chunky Sweet-Spicy Peanut Satay Sauce","ms":"Masak Kuah Kacang Pekat Pedas Manis Berkrim","ja":"粒々食感の甘辛ピーナッツだれを煮込む","ko":"고소하고 달콤매콤한 땅콩 사테 소스 끓이기"},"instruction":{"zh-TW":"鍋中熱油炒香乾辣椒醬、紅蔥碎與香茅末 8 分鐘。加入 200g 粗粒碎花生、250ml 水、30g 馬六甲椰糖、2 大匙羅望子酸汁與 1/2 茶匙鹽。小火慢熬 15 分鐘至醬汁濃稠冒泡、花生油脂微微浮面，甜酸微辣、香醇無比！","en":"Sauté chili paste, shallots, garlic and lemongrass in oil for 8 mins. Stir in 200g crushed roasted peanuts, 250ml water, 30g Gula Melaka, 2 tbsp tamarind juice and salt. Simmer over low heat for 15 mins until bubbling, thickened and glistening with rich peanut oil.","ms":"Tumis pes cili, bawang dan serai hingga wangi. Masukkan kacang tanah tumbuk, air, gula Melaka, air asam jawa dan garam. Reneh api kecil 15 minit sehingga kuah pekat berlemak.","ja":"油でチリペーストとエシャロットを炒め、粗挽きピーナッツ、水、パームシュガー、タマリンド汁、塩を加えます。弱火で15分煮込み、ピーナッツの油が浮いてトロリとするまで仕上げます。","ko":"팬에 기름을 두르고 칠리 페이스트와 샬롯을 볶다가 굵게 으깬 땅콩, 물, 흑당, 타마린드 즙, 소금을 넣습니다. 약불에서 15분간 걸쭉해질 때까지 끓여냅니다."},"durationSeconds":900},{"stepNumber":4,"image":"/images/my/satay-chicken-step4.jpg","title":{"zh-TW":"炭火翻烤或氣炸出焦香・拼盤上桌","en":"Charcoal Grill or Air Fry to Golden Char & Serve","ms":"Bakar Arang / Air Fryer Hingga Garing & Hidang","ja":"炭火またはエアフライヤーで香ばしく焼き上げ盛り付ける","ko":"숯불 또는 에어프라이어에 노릇하게 구워 서빙"},"instruction":{"zh-TW":"炭火烤爐（或燒熱條紋鐵板 / 氣炸鍋）：每面烤約 3-4 分鐘，中途用香茅刷沾油反覆刷在肉串上，翻面數次，直至邊緣微焦帶金黃炭香、肉汁飽滿！裝盤附上一大碗熱花生醬、馬來米糕塊（Ketupat）、生黃瓜片與洋蔥塊。沾滿花生醬大口咬下！","en":"Grill skewers over hot coals (or ridged grill pan / air fryer) for 3-4 mins per side. Continually baste with lemongrass oil brush. Turn frequently until edges blister into smoky golden char while interior stays succulent. Serve with piping peanut sauce, ketupat rice cubes, raw cucumber and red onion chunks.","ms":"Bakar sate atas bara arang 3-4 minit setiap belah sambil disapu minyak serai. Hidang panas bersama semangkuk kuah kacang, nasi impit, timun dan bawang.","ja":"炭火（またはグリルパン/エアフライヤー）で両面を3〜4分焼き、レモングラス刷毛で油を塗りながら香ばしい焦げ目をつけます。温かいピーナッツだれ、餅（クトゥパ）、きゅうりと玉ねぎを添えて完成！","ko":"숯불(또는 그릴팬/에어프라이어)에서 양면을 3-4분씩 굽고, 레몬그라스 붓으로 오일을 덧발라가며 불향을 입힙니다. 땅콩 소스, 끄투팟, 오이와 양파를 곁들여 냅니다."},"durationSeconds":480,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) 10-12 mins, turning once","instructionOverride":{"zh-TW":"氣炸鍋模式：肉串平鋪炸籃，表面噴薄油。190°C 烤 6 分鐘，翻面刷蜂蜜油再烤 4-5 分鐘至焦香金黃！","en":"Air Fryer: Arrange skewers in basket, mist with oil. 190°C (375°F) for 6 mins, flip, baste with honey-oil, air fry 4-5 mins.","ms":"Air Fryer: Susun sate dalam bakul, sembur sedikit minyak. 190°C selama 6 minit, balikkan dan sapu minyak madu, bakar lagi 4-5 minit.","ja":"エアフライヤー：重ならないように並べ190℃で6分、裏返してオイルを塗りさらに4〜5分香ばしく焼きます。","ko":"에어프라이어: 꼬치를 바스켓에 펼쳐놓고 190℃에서 6분 조리 후, 뒤집어 오일을 바르고 4-5분 더 구워줍니다."}}]}],"troubleshooting":[{"id":"dry-meat","problem":{"zh-TW":"烤出來的肉質乾硬柴口","en":"Chicken turns out dry and chalky","ms":"Daging sate kering dan keras","ja":"鶏肉がパサついて固い","ko":"닭고기가 퍽퍽하고 질김"},"cause":{"zh-TW":"使用了純雞胸肉或烤製時間過長","en":"Used lean chicken breast or overcooked on low heat","ms":"Guna dada ayam tanpa lemak atau bakar terlalu lama","ja":"鶏胸肉を使用した、または弱火で長時間焼きすぎた","ko":"닭가슴살만 사용했거나 너무 오래 구움"},"solution":{"zh-TW":"務必選用油潤多汁的去骨「雞腿肉」；烤時火要猛，迅速鎖住肉汁，中途用香茅刷補油。","en":"Always use skin-on or fatty chicken THIGHS; grill over high heat to sear quickly.","ms":"Sentiasa guna bahagian paha ayam dan bakar atas api arang yang marak.","ja":"必ずジューシーな「鶏もも肉」を使い、強火で表面を素早く焼き固めて肉汁を閉じ込めます。","ko":"반드시 지방이 적당히 있는 \"닭다리살\"을 사용하고, 센 불에서 단시간에 구워 육즙을 가두세요."}}],"proTips":[{"zh-TW":"老饕吃法：吃沙爹時，拿起一塊生黃瓜或生洋蔥直接沾進花生醬裡嚼，清爽的辛甜解膩無敵；接著咬一口肉串、再配一塊沾滿醬汁的白米糕（Ketupat），這就是大馬夜市人生的巔峰！","en":"Local Ritual: Scoop up peanut sauce using a chunk of raw cucumber or red onion petal to cleanse the palate, followed by a piping bite of charred chicken and a rice cube (Ketupat) drenched in sauce!","ms":"Cara Menikmati Sejati: Cicah hirisan timun atau bawang segar ke dalam kuah kacang sebagai pembuka selera, disusuli seucuk sate panas dan seketul nasi impit.","ja":"地元流の食べ方：生玉ねぎやきゅうりをスプーン代わりにピーナッツだれをすくって食べると、驚くほどさっぱり！香ばしいサテと甘辛ダレが絡んだ米餅（クトゥパ）の無限ループが止まりません。","ko":"현지인 스타일: 생오이나 양파 조각으로 땅콩 소스를 푹 찍어 먹으면 아삭하고 개운합니다. 그 다음 사테 꼬치와 끄투팟 쌀떡을 함께 즐겨보세요!"}]},{"country":"my","id":"roti-canai","slug":"roti-canai","title":{"zh-TW":"印度飛餅甩餅佐扁豆咖哩","en":"Crispy Layered Roti Canai with Dhal Curry","ms":"Roti Canai Terbang Rangup Bersama Kuah Dhal","ja":"ロティ・チャナイ（極上層状フライングブレッド＆ダールカレー）","ko":"로티 차나이 (바삭한 결이 살아있는 인도식 플랫브레드 & 달 커리)"},"subtitle":{"zh-TW":"千層酥化飛甩手藝・外脆內軟・濃郁溫潤黃扁豆咖哩汁與參巴醬","en":"Paper-Thin Flying Dough, Flaky Laminated Layers, Comforting Yellow Dhal & Sambal","ms":"Doh Terbang Lembut Berlapis, Garing di Luar & Kuah Dhal Beraroma","ja":"薄く宙を舞う生地、何層にも重なるサクサク食感、優しいレンズ豆カレー","ko":"공중에서 회전시켜 얇게 편 반죽, 바삭하고 쫄깃한 결, 부드러운 렌틸콩 커리"},"tagline":{"zh-TW":"TasteAtlas 評選全球最佳麵包冠軍！嘛嘛檔靈魂鐵板奇蹟","en":"Ranked #1 World’s Best Bread by TasteAtlas! The mesmerizing theatre of Malaysian Mamak stalls","ms":"Dianugerahkan Roti Terbaik Dunia oleh TasteAtlas! Kehebatan seni tebar gerai Mamak","ja":"世界のベストブレッド第1位（TasteAtlas）！ママック屋台の華麗な技が生む奇跡のパン","ko":"테이스트아틀라스 선정 세계 최고의 빵 1위! 말레이시아 마막 식당의 전설적인 플랫브레드"},"heroImage":"/images/my/roti-canai.jpg","difficulty":"hard","prepTimeMinutes":40,"cookTimeMinutes":20,"defaultServings":4,"caloriesPerServing":420,"category":"streetSnacks","dietaryTags":["classic","halal","vegetarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"全馬全境・印度穆斯林嘛嘛檔 (Mamak Culture)","en":"Nationwide / Indian-Muslim Mamak Heritage","ms":"Seluruh Malaysia / Budaya Restoran Mamak","ja":"マレーシア全土・インド系ムスリム（ママック）文化","ko":"말레이시아 전역 / 인도계 무슬림 마막 문화"},"famousStreetMarkets":[{"zh-TW":"吉隆坡安邦路 TG’s Nasi Kandar","en":"TG’s Nasi Kandar, Bukit Bintang, KL","ms":"Restoran TG’s Nasi Kandar","ja":"TG’s ナシカンダー（ブキッビンタン）","ko":"TG 나시 칸다르 (부킷 빈탕)"},{"zh-TW":"檳城 Transfer Road 飛餅名店","en":"Roti Canai Transfer Road, Penang","ms":"Roti Canai Transfer Road","ja":"トランスファー・ロード・ロティチャナイ（ペナン）","ko":"트랜스퍼 로드 로티 차나이 (페낭)"}],"historyStory":{"zh-TW":"19 世紀印度泰米爾穆斯林移民來到馬來西亞，將南印度圓餅（Parotta）改良。廚師以精湛手法將麵團在空中急速旋轉、揮舞拋甩成薄如蟬翼的透光薄膜，折疊拍打形成幾十層空氣層。烙烤至金黃酥脆後，雙手在砧板上猛力一拍，「蓬」的一聲酥皮四濺、鬆軟如棉！配上扁豆咖哩（Kuah Dhal）與一勺參巴，是所有大馬人最溫暖的晨光與宵夜。","en":"Brought by Tamil Muslim immigrants in the 19th century and perfected in Malaysian Mamak stalls. Masters spin and twirl dough balls into paper-thin translucent sheets in mid-air, folding them into multi-layered squares. Cooked on cast iron flat tops with ghee, then violently clapped between hands to shatter the crispy layers into a fluffy, flaky cloud.","ms":"Dicipta oleh komuniti Mamak (India Muslim). Doh diuli bersama marjerin/ghee dan ditebar nipis bak sutera di udara. Selepas digoreng atas kuali leper panas, ditepuk dengan dua belah tangan agar garing berlapis.","ja":"19世紀に南インドから渡ったイスラム系移民（ママック）が生んだ傑作。生地を空中でアクロバティックに回転させて極限まで薄く伸ばし、鉄板でギー（澄ましバター）と共に焼き上げます。焼き上がりに両手でパンッと叩くことで何重もの層が弾け、サクサク＆フワフワの食感が生まれます。","ko":"19세기 남인도 타밀 무슬림 이주민들이 정착하며 발전시킨 요리입니다. 반죽을 공중에서 돌려 종이처럼 얇게 늘린 후 겹쳐 구워냅니다. 다 구운 뒤 양손으로 팡 하고 쳐서 바삭한 결을 살려내는 것이 비법입니다."},"malayScript":"Roti Canai Terbang","malayPhonetics":"Roh-tee Chah-nye Tehr-bahng","audioPronunciationText":"An-neh, Roti Canai dua keping, kuah banjir campur sambal satu!","communityHeritage":"Indian-Mamak","nativeName":"Roti Canai Terbang","nativePhonetics":"Roti Canai Terbang"},"ingredients":[{"id":"all-purpose-flour","name":{"zh-TW":"中筋麵粉 (高延展性)","en":"All-Purpose Flour or Bread Flour","ms":"Tepung Gandum Berprotein","ja":"中力粉または強力粉","ko":"중력분 또는 강력분"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":false,"malayName":"Tepung Gandum","malayPronunciation":"Teh-poong Gahn-doom"},{"id":"condensed-milk-dough","name":{"zh-TW":"甜煉乳 (賦予微甜焦香與金黃色澤)","en":"Sweetened Condensed Milk","ms":"Susu Pekat Manis","ja":"加糖練乳（焼き色とほのかな甘み）","ko":"가당 연유 (은은한 단맛과 황금빛 색감)"},"amount":25,"unitMetric":"g","unitUS":"1.5 tbsp","isKeyFlavor":true,"malayName":"Susu Pekat","malayPronunciation":"Soo-soo Peh-kaht"},{"id":"ghee-butter","name":{"zh-TW":"純印度酥油 (Ghee / 澄清牛油) 或植物牛油 (Planta)","en":"Pure Ghee or Margarine (Planta)","ms":"Minyak Sapi (Ghee) / Marjerin Planta","ja":"ギー（澄ましバター）またはプラントマーガリン","ko":"순수 기(Ghee, 정제 버터) 또는 마가린"},"amount":60,"unitMetric":"g","unitUS":"4 tbsp","isKeyFlavor":true,"malayName":"Minyak Sapi","malayPronunciation":"Meen-yahk Sah-pee"},{"id":"yellow-split-lentils","name":{"zh-TW":"黃扁豆 (Toor Dal / 煮咖哩汁)","en":"Yellow Split Pigeon Peas / Lentils (Toor Dal)","ms":"Kacang Dhal Kuning","ja":"イエロースプリットピース（レンズ豆・ダール）","ko":"노란 렌틸콩 (투르 달)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"malayName":"Kacang Dhal","malayPronunciation":"Kah-chahng Dahl"},{"id":"dhal-curry-spices","name":{"zh-TW":"扁豆咖哩香料：薑黃粉、咖哩葉、芥末籽、乾辣椒、孜然、大蒜、番茄丁","en":"Dhal Spices: Turmeric, curry leaves, mustard seeds, dried chili, cumin, tomato","ms":"Rempah Dhal: Kunyit, daun kari, biji sawi, cili kering, jintan, tomato","ja":"ダールスパイス：ターメリック、カレーリーフ、マスタードシード、クミン、トマト","ko":"달 커리 향신료: 강황, 커리 리프, 머스터드 시드, 건고추, 큐민, 토마토"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"malayName":"Rempah Dhal","malayPronunciation":"Rehm-pah Dahl"}],"steps":[{"stepNumber":1,"image":"/images/my/roti-canai-step1.jpg","title":{"zh-TW":"揉合軟麵團・分劑浸酥油充分鬆弛","en":"Knead Silky Dough & Rest in Ghee Overnight","ms":"Uli Doh Lembut & Rendam Minyak Sapi Rehat","ja":"滑らかな生地を捏ね、ギーを塗って長時間寝かせる","ko":"부드러운 반죽을 치대어 기 버터에 담가 숙성하기"},"instruction":{"zh-TW":"盆中放入 400g 麵粉、1 茶匙鹽、25g 甜煉乳、1 顆全蛋與 180ml 溫水。揉搓成光滑柔軟、略帶耳垂軟度的麵團（約 10 分鐘）。均分成 6 個圓球，表面厚厚塗抹純印度酥油（Ghee），蓋保鮮膜常溫靜置至少 6 小時（或冷藏過夜），讓麵筋完全舒展放鬆。","en":"Combine 400g flour, 1 tsp salt, 25g condensed milk, 1 egg and 180ml warm water. Knead for 10 mins until silky, soft and elastic. Divide into 6 round balls. Smear generously with melted ghee or butter, cover and rest for at least 6 hours (or overnight) so gluten fully relaxes.","ms":"Campurkan tepung, garam, susu pekat, telur dan air suam. Uli 10 minit hingga doh licin lembut. Bahagikan kepada 6 bebola. Sapu banyak minyak sapi/marjerin dan rehatkan 6 jam.","ja":"ボウルに粉、塩、練乳、卵、ぬるま湯を合わせ、耳たぶの柔らかさになるまで10分捏ねます。6等分に丸め、表面にギー（澄ましバター）をたっぷり塗り、ラップをして最低6時間（できれば一晩）寝かせます。","ko":"밀가루, 소금, 연유, 달걀, 미온수를 섞어 귓불처럼 부드러운 상태가 될 때까지 10분간 치댑니다. 6개로 둥글리기 한 뒤 기(Ghee)를 듬뿍 바르고 랩을 씌워 최소 6시간 이상 숙성합니다."},"durationSeconds":600},{"stepNumber":2,"image":"/images/my/roti-canai-step2.jpg","title":{"zh-TW":"飛甩延展成透光薄膜 (Tebar Roti)","en":"Twirl & Stretch Dough into Translucent Thin Membrane","ms":"Tebar Doh Nipis Tembus Cahaya (Tebar Roti)","ja":"生地を宙で回し広げて透けるほど薄く伸ばす","ko":"공중에서 회전시켜 비칠 정도로 얇게 펴기"},"instruction":{"zh-TW":"桌面抹上一層酥油。取一顆麵團按扁，手掌由中心向外平推推薄。一隻手抓住邊緣，利用手腕巧勁將麵團在空中向外拋甩（或雙手抓邊緣輕柔拉扯），直至延展成大如披薩、薄如報紙般透光的透明薄膜！在薄膜上抹少許酥油，由四邊向內對折成方形，形成幾十層微薄空氣層。","en":"Oil a smooth work surface. Flatten a dough ball, push edges thin. Gently swing, flip and pull the dough from the edges (or twirl in air) until it stretches into a gigantic, paper-thin translucent sheet you can read a newspaper through! Dot with ghee and fold four corners into a laminated square envelope.","ms":"Sapu minyak atas meja. Tekan doh leper dan tebar dengan hayunan pergelangan tangan hingga menjadi lapisan nipis tembus cahaya. Sapu sedikit marjerin dan lipat empat menjadi segi empat berudara.","ja":"台に油を塗り、生地を手のひらで広げます。手首のスナップを利かせて空中で回転させながら伸ばし、向こうが透けて見える新聞紙ほどの極薄膜に広げます。ギーを少量塗り、四方を折り畳んで四角い層を作ります。","ko":"작업대에 오일을 바르고 반죽을 넓게 누릅니다. 손목의 반동을 이용해 공중에서 던져 돌리거나 가장자리를 부드럽게 당겨 신문 글씨가 비칠 만큼 투명하고 얇은 막으로 늘립니다. 오일을 살짝 바르고 네 귀퉁이를 접어 결을 만듭니다."},"durationSeconds":480,"crucialTips":{"zh-TW":"新手如果不會空中拋甩飛餅，只要桌面抹足夠酥油，用指腹抓著邊緣溫柔向外拉伸，也能拉出極致透光薄皮！","en":"Beginner Tip: If you cannot toss it in air, simply use your fingertips to gently pull and coax the edges outwards over a well-oiled table.","ms":"Petua Pemula: Jika belum mahir menebar di udara, tarik perlahan-lahan bucu doh ke luar di atas meja licin berminyak.","ja":"初心者のコツ：空中で回すのが難しい場合は、油を塗った作業台の上で指先を使って優しく四方に引っ張るだけで綺麗に伸びます！","ko":"초보자 팁: 공중 회전이 어렵다면 오일을 듬뿍 바른 작업대에서 손가락으로 가장자리를 살살 잡아당겨 늘려도 충분히 얇게 펴집니다!"}},{"stepNumber":3,"image":"/images/my/roti-canai-step3.jpg","title":{"zh-TW":"平底鐵板香煎酥化・雙手猛拍震碎酥層","en":"Sear in Ghee on Flat Griddle & Violently Clap to Fluff","ms":"Goreng Atas Kuali Leper Panas & Tepuk Dua Belah Tangan","ja":"鉄板で香ばしく焼き、両手で一気に叩いて層を弾けさせる","ko":"팬에 구워낸 뒤 양손으로 팡 쳐서 바삭한 결 터뜨리기"},"instruction":{"zh-TW":"平底鑄鐵鍋大火熱鍋，轉中火加入 1 大匙酥油。放入折疊好的麵餅，輕輕按壓展開。每面慢煎 2-3 分鐘至外皮金黃斑駁、酥脆鼓起。起鍋放上砧板，趁熱雙手向內猛力一拍一擠（Clap），「喀嚓」一聲千層酥皮瞬間震碎爆散，鬆軟如雪！","en":"Heat cast iron skillet over medium with 1 tbsp ghee. Place folded dough, press lightly. Sear for 2-3 mins per side until golden mottled blisters form. Remove immediately onto cutting board: while blistering hot, use both hands to violently clap the sides together! It instantly shatters the crisp laminated layers into an airy, fluffy cloud.","ms":"Panaskan kuali leper bersama minyak sapi. Goreng roti 2-3 minit setiap belah hingga keemasan garing. Angkat atas papan dan tepuk kuat dengan dua tapak tangan serta-merta agar garing mekar!","ja":"フライパンにギーを熱し、生地を広げて入れます。両面を2〜3分ずつこんがりキツネ色になるまで焼きます。まな板に取り出し、熱いうちに両手でパンッと側面を激しく叩き潰します！パリパリの層が弾けてフワフワになります。","ko":"달궈진 팬에 기 버터를 두르고 반죽을 올려 앞뒤로 2-3분씩 노릇하게 굽습니다. 도마에 꺼내자마자 뜨거울 때 양손으로 양옆을 팡 하고 강하게 쳐줍니다! 바삭한 겉면이 부서지며 속 결이 폭신하게 살아납니다."},"durationSeconds":360},{"stepNumber":4,"image":"/images/my/roti-canai-step4.jpg","title":{"zh-TW":"同場加映：溫潤黃扁豆咖哩汁 (Kuah Dhal) 蘸點享用","en":"Simmer Creamy Comforting Yellow Dhal Curry & Serve","ms":"Masak Kuah Dhal Kuning Pekat & Hidang Bersama Sambal","ja":"優しいレンズ豆カレー（ダール）を添えて熱々を浸して食べる","ko":"부드러운 렌틸콩 달 커리와 삼발을 곁들여 완성"},"instruction":{"zh-TW":"黃扁豆加水與薑黃粉慢燉 25 分鐘至完全熟爛化成濃稠豆泥。油鍋爆香芥末籽、乾辣椒段、咖哩葉與大蒜碎，倒入扁豆泥中拌勻，加鹽與番茄丁微煮 5 分鐘。撕下一塊酥香飛餅，先浸透溫潤的扁豆咖哩，再蘸上一抹香辣參巴醬，入口酥脆綿滑、幸福無邊！","en":"Simmer yellow lentils with water and turmeric for 25 mins until mushy and thick. In small pan, temper mustard seeds, curry leaves, dried chilies and minced garlic in oil; pour sizzling aromatics into dhal. Season with salt. Tear a steaming piece of roti, drown it into warm dhal, dab with spicy sambal, and savor the world’s greatest bread!","ms":"Rebus kacang dhal bersama air dan kunyit hingga hancur pekat. Tumis biji sawi, daun kari, cili kering dan bawang putih, tuang ke dalam dhal. Hidang panas: koyak roti canai, celup kuah dhal banjir campur sambal!","ja":"レンズ豆を水とターメリックで25分煮てペースト状にします。別鍋で油にマスタードシード、カレーリーフ、乾燥唐辛子、ニンニクを入れてパチパチ弾けさせ、豆ペーストにジュッと投入して塩で調味。ちぎった熱々ロティをカレーとサンバルにたっぷり浸して召し上がれ！","ko":"렌틸콩에 물과 강황을 넣고 25분간 푹 삶아 으깹니다. 팬에 머스터드 시드, 커리 리프, 건고추, 마늘을 볶아 향을 낸 뒤 렌틸콩에 붓고 소금으로 간합니다. 바삭한 로티를 찢어 달 커리와 삼발에 푹 찍어 드세요!"},"durationSeconds":600}],"troubleshooting":[{"id":"roti-rubbery","problem":{"zh-TW":"飛餅煎好後韌如橡皮，完全不酥脆","en":"Roti turns out rubbery, tough and dense","ms":"Roti canai liat dan keras tidak rangup","ja":"焼き上がりがゴムのように固く、サクサクしない","ko":"로티가 질기고 딱딱하며 바삭하지 않음"},"cause":{"zh-TW":"麵團鬆弛時間不足、麵皮拉得不夠薄、或煎好後未執行「雙手猛拍」","en":"Insufficient dough resting, not stretched thin enough, or skipped the clap","ms":"Doh kurang rehat atau tidak ditepuk selepas masak","ja":"生地の寝かせ不足、伸ばしが厚い、または焼き上がりに叩いていない","ko":"반죽 숙성 시간 부족, 반죽을 덜 얇게 폈거나 구운 후 양손으로 치지 않음"},"solution":{"zh-TW":"麵團浸泡酥油必須鬆弛 6 小時以上才能消除麵筋彈性；煎好起鍋 5 秒內必須雙手猛拍震開層次！","en":"Must rest in fat for at least 6 hours; must clap violently within 5 seconds of leaving the pan!","ms":"Pastikan doh direhatkan 6 jam dan tepuk kuat sejurus selepas diangkat dari kuali!","ja":"油に浸して最低6時間は寝かせてください。また、焼き上がり後5秒以内に必ず両手でパンッと叩くこと！","ko":"반죽을 오일에 담가 최소 6시간 이상 숙성하고, 팬에서 꺼낸 즉시 5초 이내에 양손으로 강하게 쳐주세요!"}}],"proTips":[{"zh-TW":"嘛嘛檔老饕通關密語「Kuah Banjir」：在馬來西亞吃 Roti Canai，最高境界是叫店員「Banjir」（淹水之意）！店員會將滿滿的扁豆咖哩汁與參巴醬直接淋在撕碎的飛餅上，讓千層酥皮半浸汁半酥脆，絕頂美味！","en":"Mamak Slang \"Kuah Banjir\": In Malaysia, asking for \"Banjir\" (Flood) instructs the cook to literally flood your shredded roti with a deluge of warm dhal and sambal, giving you a sublime contrast of crispy and gravy-soaked bites!","ms":"Slanga Mamak \"Roti Canai Banjir\": Sebut sahaja perkataan \"Banjir\" bila memesan! Peniaga akan mencurahkan kuah dhal dan sambal hingga membanjiri pinggan untuk kenikmatan kuah meresap ke dalam roti.","ja":"ママックの裏技「クア・バンジール（洪水）」：注文時に「バンジール（洪水）」と言うと、お皿のロティが見えなくなるほどカレーとサンバルを並々と注いでくれます！ヒタヒタになった部分とサクサクの部分の対比が最高です。","ko":"마막 식당의 은어 \"쿠아 반지르(홍수)\": \"반지르(홍수)\"로 주문하면 로티 위에 달 커리와 삼발을 접시가 넘치도록 듬뿍 부어줍니다! 국물에 푹 적셔진 부분과 바삭한 부분의 조화가 환상적입니다."}]},{"country":"my","id":"hainanese-chicken-rice","slug":"hainanese-chicken-rice","title":{"zh-TW":"大馬海南雞飯配三色沾醬","en":"Malaysian Hainanese Chicken Rice & 3-Sauce Trio","ms":"Nasi Ayam Hainan Asli & Tiga Sos Istimewa","ja":"本場マレーシア・海南鶏飯（ハイナンチキンライス＆特製3種ダレ）","ko":"말레이시아 하이난 치킨라이스 & 삼색 특제 소스"},"subtitle":{"zh-TW":"冰鎮果凍皮脆嫩白斬雞・特香雞油紅蔥薑蒜飯・靈魂金桔辣醬與黑老抽","en":"Jelly-Skin Tender Poached Chicken, Fragrant Chicken-Fat Rice & Calamansi Chili Dip","ms":"Ayam Rebus Lembut Berjus, Nasi Minyak Ayam Harum & Sambal Cili Halia","ja":"ゼラチン皮がプルプルの蒸し鶏、鶏油とエシャロットの黄金炊き込みご飯、生姜チリだれ","ko":"젤리처럼 부드러운 껍질의 촉촉한 닭고기, 닭기름 생강 파 밥, 칼라만시 칠리소스"},"tagline":{"zh-TW":"瓊籍移民百年傳承智慧！將一隻雞與一鍋飯推向極致境界的平民國宴","en":"The hundred-year legacy of Hainanese diaspora, elevating humble chicken and rice to royal heights","ms":"Warisan kurun penghijrahan suku Hainan yang mengangkat hidangan ayam ke martabat diraja","ja":"100年を超える海南移民の知恵の結晶。鶏一羽の旨味をご飯の芯まで閉じ込めた至高の逸品","ko":"100년 역사의 하이난 화교들이 완성한 요리. 닭 한 마리의 모든 감칠맛을 밥 한 톨까지 담아낸 명작"},"heroImage":"/images/my/hainanese-chicken-rice.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":40,"defaultServings":4,"caloriesPerServing":560,"category":"mains","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"馬六甲、雪蘭莪與吉隆坡 (Melaka, Selangor, KL)","en":"Melaka, Selangor & Kuala Lumpur","ms":"Melaka & Kuala Lumpur","ja":"マラッカおよびクアラルンプール","ko":"말라카 및 쿠알라룸푸르"},"famousStreetMarkets":[{"zh-TW":"馬六甲雞場街中華茶室 (海南雞飯粒)","en":"Kedai Kopi Chung Wah (Chicken Rice Balls), Melaka","ms":"Kedai Kopi Chung Wah Melaka","ja":"中華茶室（マラッカ・チキンライスボール）","ko":"중화 다방 (말라카 치킨라이스 볼)"},{"zh-TW":"吉隆坡安邦南香海南雞飯","en":"Nam Heong Chicken Rice, Jalan Sultan, KL","ms":"Nam Heong Chicken Rice KL","ja":"南香海南鶏飯（KLスルタン通り）","ko":"남향 치킨라이스 (KL 술탄 거리)"}],"historyStory":{"zh-TW":"早年來自中國海南島的移民多受雇於英殖民家庭或遠洋輪船擔任主廚。他們將海南文昌雞的烹法融入南洋本土食材：用肥厚雞油爆香紅蔥頭、老薑與斑蘭葉煮出油亮噴香的米飯，整隻全雞慢火微沸浸熟後立刻投進冰水中「冰鎮激脆」，使表皮與肉質間凝聚出一層如晶瑩果凍般的皮凍膠原！佐以酸辣醒胃的鮮磨金桔辣椒醬、鮮薑蔥茸與黑老抽，成為星馬不可撼動的平民傳奇。","en":"Hainanese emigrants to Malaya served as chefs in British colonial households and maritime ships. They perfected Wenchang chicken with tropical Southeast Asian touches: rice sautéed in rendered golden chicken fat, shallots, ginger and knotted pandan leaves. The whole bird is gently poached at bare simmer, then plunged into ice baths to shock a layer of savory collagen jelly under the paper-thin golden skin. Served with a holy trinity of calamansi chili sauce, ginger-scallion paste, and thick dark soy.","ms":"Diperkenalkan oleh imigran Hainan pada kurun ke-19. Ayam direbus perlahan dan direndam air ais untuk menghasilkan lapisan agar-agar enak di bawah kulit. Beras ditumis dengan minyak lemak ayam, halia dan daun pandan.","ja":"19世紀、英領マラヤに移住した海南島出身者が考案。丸鶏を沸騰させない絶妙な温度で茹で、直後に氷水で一気に締めることで皮と肉の間に「コラーゲンの煮こごり（ジュレ）」を作ります。鶏油で炒めて炊いたご飯に、自家製の生姜ネギだれとチリだれをたっぷり絡めていただきます。","ko":"19세기 말레이 반도로 건너온 하이난 출신 이주민들이 정착시키며 탄생했습니다. 닭을 끓는 물에 은근히 익힌 뒤 얼음물에 급랭시켜 껍질과 살코기 사이에 젤리 같은 콜라겐 층을 만듭니다. 고소한 닭기름 밥과 세 가지 소스의 조화가 완벽합니다."},"malayScript":"Nasi Ayam Hainan","malayPhonetics":"Nah-see Ah-yahm Hye-nahn","audioPronunciationText":"Tauke, Nasi Ayam satu pinggan, paha ayam, sup lebih!","communityHeritage":"Chinese","nativeName":"Nasi Ayam Hainan","nativePhonetics":"Nasi Ayam Hainan"},"ingredients":[{"id":"whole-chicken","name":{"zh-TW":"優質三黃雞或走地雞 (約 1.3 - 1.5 kg)","en":"Quality Whole Free-Range Chicken (1.3 - 1.5 kg)","ms":"Ayam Kampung Bulat Segar","ja":"地鶏または丸鶏（1.3〜1.5kg）","ko":"신선한 영계 또는 토종닭 (1.3 - 1.5kg)"},"amount":1400,"unitMetric":"g","unitUS":"3 lb","isKeyFlavor":true,"malayName":"Ayam Bulat","malayPronunciation":"Ah-yahm Boo-laht"},{"id":"chicken-fat","name":{"zh-TW":"生雞油塊 (從雞腹中取下)","en":"Raw Chicken Fat (Trimmed from cavity)","ms":"Lemak Ayam Segar","ja":"鶏脂（チキンファット・内臓周辺の脂）","ko":"닭기름 덩어리 (닭 뱃속에서 떼어낸 지방)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":true,"malayName":"Lemak Ayam","malayPronunciation":"Leh-mahk Ah-yahm"},{"id":"rice-grains","name":{"zh-TW":"優質泰國茉莉香米 (洗淨瀝乾)","en":"Thai Jasmine Fragrant Rice (Washed & dried)","ms":"Beras Wangi Thai","ja":"ジャスミンライス（研いで水切り）","ko":"자스민 라이스 (씻어서 물기 뺌)"},"amount":300,"unitMetric":"g","unitUS":"1.5 cup","isKeyFlavor":false,"malayName":"Beras Wangi","malayPronunciation":"Beh-rahs Wah-ngee"},{"id":"ginger-shallot-pandan","name":{"zh-TW":"老薑厚片、紅蔥頭碎、拍蒜與香蘭葉","en":"Sliced Ginger, Shallots, Garlic & Knotted Pandan","ms":"Halia, Bawang Merah, Bawang Putih & Daun Pandan","ja":"スライス生姜、エシャロット、ニンニク、パンダンリーフ","ko":"편생강, 샬롯, 마늘, 매듭지은 판단잎"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"malayName":"Halia & Pandan","malayPronunciation":"Hah-lee-ah dahn Pahn-dahn"},{"id":"chili-sauce-trio","name":{"zh-TW":"三色沾醬：金桔辣椒醬、純薑蔥油蓉、大馬特濃老抽黑醬油","en":"3-Sauce Trio: Calamansi Chili Dip, Ginger-Scallion Oil & Thick Dark Soy","ms":"Tiga Sos: Sambal Cili Limau, Minyak Halia Daun Bawang & Kicap Pekat","ja":"特製3種ダレ：生姜チリだれ、ネギ生姜油、濃厚黒醤油","ko":"삼색 소스: 칼라만시 칠리 소스, 대파 생강 기름장, 달콤한 흑간장"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"malayName":"Tiga Sos Istimewa","malayPronunciation":"Tee-gah Sohs Ees-tee-meh-wah"}],"steps":[{"stepNumber":1,"image":"/images/my/hainanese-chicken-rice-step1.jpg","title":{"zh-TW":"整雞浸泡低溫微沸慢煮 (浸雞法)","en":"Submerge & Poach Whole Chicken at Gentle Simmer","ms":"Celup & Rebus Ayam Perlahan (Teknik Rendam)","ja":"丸鶏を沸騰させず低温でじっくり火を通す（浸鶏法）","ko":"약불에서 끓이지 않고 은근하게 익혀내기 (침계법)"},"instruction":{"zh-TW":"深大鍋中燒滾能沒過全雞的水，加入蔥段、薑片、拍蒜與 1 大匙海鹽。抓住雞頭將整雞浸入滾水中燙 10 秒，提起瀝水，重複「三提三浸」使內外腔溫度一致。隨後整雞完全浸入水中，加蓋轉極微火（水面微冒微小氣泡，約 85-90°C），慢浸煮 35-40 分鐘，筷子扎入大腿最厚處無血水冒出即可。","en":"Bring a deep pot of water to boil with scallions, ginger slices and salt. Hold chicken by neck and submerge into boiling water for 10 secs, lift out, repeat 3 times to equalize inner/outer temps. Lower bird fully, cover and reduce heat to bare sub-boil simmer (85-90°C) for 35-40 mins until thigh juice runs crystal clear.","ms":"Didihkan air bersama daun bawang, halia dan garam. Buat teknik celup dan angkat ayam 3 kali. Masukkan ayam sepenuhnya, tutup dan reneh api paling kecil (85-90°C) selama 35-40 minit.","ja":"大鍋に湯を沸かし、ネギ、生姜、塩を入れます。鶏の首を持って湯に10秒浸して持ち上げる動作を3回繰り返し、内外の温度を均一にします。その後全体を沈め、沸騰させない極微火（約85〜90℃）で35〜40分じっくり浸し煮にします。","ko":"큰 냄비에 물을 넉넉히 붓고 대파, 생강, 소금을 넣어 끓입니다. 닭 목을 잡고 끓는 물에 10초간 넣었다 빼는 과정을 3번 반복합니다. 완전히 담근 후 끓어오르지 않는 약불(85-90℃)에서 35-40분간 은근히 익힙니다."},"durationSeconds":2400,"crucialTips":{"zh-TW":"水絕對不能劇烈大滾！否則雞胸肉纖維會縮緊變柴、皮破肉爛。始終維持「菊花微沸」（水面隱隱微動）是多汁神技！","en":"Never let the water violently boil! Rapid rolling bubbles seize the breast fibers and shred the skin. Maintain a peaceful sub-simmer.","ms":"Jangan biarkan air mendidih buak! Haba tinggi akan mengeraskan daging dada ayam dan mengoyakkan kulit.","ja":"絶対に強火でグラグラ沸騰させてはいけません！水面が静かに揺れる程度の微沸騰を保つことで、胸肉までしっとりジューシーに仕上がります。","ko":"물이 팔팔 끓게 두지 마세요! 센 불로 끓이면 닭가슴살이 퍽퍽해지고 껍질이 찢어집니다. 물결이 잔잔하게 유지되는 온도를 지키세요."}},{"stepNumber":2,"image":"/images/my/hainanese-chicken-rice-step2.jpg","title":{"zh-TW":"冰水激脆急冷・鎖住晶瑩皮凍 (Ice Shock)","en":"Ice Bath Shock to Lock in Glossy Collagen Jelly","ms":"Rendam Air Ais Segera untuk Kulit Rangup & Agar-Agar","ja":"氷水に即座に沈め、プルプルのジュレ層を作る（アイスショック）","ko":"얼음물에 즉시 담가 탱글탱글한 콜라겐 층 형성하기"},"instruction":{"zh-TW":"準備一大盆盛滿冰塊的冰水。將熟雞撈出立刻完全浸入冰水中激凍 15-20 分鐘。急劇溫差會讓雞皮瞬間收緊變脆，表皮下的皮下脂肪與膠原蛋白瞬間凝結成一層如天然肉凍般晶瑩剔透的皮凍！取出瀝乾，表面刷上一層純芝麻香油保濕防乾。","en":"Plunge the hot poached chicken straight into a deep bath filled with ice cubes and cold water for 15-20 mins. The violent thermal shock instantly snaps the skin taut and solidifies the underlying collagen broth into a sensational savory jelly mantle! Remove, pat dry, and brush skin with toasted sesame oil.","ms":"Angkat ayam panas dan terus rendam dalam air batu berketul selama 15-20 minit. Kejutan suhu sejuk membekukan kolagen menjadi lapisan agar-agar lazat. Angkat dan sapu minyak bijan.","ja":"茹で上がった熱々の鶏を、氷がぎっしり入った冷水に即座にドボンと沈めて15〜20分冷却します。急冷によって皮がキュッと引き締まり、皮下に極上のコラーゲンジュレが完成！取り出したらごま油を塗って乾燥を防ぎます。","ko":"잘 익은 뜨거운 닭을 건져 얼음이 가득 담긴 냉수에 즉시 담가 15-20분간 식힙니다. 급격한 온도차로 껍질이 탱글탱글해지며 껍질 아래에 투명한 닭육수 젤리층이 형성됩니다! 건져서 참기름을 고루 발라줍니다."},"durationSeconds":1200},{"stepNumber":3,"image":"/images/my/hainanese-chicken-rice-step3.jpg","title":{"zh-TW":"雞油炒生米・高湯燜蒸油亮香蘭雞飯","en":"Render Golden Chicken Fat & Steam Pandan Rice in Broth","ms":"Tumis Beras Dengan Lemak Ayam & Tanak Nasi Wangi","ja":"鶏油で生米を炒め、濃厚チキンスープで黄金ライスを炊く","ko":"닭기름에 쌀을 볶아 진한 닭 육수로 고슬고슬한 밥 짓기"},"instruction":{"zh-TW":"取下雞腹多餘生雞油切丁，平底鍋慢火煸出透明澄黃的雞油，撈出油渣。下紅蔥頭碎、薑末與拍蒜炒至焦黃酥香。倒入洗淨瀝乾的香米中火煸炒 2 分鐘，使每粒米均勻裹上香濃雞油。將米移入電鍋，倒入浸雞留下的鮮雞高湯（米水比 1:1.1）、加入 2 片薑、1 茶匙鹽與 2 根打結香蘭葉，煮成粒粒分明、油亮噴香的海南雞飯！","en":"Render chicken fat chunks in pan until liquid gold oil is extracted. Sauté minced shallots, ginger and garlic until golden and fragrant. Toss in drained raw jasmine rice; stir-fry for 2 mins to coat every grain in aromatic chicken fat. Transfer to rice cooker, add reserved poaching chicken stock (1:1.1 ratio), pandan knot and salt. Cook until grains are glistening, separate and intoxicatingly fragrant!","ms":"Cairkan lemak ayam dalam kuali hingga menjadi minyak wangi keemasan. Tumis bawang merah, halia dan bawang putih. Masukkan beras wangi, goreng 2 minit hingga bersalut minyak. Masak dalam periuk nasi bersama air rebusan ayam, daun pandan dan garam.","ja":"鶏脂を弱火で熱して黄金色のチキンオイルを抽出。エシャロット、生姜、ニンニクを炒め、研いだ生米を加えて2分炒め合わせます。炊飯器に移し、鶏の茹で汁、塩、パンダンリーフを入れて通常炊飯。粒立ちが美しく香ばしいご飯が完成します。","ko":"팬에 닭기름을 둘러 녹여낸 뒤 샬롯, 다진 생강, 마늘을 노릇하게 볶습니다. 물기 뺀 쌀을 넣고 2분간 볶아 닭기름으로 코팅합니다. 밥솥에 볶은 쌀과 닭 육수, 소금, 판단잎을 넣고 밥을 지어냅니다."},"durationSeconds":1500},{"stepNumber":4,"image":"/images/my/hainanese-chicken-rice-step4.jpg","title":{"zh-TW":"全雞斬件滑切・配三色沾醬盛盤","en":"Carve Succulent Chicken & Plate with 3-Sauce Trio","ms":"Potong Ayam Cantik & Hidang Bersama Tiga Sos","ja":"鶏肉を美しく切り分け、特製3種ダレを添えて盛り付ける","ko":"닭고기를 먹기 좋게 썰어 세 가지 소스와 함께 서빙"},"instruction":{"zh-TW":"將冰鎮好的雞斬成適口厚塊，排在黃瓜厚片上。淋上 1 大匙特調生抽香油汁。隨盤奉上三大靈魂沾醬：① 鮮紅金桔生辣椒醬（蒜末、紅椒、金桔汁）；② 碧綠鮮薑蔥蓉油；③ 馬來西亞特濃黑醬油。舀一勺熱騰騰雞油飯，夾一塊果凍皮嫩雞，沾上三色醬料，人間至味！","en":"Chop chicken into glossy slices, arrange over crunchy cucumber planks. Drizzle with a mixture of light soy and sesame oil. Serve alongside the 3 iconic sauces: ① Fiery Calamansi Chili Dip, ② Aromatic Scallion-Ginger Paste, and ③ Thick Caramel Black Soy. Savor a spoonful of steaming chicken-fat rice capped with tender jelly-skinned chicken!","ms":"Potong ayam cantik dan susun atas hirisan timun. Renjis sedikit kicap cair dan minyak bijan. Hidang bersama nasi panas dan 3 sos: Sambal cili limau kasturi, pes halia daun bawang dan kicap pekat karamel.","ja":"鶏肉を食べやすくカットし、きゅうりの上に盛り付けます。特製醤油だれをひと回し。3種の特製ダレ（①カラマンシーチリ、②ネギ生姜油、③濃厚黒醤油）と熱々のご飯を添えて完成です！","ko":"닭고기를 먹기 좋게 썰어 오이 위에 담고, 양조간장과 참기름을 살짝 뿌립니다. 세 가지 소스(칼라만시 칠리, 파 생강 기름장, 흑간장)와 닭기름 밥을 곁들여 완성합니다."},"durationSeconds":300}],"troubleshooting":[{"id":"rice-dry","problem":{"zh-TW":"煮出的雞飯不夠香潤油亮","en":"Rice lacks deep aroma and glossy sheen","ms":"Nasi ayam kering dan kurang wangi","ja":"チキンライスの香りと油気が足りない","ko":"밥이 기름지지 않고 향이 덜함"},"cause":{"zh-TW":"使用了普通清水炊飯，或未先用雞油炒生米","en":"Used plain water instead of rich poaching stock or skipped frying rice in fat","ms":"Guna air paip biasa atau tidak tumis beras dengan lemak","ja":"水で炊いてしまった、または鶏油で米を炒める工程を省いた","ko":"닭 육수 대신 맹물을 썼거나 쌀을 닭기름에 볶지 않음"},"solution":{"zh-TW":"務必使用浸雞留下的表面浮油與金黃高湯煮飯，煮前生米必須與紅蔥雞油充分煸炒至透光！","en":"Always boil rice in the rich surface-poaching broth and thoroughly coat raw rice in rendered chicken fat shallot oil.","ms":"Wajib gunakan air rebusan ayam yang berlemak dan tumis beras sehingga berkilat.","ja":"必ず鶏を茹でた出汁の上澄み油とスープを使って炊き、事前にエシャロット鶏油で米をしっかり炒めてください。","ko":"반드시 닭을 삶아낸 진한 육수와 닭기름으로 밥을 짓고, 취사 전 쌀을 닭기름에 볶아주세요."}}],"proTips":[{"zh-TW":"老饕吃法三部曲：吃第一口雞肉時先沾金桔酸辣醬解鎖肉質鮮美；第二口抹上生薑蔥油感受清新蔥香；第三口沾濃稠如墨的大馬黑醬油與雞油飯大口扒入嘴中，三種層次千變萬化！","en":"The 3-Bite Masterclass: Bite 1: Dip in calamansi chili for zesty fireworks. Bite 2: Top with ginger-scallion paste for fragrant herbal luxury. Bite 3: Dredge into thick dark caramel soy and shovel with glistening chicken rice!","ms":"Tiga Langkah Menikmati: Suapan pertama cicah sambal cili limau, suapan kedua calit pes halia daun bawang, suapan ketiga gaul kicap pekat karamel bersama nasi ayam hangat!","ja":"3口の美食体験：1口目はライムチリだれでジューシーな肉の甘みを引き出し、2口目はネギ生姜だれで上品な香りを堪能、3口目は濃厚黒醤油をつけてご飯と一緒に頬張るのが至高の楽しみ方！","ko":"삼색 소스 즐기기: 첫 입은 칼라만시 칠리로 깔끔하게, 두 번째 입은 파 생강장으로 향긋하게, 세 번째 입은 흑간장을 듬뿍 찍어 밥과 함께 크게 한 숟가락 드셔보세요!"}]},{"country":"my","id":"kl-hokkien-mee","slug":"kl-hokkien-mee","title":{"zh-TW":"吉隆坡茨廠街福建黑炒麵 (大碌麵)","en":"Kuala Lumpur Chinatown Dark Hokkien Mee","ms":"Mee Hokkien Hitam Arang Petaling Street KL","ja":"KLチャイナタウン・名物黒炒め福建麺（大碌麺）","ko":"쿠알라룸푸르 차이나타운 칠흑빛 호키엔 미 (다이록미)"},"subtitle":{"zh-TW":"炭火猛鑊・特濃焦香黑老抽・酥脆豬油渣與比目魚左口魚鐵鑊香","en":"Charcoal Blaze, Thick Black Caramel Glaze, Crispy Pork Lard & Flounder Powder","ms":"Kuali Arang Membara, Kicap Karamel Hitam, Minyak Babi Garing & Serbuk Ikan Kering","ja":"炭火の強火力、濃厚カラメル黒醤油、カリカリ豚脂かすとカレイの粉末","ko":"숯불 웍의 강렬한 불맛, 진한 캐러멜 흑간장, 바삭한 라드 크랙클링과 가자미 가루"},"tagline":{"zh-TW":"吉隆坡華人傳承近百年的深夜碳水霸王！黑得發亮、香得入骨","en":"The legendary hundred-year nocturnal street noodle of Chinese Kuala Lumpur","ms":"Raja mi goreng malam warisan kurun di tengah ibu kota Kuala Lumpur","ja":"クアラルンプールで100年愛される深夜のソウルフード！黒光りする濃厚な麺の至福","ko":"쿠알라룸푸르에서 100년간 사랑받아온 심야의 제왕! 검고 윤기 흐르는 불맛의 극치"},"heroImage":"/images/my/kl-hokkien-mee.jpg","difficulty":"hard","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":650,"category":"noodles","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中馬・吉隆坡茨廠街唐人街 (Petaling Street, KL)","en":"Petaling Street, Kuala Lumpur","ms":"Jalan Petaling, Kuala Lumpur","ja":"クアラルンプール・ペタリン通り中華街","ko":"쿠알라룸푸르 페탈링 거리"},"famousStreetMarkets":[{"zh-TW":"茨廠街金蓮記百年炭火老店 (創始店)","en":"Kim Lian Kee (Originator 1927), Petaling Street, KL","ms":"Kim Lian Kee Petaling Street","ja":"金蓮記（1927年創業元祖店）","ko":"김련기 (1927년 창업 원조집)"},{"zh-TW":"吉隆坡增江陳記炒麵","en":"Jinjang Tan Kee Hokkien Mee, KL","ms":"Tan Kee Jinjang","ja":"陳記福建炒麺（ジンジャン）","ko":"진장 탄키 호키엔 미"}],"historyStory":{"zh-TW":"1927 年，由福建安溪移民王金蓮在吉隆坡茨廠街挑擔擺攤創製。吉隆坡氣候濕熱，南洋顧客嫌傳統清淡福建湯麵不夠過癮。王金蓮大膽改良：選用粗壯彈牙的黃鹼麵（大碌麵），以現煉豬油高溫炒香五花肉片、鮮蝦、魷魚與高麗菜，加入長時間暴晒發酵的特濃黑老抽（晒油）與烤香的比目魚乾粉（左口魚粉），在炭火大鐵鑊中燜炒至收汁黏稠、黑亮噴香，震撼整個南洋！","en":"Invented in 1927 by Ong Kim Lian on Petaling Street. Locals demanded more bold, visceral flavors than delicate southern Chinese broths. He pioneered using thick alkaline yellow noodles braised over raging charcoal fires with freshly rendered pork lard, pork slices, prawns, cabbage, thick sun-aged black caramel soy sauce, and a secret pinch of roasted ground flounder fish powder (ti-poh).","ms":"Dicipta pada tahun 1927 oleh imigran Fujian, Ong Kim Lian di Petaling Street. Menggunakan mee kuning tebal (Tai Lok Mee), minyak babi garing, udang, sotong dan kicap pekat karamel hitam yang dimasak atas kuali arang.","ja":"1927年にペタリン通りで屋台を開いた王金蓮氏が考案。太いアルカリ黄色麺（大碌麺）を使い、豚ラード、エビ、イカ、キャベツと共に真っ黒な特濃カラメル醤油と乾燥カレイの粉末で汁気がなくなるまで強火で焼き付けます。","ko":"1927년 페탈링 거리의 노점에서 왕김련 씨가 개발했습니다. 굵은 면발(다이록미)을 신선한 돼지기름, 해산물, 양배추, 흑간장, 그리고 구운 가자미 가루와 함께 숯불 웍에서 국물이 자작해질 때까지 볶아냅니다."},"malayScript":"Mee Hokkien Hitam KL","malayPhonetics":"Mee Hoke-kee-ehn Hee-tahm K-L","audioPronunciationText":"Tauke, Hokkien Mee satu bungkus, garing lebih, cili sambal asing!","communityHeritage":"Chinese","nativeName":"Mee Hokkien Hitam KL","nativePhonetics":"Mee Hokkien Hitam KL"},"ingredients":[{"id":"tai-lok-mee","name":{"zh-TW":"特粗黃鹼麵 (大碌麵 / 福建麵條)","en":"Thick Alkaline Yellow Noodles (Tai Lok Mee)","ms":"Mee Kuning Tebal (Tai Lok Mee)","ja":"太アルカリ黄色麺（大碌麺 / タイロックミー）","ko":"굵은 알칼리 노란 면 (다이록미)"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"malayName":"Mee Tai Lok","malayPronunciation":"Mee Tie Lohk"},{"id":"lard-cracklings-kl","name":{"zh-TW":"新鮮現煉純豬油與金黃酥脆豬油渣","en":"Fresh Rendered Pork Lard & Golden Cracklings (Zhu You Zha)","ms":"Minyak Babi & Sisa Minyak Garing","ja":"自家製ラード＆香ばしい豚脂かす（猪油渣）","ko":"신선한 돼지기름(라드) & 바삭한 라드 크랙클링"},"amount":60,"unitMetric":"g","unitUS":"4 tbsp","isKeyFlavor":true,"malayName":"Minyak Garing","malayPronunciation":"Meen-yahk Gah-reeng"},{"id":"ti-poh-powder","name":{"zh-TW":"烘烤比目魚乾粉 (左口魚粉 / 大地魚粉)","en":"Roasted Dried Flounder Powder (Ti Poh / Sole Fish)","ms":"Serbuk Ikan Kering Panggang (Ti Poh)","ja":"焙煎乾燥ヒラメ・カレイ粉末（左口魚粉 / ティーポー）","ko":"구운 건가자미 가루 (티포 파우더)"},"amount":8,"unitMetric":"g","unitUS":"1.5 tsp","isKeyFlavor":true,"malayName":"Serbuk Ikan Kering","malayPronunciation":"Sehr-book Ee-kahn Keh-reeng"},{"id":"pork-belly-slices","name":{"zh-TW":"五花肉片 (切薄片)","en":"Pork Belly (Thinly sliced)","ms":"Daging Babi / Ayam Dihiris","ja":"豚バラ肉（薄切り）","ko":"삼겹살 (얇게 썬 것)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":false,"malayName":"Daging Hiris","malayPronunciation":"Dah-geeng Hee-rees"},{"id":"prawns-squid-mix","name":{"zh-TW":"鮮蝦仁與鮮魷魚圈","en":"Fresh Prawns & Tender Squid Rings","ms":"Udang Laut & Sotong Segar","ja":"生エビ＆イカリング","ko":"신선한 새우 & 오징어 링"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":false,"malayName":"Udang & Sotong","malayPronunciation":"Oo-dahng dahn Soh-tohng"},{"id":"cabbage-leaves","name":{"zh-TW":"包菜 (高麗菜 / 切厚片)","en":"Green Cabbage (Cut into bite-sized squares)","ms":"Kubis Bulat Segar","ja":"キャベツ（ざく切り）","ko":"양배추 (큼직하게 썬 것)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":false,"malayName":"Kubis","malayPronunciation":"Koo-bees"},{"id":"black-caramel-sauce-kl","name":{"zh-TW":"大馬老字號特濃焦香黑老抽 (晒油)","en":"Thick Black Caramel Soy Sauce (Sai Yau)","ms":"Kicap Pekat Karamel Pekat","ja":"特級マレーシア焦がし黒老抽（晒油）","ko":"말레이시아 전통 특농 캐러멜 흑간장"},"amount":40,"unitMetric":"ml","unitUS":"2.5 tbsp","isKeyFlavor":true,"malayName":"Kicap Pekat Karamel","malayPronunciation":"Kee-chahp Peh-kaht"},{"id":"rich-stock-broth","name":{"zh-TW":"濃豬骨高湯或鮮蝦高湯","en":"Rich Pork Bone Broth or Shrimp Stock","ms":"Stok Tulang Rebusan Pekat","ja":"濃厚豚骨スープまたはエビ出汁","ko":"진한 돼지 뼈 육수 또는 새우 육수"},"amount":200,"unitMetric":"ml","unitUS":"7 fl oz","isKeyFlavor":false,"malayName":"Stok Pekat","malayPronunciation":"Stohk Peh-kaht"}],"steps":[{"stepNumber":1,"image":"/images/my/kl-hokkien-mee-step1.jpg","title":{"zh-TW":"鐵鑊大火煸五花肉與海鮮","en":"Sear Pork Belly & Seafood in Hot Lard","ms":"Tumis Daging, Udang & Sotong Dalam Minyak Babi Panas","ja":"熱々のラードで豚バラ肉と海鮮を一気に炒める","ko":"뜨거운 라드에 삼겹살과 해산물을 강불로 볶기"},"instruction":{"zh-TW":"生鐵鑊大火燒至白煙四溢，下 2 大匙香濃豬油。放入薄切五花肉片煸出焦香油脂，接著下拍碎蒜粒、鮮蝦仁與魷魚圈大火爆炒 30 秒至微熟，蝦身捲起變紅。","en":"Heat cast iron wok until smoking furiously. Add 2 tbsp pork lard. Sauté sliced pork belly until fat renders and edges brown. Drop in minced garlic, peeled prawns and squid rings. Stir-fry for 30 secs until prawns turn pink.","ms":"Panaskan kuali besi hingga berasap. Masukkan 2 sb minyak babi. Goreng hirisan daging hingga garing, kemudian masukkan bawang putih, udang dan sotong selama 30 saat.","ja":"鉄鍋から煙が立つまで強火で熱し、ラード大さじ2を入れます。豚バラ肉を炒めて脂を出し、ニンニク、エビ、イカを投入して30秒一気に炒めます。","ko":"무쇠 웍을 연기가 날 때까지 달군 뒤 라드 2큰술을 넣습니다. 삼겹살을 볶아 기름을 낸 뒤 다진 마늘, 새우, 오징어를 넣고 30초간 강하게 볶아냅니다."},"durationSeconds":45},{"stepNumber":2,"image":"/images/my/kl-hokkien-mee-step2.jpg","title":{"zh-TW":"粗麵下鍋・注入特濃黑老抽與高湯燜透","en":"Add Thick Noodles, Black Caramel Soy & Simmer in Stock","ms":"Masukkan Mee Tebal, Kicap Pekat & Reneh Bersama Stok","ja":"極太麺を投入、特濃黒醤油とスープを加えて蓋をして煮込む","ko":"굵은 면을 넣고 특농 흑간장과 육수를 부어 뜸 들이며 볶기"},"instruction":{"zh-TW":"放入粗大碌麵與包菜塊。沿著滾燙鍋邊淋入 40ml 特濃焦香黑老抽（晒油）、1 大匙生抽、1 茶匙糖與 200ml 濃骨高湯。蓋上鍋蓋，轉中大火燜煮 3-4 分鐘！高溫蒸汽與黑醬油會深層滲透進粗麵的毛孔內部，軟化麵芯並染上油亮的黑曜石色澤。","en":"Add thick noodles and cabbage. Swirl 40ml dark caramel soy, 1 tbsp light soy, 1 tsp sugar and 200ml rich bone stock down scorching wok edges. Cover with lid and braise over medium-high for 3-4 mins! The intense steam forces the smoky caramel soy deep into the heart of the thick noodles.","ms":"Masukkan mee kuning tebal dan kubis. Tuang 40ml kicap pekat karamel, kicap cair, gula dan 200ml stok rebusan. Tutup kuali 3-4 minit atas api kuat agar warna hitam meresap ke dalam mee.","ja":"大碌麺とキャベツを投入。鍋肌から黒醤油40ml、薄口醤油、砂糖、濃厚スープ200mlを回し入れます。蓋をして強火で3〜4分蒸し煮にし、麺の芯まで真っ黒なタレの旨味を染み込ませます。","ko":"다이록미 면과 양배추를 넣습니다. 웍 가장자리에 흑간장 40ml, 진간장, 설탕, 육수 200ml를 두르고 뚜껑을 덮어 강불에서 3-4분간 푹 조리듯 끓여 면의 속까지 검은 소스가 배어들게 합니다."},"durationSeconds":240},{"stepNumber":3,"image":"/images/my/kl-hokkien-mee-step3.jpg","title":{"zh-TW":"開蓋大火收汁・撒入左口魚粉與酥脆豬油渣","en":"Uncover, Flash-Reduce to Sticky Glaze with Ti Poh & Cracklings","ms":"Buka Penutup, Goreng Kering Bersama Serbuk Ti Poh & Minyak Garing","ja":"蓋を開け強火で煮詰め、カレイ粉末とカリカリ豚脂かすを投入","ko":"뚜껑을 열고 센 불로 조려 가자미 가루와 라드 크랙클링 넣기"},"instruction":{"zh-TW":"掀開鍋蓋，轉最大猛火！用鐵鏟快速翻炒進行「收汁」。均勻撒入靈魂秘器——1.5 茶匙烘烤比目魚乾粉（左口魚粉）與一把酥脆的豬油渣。湯汁在極高溫下迅速收斂成黏稠亮澤的黑金醬膜，每一根麵條均勻裹上焦香鑊氣！","en":"Remove lid, crank heat to maximum! Furiously flip noodles to reduce sauce into a rich, glossy, sticky lacquer. Scatter in the secret weapon: 1.5 tsp roasted flounder powder (ti poh) and a generous handful of golden pork cracklings. The intense heat binds the smoky seafood umami around every noodle strand!","ms":"Buka penutup, kuatkan api paling maksima! Gaul pantas hingga kuah menjadi likat berkilat. Taburkan serbuk ikan kering (ti poh) dan sisa minyak babi garing. Setiap urat mee disalut aroma asap kuali!","ja":"蓋を取り、最大火力に！手早く煽ってタレをトロリと煮詰めます。秘伝のカレイ粉末（ティーポー）とカリカリの豚脂かすを一気に投入。濃厚な黒いタレが麺にピタリと吸い付きます！","ko":"뚜껑을 열고 화력을 최대로 올립니다! 빠르게 볶으며 소스를 졸이다가 비밀 병기인 구운 가자미 가루와 바삭한 라드 크랙클링을 뿌립니다. 진한 검은 소스가 면에 착 달라붙을 때까지 볶아냅니다."},"durationSeconds":90,"crucialTips":{"zh-TW":"左口魚粉（比目魚乾粉）是吉隆坡百年炒麵靈魂！它帶來深邃無法言喻的天然海鮮鮮味，絕非味精能比擬！","en":"Ti Poh (flounder powder) is the secret soul of genuine KL Hokkien Mee! It imparts an earthy, profound umami depth that MSG can never imitate.","ms":"Serbuk ikan kering ti poh adalah rahsia keaslian mee Hokkien KL yang memberi rasa umami laut mendalam.","ja":"カレイ粉末（ティーポー）こそ元祖の魂！化学調味料では出せない、魚介の濃厚な奥行きが口いっぱいに広がります。","ko":"티포(구운 가자미 가루)는 쿠알라룸푸르 호키엔 미의 핵심 비법입니다! 깊은 바다의 감칠맛을 폭발시켜 줍니다."}},{"stepNumber":4,"image":"/images/my/kl-hokkien-mee-step4.jpg","title":{"zh-TW":"黑亮出鍋・附靈魂參巴辣醬盛盤","en":"Slide Onto Plate with Calamansi Sambal Belacan","ms":"Tuang Atas Pinggan Bersama Sambal Belacan Pedas","ja":"黒光りする麺を皿に盛り、特製サンバルを添えて完成","ko":"검게 윤기 나는 국수를 접시에 담고 삼발 소스 곁들여 완성"},"instruction":{"zh-TW":"起鍋滑入大盤，表面再點綴數顆金黃金脆的豬油渣。附上一小碟鮮榨金桔參巴辣醬（Sambal Belacan）。大口吸入滿滿鑊氣焦香的黑粗麵，豬油渣在齒間爆脆，這就是吉隆坡最銷魂的深夜滋味！","en":"Slide the pitch-black glistening noodles onto plate, crowned with extra crunchy pork cracklings. Serve with a side dish of fiery calamansi Sambal Belacan. Slurp the smoky, chewy noodles while the cracklings shatter between your teeth!","ms":"Tuang mee hitam berkilat atas pinggan, tabur lebih minyak garing di atasnya. Hidang bersama piring sambal belacan limau kasturi.","ja":"黒く輝く麺をお皿に盛り付け、さらにカリカリの豚脂かすをトッピング。ライム入りサンバルチリを添えていただきます！モッチリした麺とサクサクの脂かすの対比が絶品。","ko":"칠흑빛의 윤기 나는 국수를 접시에 담고 바삭한 라드 크랙클링을 위에 얹어냅니다. 매콤한 칼라만시 삼발 소스를 곁들여 드세요!"},"durationSeconds":30}],"troubleshooting":[{"id":"color-too-pale","problem":{"zh-TW":"炒出的麵顏色偏淺偏黃，不夠黑亮","en":"Noodles look pale brown instead of pitch-black glossy","ms":"Mee warna pudar tidak hitam berkilat","ja":"麺の色が薄く、本場のような真っ黒な艶がない","ko":"면의 색이 연하고 특유의 칠흑빛 윤기가 나지 않음"},"cause":{"zh-TW":"使用了普通生抽老抽，缺少馬來西亞特產的濃稠晒油 (Kicap Pekat)","en":"Used standard soy sauce lacking Malaysian thick caramel black soy","ms":"Guna kicap cair biasa tanpa kicap pekat karamel masakan","ja":"通常の醤油を使用し、マレーシア特産のカラメル黒老抽を使っていない","ko":"일반 간장을 사용해 말레이시아 특유의 걸쭉한 흑간장이 부족함"},"solution":{"zh-TW":"務必購買正宗大馬晒油或老抽；應急時可在生抽中加入 1 大匙黑糖蜜慢熬濃縮。","en":"Must use authentic Malaysian thick caramel soy (Sai Yau) or reduce dark soy with dark molasses.","ms":"Wajib gunakan kicap pekat karamel masakan asli Malaysia.","ja":"必ずマレーシアの「晒油（カラメル黒醤油）」を使用してください。ない場合はダークソイソースに黒蜜を加えて煮詰めます。","ko":"반드시 말레이시아산 흑간장(사이유)을 사용하거나 진간장에 흑설탕/몰라세스를 졸여서 색을 내세요."}}],"proTips":[{"zh-TW":"神級吃法：一定要將隨盤附上的「酸柑參巴醬（Sambal）」拌一小口到麵上！辛酸的辣椒醬能瞬間中和黑醬油與豬油的濃郁，激發出第二層更深層次的回甘！","en":"Local Ritual: Dab a forkful of fiery Sambal Belacan into the noodles! The tart lime acid and chili heat cut right through the rich lard and caramel soy, unlocking a secondary wave of sweet umami.","ms":"Petua Otai: Calit sambal belacan limau kasturi ke atas mee! Rasa masam pedas akan memotong lemak minyak babi dan membangkitkan kemanisan karamel kicap.","ja":"地元民の極意：添えられた「ライムサンバルチリ」を少し麺に絡めて食べてみてください！チリの辛みと酸味がラードの濃厚さをリセットし、新たな旨味の波が押し寄せます。","ko":"현지인 먹팁: 함께 나오는 칼라만시 삼발 소스를 국수 위에 살짝 얹어 비벼 드세요! 상큼한 산미와 매운맛이 라드의 느끼함을 잡아주며 극상의 단짠 풍미를 만듭니다."}]},{"country":"my","id":"ipoh-hor-fun","slug":"ipoh-hor-fun","title":{"zh-TW":"怡保舊街場雞絲蝦湯沙河粉","en":"Ipoh Shredded Chicken & Prawn Hor Fun","ms":"Kuey Teow Sup Ayam & Udang Pekan Lama Ipoh","ja":"イポー名物・極上チキン＆海老出汁の蒸し鶏フォーファン","ko":"이포 올드타운 닭고기 새우 맑은탕 쌀국수 (호펀)"},"subtitle":{"zh-TW":"絲滑薄透沙河粉・金紅蝦頭油老母雞濃湯・爽脆怡保短肥芽菜","en":"Silky Translucent Rice Noodles, Golden Prawn-Head Broth & Plump Ipoh Bean Sprouts","ms":"Kuey Teow Lembut Halus, Kuah Stok Udang Minyak Merah & Taugeh Rangup","ja":"絹のように滑らかな米平麺、黄金色のエビ油チキンスープ、極太シャキシャキもやし","ko":"비단결처럼 부드러운 쌀국수, 황금빛 새우머리 기름 닭 육수, 아삭한 이포 숙주나물"},"tagline":{"zh-TW":"霹靂山城喀斯特地下泉水的天然恩賜！清甜滑順天下第一","en":"A culinary gift from Ipoh’s limestone karst mountain springs—the world’s silkiest noodle soup","ms":"Pemberian alam dari punca air batu kapur bukit Ipoh, sup mee paling halus dan manis","ja":"石灰岩山地の天然湧き水が育んだ奇跡。世界一なめらかな米麺と澄んだエビスープの至福","ko":"석회암 산악 지하수가 빚어낸 천연의 선물! 세상에서 가장 부드러운 쌀국수"},"heroImage":"/images/my/ipoh-hor-fun.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":40,"defaultServings":2,"caloriesPerServing":460,"category":"noodles","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"北馬・霹靂怡保舊街場 (Ipoh Old Town, Perak)","en":"Ipoh Old Town, Perak","ms":"Pekan Lama Ipoh, Perak","ja":"ペラ州イポー・オールドタウン","ko":"페락 이포 올드타운"},"famousStreetMarkets":[{"zh-TW":"怡保舊街場天津茶室 (雞絲河粉)","en":"Thean Chun Coffee Shop (House of Mirrors), Ipoh","ms":"Restoran Thean Chun Ipoh","ja":"天津茶室（鏡の家）","ko":"티안춘 다방 (거울의 집)"},{"zh-TW":"怡保樂會居茶室","en":"Restoran Lok Hoi Fong, Ipoh","ms":"Lok Hoi Fong Ipoh","ja":"楽会居茶室","ko":"록호이퐁 다방"}],"historyStory":{"zh-TW":"20 世紀初由廣東移民帶入馬來西亞錫礦之都怡保。怡保被壯麗的喀斯特石灰岩群山環抱，富含碳酸鈣等天然礦物質的純淨地下泉水，使研磨蒸製出的沙河粉比世界任何地方都更加薄透、滑溜如絲，吸入口中甚至無須咀嚼便順喉而下！湯底以老雞骨加大量鮮蝦頭慢火熬煮，起鍋前淋上一勺紅艷的現熬純蝦油（Minyak Udang），鮮甜至極。","en":"Brought by Cantonese tin miners in the 1900s. Surrounded by limestone karst peaks, Ipoh’s alkaline mineral spring water yields rice noodles so gossamer, translucent and slippery that they glide down your throat without chewing! The broth combines stewed old fowl and mountains of prawn shells, crowned with an amber swirl of fragrant prawn-head oil.","ms":"Dibawa oleh imigran Kantonis ke bandar perlombongan timah Ipoh. Air mata air batu kapur yang kaya mineral menjadikan kuey teow Ipoh paling halus dan licin di dunia. Kuahnya dimasak dengan ayam pencen dan kepala udang manis.","ja":"広東省から錫鉱山の街イポーへ渡った華人が定着させました。ミネラルを豊富に含む山々の湧き水で作られる平打ち米麺は、驚くほど薄くシルキーで、喉越し抜群。老鶏の骨と大量の有頭エビを煮込んだ黄金スープに、赤い特製エビ油を浮かべるのが特徴です。","ko":"20세기 초 주석 광산의 도시 이포로 건너온 광둥 출신 화교들이 정착시켰습니다. 석회암 천연 지하수로 만들어 비단처럼 얇고 미끄러운 쌀국수 면발에, 노계와 새우 머리를 푹 고아 붉은 새우기름을 띄운 맑고 깊은 국물이 일품입니다."},"malayScript":"Kuey Teow Sup Ipoh","malayPhonetics":"Kway Tee-ow Soop Ee-poh","audioPronunciationText":"Tauke, Gai See Hor Fun satu, taugeh satu piring, sup manis!","communityHeritage":"Chinese","nativeName":"Kuey Teow Sup Ipoh","nativePhonetics":"Kuey Teow Sup Ipoh"},"ingredients":[{"id":"fresh-ipoh-hor-fun","name":{"zh-TW":"特薄滑嫩新鮮沙河粉 (粿條)","en":"Ultra-Thin Fresh Flat Rice Noodles (Hor Fun)","ms":"Kuey Teow Halus Lembut Segar","ja":"極薄生ライスヌードル（平打ち沙河粉）","ko":"얇고 부드러운 생 쌀국수 (호펀)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"malayName":"Kuey Teow Halus","malayPronunciation":"Kway Tee-ow Hah-loos"},{"id":"prawn-heads-shells","name":{"zh-TW":"新鮮大頭蝦頭與蝦殼 (熬蝦油與高湯)","en":"Fresh Jumbo Prawn Heads & Shells","ms":"Kepala & Kulit Udang Segar","ja":"新鮮な有頭エビの頭と殻","ko":"신선한 새우 머리와 껍질"},"amount":250,"unitMetric":"g","unitUS":"9 oz","isKeyFlavor":true,"malayName":"Kepala Udang","malayPronunciation":"Keh-pah-lah Oo-dahng"},{"id":"chicken-bones-breast","name":{"zh-TW":"老母雞骨架與雞胸肉 (煮熟撕絲)","en":"Chicken Carcass & Chicken Breast (poached, shredded)","ms":"Tulang Ayam & Isi Dada Ayam","ja":"鶏ガラ＆鶏胸肉（茹でて細く割く）","ko":"닭 뼈 육수용 & 닭가슴살 (삶아 찢어둠)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"malayName":"Stok Ayam & Daging","malayPronunciation":"Stohk Ah-yahm"},{"id":"ipoh-bean-sprouts","name":{"zh-TW":"爽脆肥嫩綠豆芽菜 (川燙佐生抽香油)","en":"Crunchy Fat Bean Sprouts (blanched with soy & sesame)","ms":"Taugeh Gemuk Segar Celur","ja":"太もやし（サッと湯通しし、醤油とごま油で和える）","ko":"통통한 숙주나물 (살짝 데쳐 간장 참기름에 무침)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"malayName":"Taugeh Ipoh","malayPronunciation":"Tah-oo-geh Ee-poh"},{"id":"fresh-prawns-garnish","name":{"zh-TW":"新鮮草蝦 (留尾去殼燙熟片開)","en":"Sea Prawns (Poached, halved horizontally)","ms":"Udang Laut Celur Belah Dua","ja":"茹でエビ（背開き）","ko":"데친 새우 (반으로 저민 것)"},"amount":6,"unitMetric":"piece","unitUS":"6 pcs","isKeyFlavor":false,"malayName":"Udang Celur","malayPronunciation":"Oo-dahng Cheh-loor"},{"id":"chives-and-scallions","name":{"zh-TW":"韭菜段與新鮮青蔥絲","en":"Fresh Chinese Chives & Scallion Silk","ms":"Kucai & Daun Bawang Hiris","ja":"ニラ＆細切り青ネギ","ko":"부추 & 대파채"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","isKeyFlavor":false,"malayName":"Kucai & Bawang","malayPronunciation":"Koo-chai dahn Bah-wahng"}],"steps":[{"stepNumber":1,"image":"/images/my/ipoh-hor-fun-step1.jpg","title":{"zh-TW":"慢火提煉金紅純蝦油 (Minyak Udang)","en":"Render Golden Red Prawn-Head Oil","ms":"Tumis Minyak Kepala Udang Merah Wangi","ja":"エビの頭を炒めて香り高い赤いエビ油を抽出する","ko":"새우 머리를 볶아 붉은 새우기름(새우 오일) 뽑아내기"},"instruction":{"zh-TW":"平底鍋中倒入 4 大匙油，加入 250g 洗淨瀝乾的新鮮蝦頭與蝦殼。開中火慢慢煎炒，用鐵鏟反覆用力擠壓蝦頭，把紅澄澄的蝦膏與蝦黃徹底壓榨出來。慢煸 8-10 分鐘，直到油質轉為透明亮麗的天然紅寶石色、油泡細密，過濾出極品蝦油備用。","en":"Heat 4 tbsp oil in skillet with 250g drained prawn heads and shells. Sauté over medium heat, using a wooden spoon to press and crush the heads, extracting the rich orange prawn tomalley and lipids. Fry for 8-10 mins until oil glows crimson-orange and fragrant. Strain and reserve this precious prawn oil.","ms":"Panaskan 4 sb minyak bersama kepala dan kulit udang. Tekan kepala udang dengan senduk untuk mengeluarkan pati lemak merah manis. Goreng 8-10 minit hingga minyak bertukar merah berkilau, tapis minyaknya.","ja":"フライパンに油大さじ4とエビの頭・殻を入れ中火で加熱。ヘラで頭をギュッと押し潰して濃厚なエビ味噌を油に溶け出させます。8〜10分炒め、油が透き通ったルビー色になったら濾してエビ油を取っておきます。","ko":"팬에 오일 4큰술과 새우 머리, 껍질을 넣고 중불에서 볶습니다. 주걱으로 머리를 꾹꾹 눌러 내장과 감칠맛을 오일에 우려냅니다. 8-10분간 볶아 영롱한 붉은빛이 돌면 체에 걸러 새우기름을 따로 둡니다."},"durationSeconds":600},{"stepNumber":2,"image":"/images/my/ipoh-hor-fun-step2.jpg","title":{"zh-TW":"雞骨蝦殼合流・慢熬清甜雙鮮高湯","en":"Simmer Dual-Essence Chicken & Prawn Sweet Broth","ms":"Reneh Tulang Ayam & Sisa Udang Jadi Kuah Manis Asli","ja":"鶏ガラと炒めたエビ殻を合わせて極上ダブルスープを煮出す","ko":"닭 뼈와 볶은 새우를 함께 끓여 맑고 깊은 더블 육수 내기"},"instruction":{"zh-TW":"深湯鍋中倒入 1600ml 清水，放入川燙過的雞骨架、一塊雞胸肉、幾片拍薑，以及剛剛煉完油的香脆蝦頭殼。大火煮沸後撈除表面浮沫，轉小火加蓋慢熬 35 分鐘。取出煮熟的雞胸肉放涼撕成細絲。將其餘骨頭蝦殼全數過濾，留下金黃透亮、清甜無比的雙鮮高湯，加少許冰糖、白胡椒粉與海鹽調味。","en":"In deep pot, bring 1600ml water to boil with blanched chicken carcass, 1 chicken breast, ginger slices and the crushed sautéed prawn shells. Skim scum, reduce to low simmer covered for 35 mins. Lift out cooked chicken breast, cool and shred into fine threads. Strain out all solids, leaving a crystal clear golden-amber stock. Season with rock sugar, white pepper and salt.","ms":"Didihkan 1600ml air bersama tulang ayam, dada ayam, halia dan kepala udang yang telah digoreng tadi. Reneh api kecil 35 minit. Angkat dada ayam dan carik halus. Tapis kuah hingga jernih keemasan dan perasakan dengan garam, gula batu dan lada putih.","ja":"鍋に水1600ml、下茹でした鶏ガラ、鶏胸肉、生姜、先ほどのエビ殻を入れます。アクを取り、蓋をして弱火で35分煮込みます。胸肉を取り出して細かく裂き、スープを漉して黄金色の澄んだスープを抽出。氷砂糖、白胡椒、塩で調味します。","ko":"냄비에 물 1600ml, 닭 뼈, 닭가슴살, 생강, 볶아둔 새우 머리를 넣고 끓입니다. 거품을 걷어내고 약불에서 35분간 우립니다. 닭가슴살은 건져 결대로 찢어두고, 육수를 체에 걸러 맑고 깨끗한 상태로 만든 뒤 빙탕, 백후추, 소금으로 간합니다."},"durationSeconds":2100},{"stepNumber":3,"image":"/images/my/ipoh-hor-fun-step3.jpg","title":{"zh-TW":"燙沙河粉盛碗・排入雙鮮配料","en":"Flash-Blanch Rice Noodles & Arrange Delicate Toppings","ms":"Celur Kuey Teow Pantas & Susun Hiasan Ayam & Udang","ja":"沙河粉をサッと湯通しし、蒸し鶏とエビを美しく並べる","ko":"쌀국수 면을 살짝 데쳐 담고 닭고기와 새우 얹기"},"instruction":{"zh-TW":"滾水中放入新鮮沙河粉（粿條）極速汆燙 15-20 秒（切忌煮久否則軟爛！），撈出抖乾水分放入大湯碗。在粉面整齊排入細嫩雞絲、對半片開的鮮蝦仁，以及綠瑩瑩的青韭菜段。","en":"Drop fresh flat rice noodles into boiling water for just 15-20 secs (never over-boil; they must retain slippery elasticity!). Shake dry and drop into serving bowl. Arrange delicate shredded chicken, poached prawn halves, and vibrant green chives neatly across the surface.","ms":"Celur kuey teow dalam air mendidih selama 15-20 saat sahaja (jangan lama agar tidak lembik). Toskan ke mangkuk, susun isi ayam carik, udang celur dan kucai kemas.","ja":"沸騰した湯で生ライスヌードルをわずか15〜20秒湯通しします（茹ですぎ厳禁！）。湯切りして丼へ。上に割いた蒸し鶏、開いたエビ、ニラを美しく並べます。","ko":"끓는 물에 신선한 쌀국수 면을 15-20초간만 빠르게 데쳐냅니다 (오래 삶으면 퍼집니다!). 물기를 털어 그릇에 담고 찢어둔 닭가슴살, 데친 새우, 부추를 가지런히 올립니다."},"durationSeconds":60},{"stepNumber":4,"image":"/images/my/ipoh-hor-fun-step4.jpg","title":{"zh-TW":"淋滾燙雙鮮高湯・點入靈魂金紅蝦油","en":"Ladle Boiling Broth & Crown with Ruby Red Prawn Oil","ms":"Senduk Kuah Panas & Titik Minyak Udang Merah Keemasan","ja":"熱々スープを注ぎ、特製エビ油をひと回し落として完成","ko":"뜨거운 육수를 붓고 붉은 새우기름을 둘러 완성"},"instruction":{"zh-TW":"將滾燙的雙鮮雞蝦清湯舀滿整個粉碗。最後在清澈如鏡的湯面上，淋上 1 大匙金紅蝦油（Minyak Udang）。一圈圈艷紅澄澈的蝦油在熱氣中綻放，散發出無與倫比的海鮮甘醇！配上一小盤燙怡保芽菜，吸溜入口滑順到底！","en":"Ladle boiling chicken-prawn broth lavishly into the bowl. Crown with a generous swirl of the ruby red prawn-head oil. As the amber droplets float across the surface, an intoxicating aroma fills the air! Serve with a side plate of crunchy, plump blanched bean sprouts.","ms":"Sendukkan kuah sup ayam udang panas ke dalam mangkuk. Titikkan sesudu minyak udang merah keemasan di atas kuah. Hidang panas bersama sepinggan taugeh Ipoh rangup berlemak kicap.","ja":"沸騰した熱々のスープをたっぷり注ぎます。仕上げに作っておいた赤いエビ油をたらりと回しかけます。黄金のスープに浮かぶ赤いオイルから極上のエビの香りが立ち上ります！シャキシャキのイポーもやしを添えてどうぞ。","ko":"펄펄 끓는 육수를 국수 위에 듬뿍 붓습니다. 마지막으로 붉은 새우기름 1큰술을 둘러줍니다. 황금빛 맑은 국물 위에 붉은 새우 오일이 퍼지며 매혹적인 향을 뿜어냅니다! 아삭한 이포식 숙주나물 무침과 함께 즐기세요."},"durationSeconds":45}],"troubleshooting":[{"id":"soup-cloudy","problem":{"zh-TW":"高湯過於混濁不夠清澈透亮","en":"Broth turns milky and cloudy","ms":"Kuah sup keruh tidak jernih keemasan","ja":"スープが白濁して澄んだ黄金色にならない","ko":"국물이 맑지 않고 탁하게 흐려짐"},"cause":{"zh-TW":"大火劇烈沸騰導致油脂蛋白質乳化，或未徹底過濾骨渣","en":"Violent rapid boil emulsified fats or inadequate fine-mesh straining","ms":"Api terlalu kuat atau tidak ditapis rapi","ja":"強火で煮立てすぎたため脂が乳化してしまった","ko":"센 불로 끓여 지방이 유화되었거나 미세한 찌꺼기를 거르지 않음"},"solution":{"zh-TW":"熬高湯水滾後務必轉最小火慢燉；過濾時墊上一層細緻濾布，即可得到如茶湯般清透的高湯。","en":"Keep at gentle simmer; strain through fine cheesecloth or coffee filter for crystal clarity.","ms":"Kekalkan api kecil mereneh dan tapis menggunakan kain kasa halus.","ja":"沸騰後は必ず極弱火を保ち、細かいネル布やペーパーで漉すと透き通った黄金スープになります。","ko":"끓어오른 뒤에는 반드시 약불을 유지하고, 고운 면포에 한 번 걸러내면 맑은 국물이 됩니다."}}],"proTips":[{"zh-TW":"靈魂點睛——紅蝦油（Minyak Udang）：這碗麵之所以聞名全馬，關鍵全在那一勺浮在湯面上的自煉蝦油！熱湯激發蝦頭甲殼素的香氣，每一口吸麵都能感受到蝦油包裹著滑粉的極致奢華。","en":"The Golden Crown: The red prawn-head oil makes or breaks this dish! The searing hot soup atomizes the prawn lipids, coating every slippery strand with an opulent, savory glaze.","ms":"Mahkota Rasa: Minyak kepala udang adalah kunci utama! Kuah panas mengaktifkan aroma minyak udang yang menyalut setiap urat kuey teow dengan penuh kemewahan.","ja":"大師の秘訣：この料理の真髄は最後に浮かべる「エビ油」にあります！熱いスープによってエビの甲殻類の香ばしさが一気に花開き、ツルツルの麺を極上の風味でコーティングします。","ko":"마스터의 비법: 붉은 새우기름이 이 요리의 영혼입니다! 뜨거운 국물 위에서 퍼지는 새우 내장의 감칠맛 오일이 부드러운 쌀국수를 감싸며 극상의 풍미를 선사합니다."}]},{"country":"my","id":"mee-goreng-mamak","slug":"mee-goreng-mamak","title":{"zh-TW":"印度嘛嘛檔經典香辣炒麵","en":"Mamak Sizzling Indian Fried Noodles","ms":"Mee Goreng Mamak Pedas Berapi Kuali Panas","ja":"ママック名物・インド風スパイシー炒め麺（ミーゴレン・ママック）","ko":"마막 인도식 불맛 매콤 볶음면 (미고랭 마막)"},"subtitle":{"zh-TW":"鐵板鏗鏘鑊氣・炸豆腐土豆塊脆餅・酸甜番茄參巴辣醬與金桔汁","en":"Sizzling Wok Clatter, Crispy Cucur Fritters, Fried Tofu, Potato & Calamansi Sambal","ms":"Aroma Kuali Besi, Cucur Udang Rangup, Kentang Rebus, Tauhu & Sambal Manis","ja":"鉄板とヘラの激しい音、揚げ豆腐と角切りポテト、甘辛チリトマトとライム","ko":"철판 불맛, 바삭한 튀김 쿠추르, 튀긴 두부, 감자, 매콤달콤 토마토 칠리와 칼라만시"},"tagline":{"zh-TW":"大馬 24 小時露天嘛嘛檔的靈魂節奏！宵夜桌上永遠的無冕之王","en":"The pulsing heartbeat of 24-hour Malaysian Mamak culture—the undisputed king of late-night cravings","ms":"Nadi budaya restoran Mamak 24 jam di Malaysia, raja makanan lewat malam yang tiada tandingan","ja":"24時間営業ママック屋台の象徴！深夜の空腹を満たす熱気とスパイシーの王様","ko":"24시간 불야성을 이루는 말레이시아 마막 문화의 심장! 심야 야식의 독보적인 제왕"},"heroImage":"/images/my/mee-goreng-mamak.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":570,"category":"noodles","dietaryTags":["classic","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"全馬全境・印度穆斯林嘛嘛檔 (Mamak Hawker Culture)","en":"Nationwide / Indian-Muslim Mamak Heritage","ms":"Seluruh Malaysia / Gerai Mamak","ja":"マレーシア全土・ママック露店文化","ko":"말레이시아 전역 / 마막 노점 문화"},"famousStreetMarkets":[{"zh-TW":"檳城海墘新路辣死你媽炒麵","en":"Mee Manja / Transfer Road Mamak, Penang","ms":"Mee Goreng Transfer Road","ja":"ペナン・トランスファー通りママック","ko":"페낭 트랜스퍼 거리 마막"},{"zh-TW":"吉隆坡安邦路 Devi’s Corner","en":"Devi’s Corner Bangsar, Kuala Lumpur","ms":"Devi’s Corner Bangsar","ja":"デヴィズ・コーナー（バンサー）","ko":"데비스 코너 (방사르)"}],"historyStory":{"zh-TW":"印度泰米爾穆斯林（Mamak）將中華黃油麵與南印度香料烹飪技藝碰撞融合。嘛嘛檔廚師在巨大的半圓形生鐵熱板前，雙鏟飛舞、敲擊鐵板發出節奏感強烈的「鏗鏗鏘鏘」聲。將煮土豆丁、炸豆腐塊、麵粉蝦餅脆塊（Cucur）與黃麵一同翻炒，淋入獨家紅番茄參巴甜辣醬與甜醬油，起鍋前擠入一顆新鮮青金桔汁，鑊氣逼人！","en":"A genius cross-cultural fusion by Tamil Muslims adapting Chinese yellow noodles to South Indian spice profiles. Chefs orchestrate a rhythmic drumbeat of steel spatulas clattering against scorching flat-top griddles. They toss noodles with boiled potato cubes, fried bean curd, crispy flour fritters (cucur), an intensely savory-sweet tomato sambal gravy, and a spritz of fresh calamansi lime juice.","ms":"Gabungan seni masakan Cina dan rempah India oleh masyarakat India Muslim. Peniaga beraksi dengan sudip besi di atas kuali leper panas, mencampurkan mee kuning bersama ubi kentang, cucur tepung, tauhu dan sambal cili sos tomato yang berkaramel.","ja":"インド系ムスリム（ママック）が中華の黄色い太麺を南インド風にアレンジ。巨大な丸鉄板でヘラをリズミカルにカンカン鳴らしながら、茹でジャガイモ、揚げ豆腐、エビかき揚げ（クチュール）と共に炒め上げます。特製トマトチリソースの甘辛さとライムの酸味が食欲を直撃。","ko":"타밀 무슬림들이 중화풍 노란 국수와 남인도 향신료를 결합해 완성한 요리입니다. 거대한 평철판에서 주걱을 리드미컬하게 부딪치며 감자, 튀긴 두부, 바삭한 튀김을 토마토 칠리소스와 함께 강불에서 볶아냅니다."},"malayScript":"Mee Goreng Mamak","malayPhonetics":"Mee Goh-rehng Mah-mahk","audioPronunciationText":"An-neh, Mee Goreng satu, telur mata goyang satu, pedas kaw!","communityHeritage":"Indian-Mamak","nativeName":"Mee Goreng Mamak","nativePhonetics":"Mee Goreng Mamak"},"ingredients":[{"id":"yellow-noodles-mamak","name":{"zh-TW":"新鮮油黃麵條 (黃鹼麵)","en":"Fresh Yellow Alkaline Noodles","ms":"Mee Kuning Basah Segar","ja":"黄色い中華太麺（生麺）","ko":"신선한 노란 알칼리 생면"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":false,"malayName":"Mee Kuning","malayPronunciation":"Mee Koon-yeeng"},{"id":"boiled-potato","name":{"zh-TW":"煮熟馬鈴薯 (土豆 / 切 1.5cm 小塊)","en":"Boiled Potato (Diced into 1.5cm chunks)","ms":"Ubi Kentang Rebus Dadu","ja":"茹でジャガイモ（1.5cm角切り）","ko":"삶은 감자 (1.5cm 깍둑썰기)"},"amount":1,"unitMetric":"piece","unitUS":"1 medium","isKeyFlavor":true,"malayName":"Ubi Kentang","malayPronunciation":"Oo-bee Kehn-tahng"},{"id":"fried-tofu-mamak","name":{"zh-TW":"油炸老豆腐 (豆乾 / 切丁)","en":"Firm Fried Tofu (Tauhu Goreng, diced)","ms":"Tauhu Goreng Potong Dadu","ja":"厚揚げ・揚げ豆腐（角切り）","ko":"튀긴 단단한 두부 (깍둑썰기)"},"amount":1,"unitMetric":"piece","unitUS":"1 block","isKeyFlavor":true,"malayName":"Tauhu Goreng","malayPronunciation":"Tah-oo-hoo Goh-rehng"},{"id":"cucur-fritters","name":{"zh-TW":"大馬炸麵粉脆餅塊 (Cucur / 可用炸魚餅或蝦餅代替)","en":"Crispy Flour Fritters (Cucur Udang chunks or fish cake)","ms":"Cucur Tepung Rangup / Kek Ikan","ja":"マレー風天ぷら・揚げ餅（クチュールまたは魚肉練り天）","ko":"말레이식 밀가루 튀김 조각 (쿠추르 또는 어묵)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":true,"malayName":"Cucur Tepung","malayPronunciation":"Choo-choor Teh-poong"},{"id":"mamak-chili-paste","name":{"zh-TW":"嘛嘛檔特製紅辣醬 (乾辣椒醬、番茄醬、甜辣醬、咖哩粉調和)","en":"Mamak Sweet-Spicy Chili Paste: Chili bo, tomato ketchup, sweet chili, curry powder","ms":"Pes Sambal Mamak (Cili Boh, Sos Tomato, Serbuk Kari)","ja":"ママック特製チリソース（チリペースト、トマトケチャップ、カレー粉）","ko":"마막 특제 칠리 페이스트 (고추 페이스트, 케첩, 카레가루)"},"amount":60,"unitMetric":"g","unitUS":"4 tbsp","isKeyFlavor":true,"malayName":"Pes Sambal Mamak","malayPronunciation":"Pehs Sahm-bahl Mah-mahk"},{"id":"kicap-manis-mamak","name":{"zh-TW":"大馬老字號甜醬油 (Kicap Manis)","en":"Sweet Soy Sauce (Kicap Manis)","ms":"Kicap Manis Pekat","ja":"甘口黒醤油（キチャップマニス）","ko":"달콤한 흑간장 (키찹 마니스)"},"amount":25,"unitMetric":"ml","unitUS":"1.5 tbsp","isKeyFlavor":true,"malayName":"Kicap Manis","malayPronunciation":"Kee-chahp Mah-nees"},{"id":"eggs-mamak","name":{"zh-TW":"新鮮雞蛋","en":"Fresh Chicken Eggs","ms":"Telur Ayam Segar","ja":"生卵","ko":"신선한 달걀"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":false,"malayName":"Telur Ayam","malayPronunciation":"Teh-loor Ah-yahm"},{"id":"bean-sprouts-cabbage","name":{"zh-TW":"綠豆芽與爽脆高麗菜絲","en":"Fresh Bean Sprouts & Shredded Cabbage","ms":"Taugeh & Kobis Hiris","ja":"もやし＆千切りキャベツ","ko":"숙주나물 & 양배추 채"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":false,"malayName":"Taugeh & Kobis","malayPronunciation":"Tah-oo-geh dahn Koh-bees"},{"id":"calamansi-lime-mamak","name":{"zh-TW":"青金桔 (酸柑 / 擠汁)","en":"Fresh Calamansi Limes (Limau Kasturi)","ms":"Limau Kasturi Segar","ja":"カラマンシーライム","ko":"칼라만시 라임"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":true,"malayName":"Limau Kasturi","malayPronunciation":"Lee-mah-oo Kahs-too-ree"}],"steps":[{"stepNumber":1,"image":"/images/my/mee-goreng-mamak-step1.jpg","title":{"zh-TW":"大鐵鑊熱油・煸香大蒜與配料丁","en":"Sear Garlic, Tofu & Boiled Potato Chunks in Hot Wok","ms":"Tumis Bawang Putih, Tauhu & Ubi Kentang Dalam Kuali Panas","ja":"熱々の鉄鍋でニンニク、揚げ豆腐、ジャガイモを香ばしく炒める","ko":"달궈진 웍에 마늘, 튀긴 두부, 감자를 넣고 볶기"},"instruction":{"zh-TW":"大鐵鑊（或寬平底深鍋）燒至大熱，倒入 2 大匙油。下拍蒜蓉爆出金黃蒜香，接著放入熟土豆丁、炸豆腐丁與切段脆餅（Cucur）。大火快炒 1 分鐘，使土豆表面煎出微脆金邊。","en":"Heat iron wok or wide skillet until very hot, add 2 tbsp oil. Sauté minced garlic until golden, then toss in boiled potato chunks, fried tofu cubes and crispy fritter pieces. Stir-fry over high heat for 1 min until edges lightly blister.","ms":"Panaskan kuali leper bersama 2 sb minyak. Tumis bawang putih hingga wangi, masukkan ubi kentang rebus, tauhu goreng dan cucur tepung. Goreng 1 minit atas api besar.","ja":"鉄鍋を強火で熱し、油大さじ2を入れます。刻みニンニクを炒め、ジャガイモ角切り、揚げ豆腐、クチュール（かき揚げ）を加えて1分強火で炒めます。","ko":"달궈진 웍에 기름 2큰술을 두르고 다진 마늘을 볶다가 삶은 감자, 튀긴 두부, 튀김 조각을 넣고 1분간 센 불에서 노릇하게 볶습니다."},"durationSeconds":60},{"stepNumber":2,"image":"/images/my/mee-goreng-mamak-step2.jpg","title":{"zh-TW":"黃麵下鍋・拌炒特製參巴番茄紅醬","en":"Add Yellow Noodles & Toss in Sweet-Savory Mamak Sambal","ms":"Masukkan Mee Kuning & Pes Sambal Kicap Mamak","ja":"黄色い太麺を投入し特製ママックチリソースと絡める","ko":"노란 면을 넣고 마막 칠리소스와 함께 볶기"},"instruction":{"zh-TW":"放入 300g 黃麵條、高麗菜絲與豆芽。倒入 4 大匙嘛嘛檔特製紅辣醬（含番茄醬與咖哩香氣）、1.5 大匙大馬甜醬油（Kicap Manis）與 1 茶匙生抽。大火快速拋翻翻炒 1 分鐘，讓每根麵條均勻染上橘紅油亮的醬汁。","en":"Toss in 300g yellow noodles, shredded cabbage and bean sprouts. Pour in 4 tbsp Mamak chili sauce (tomato-curry blend), 1.5 tbsp Kicap Manis sweet soy, and 1 tsp light soy. Flash-fry on maximum flame for 1 min until every noodle glimmers with scarlet, sticky gravy.","ms":"Masukkan mee kuning, kobis dan taugeh. Tuang pes sambal tomato mamak, kicap manis dan kicap cair. Gaul pantas atas api besar 1 minit hingga mee bersalut sos merah berkilat.","ja":"中華太麺300g、キャベツ、もやしを投入。特製チリトマトソース大さじ4、甘口黒醤油大さじ1.5を回し入れ、強火で一気に1分間煽って麺全体にソースを行き渡らせます。","ko":"노란 면 300g, 양배추, 숙주를 넣습니다. 마막 칠리소스 4큰술, 키찹 마니스 단간장 1.5큰술, 진간장을 넣고 센 불에서 1분간 빠르게 볶아 면을 소스로 코팅합니다."},"durationSeconds":75},{"stepNumber":3,"image":"/images/my/mee-goreng-mamak-step3.jpg","title":{"zh-TW":"推開炒雞蛋・碎炒金黃包覆麵條","en":"Push Aside, Scramble Egg & Fold Silky Curds into Noodles","ms":"Tolak Mee ke Tepi, Pecahkan Telur & Kacau Sebati","ja":"麺を寄せて卵を割り入れ、半熟スクランブルを全体に絡める","ko":"면을 밀어두고 달걀을 깨 넣어 스크램블한 뒤 함께 섞기"},"instruction":{"zh-TW":"將麵條推至鐵鍋邊緣，中央淋 1 茶匙油打入 1 顆雞蛋。用鏟尖快速劃圈炒散至半凝固嫩蛋花狀，隨即將上方的熱麵條翻蓋下來全力翻炒 20 秒，讓碎蛋花均勻附著在麵條之間，增加濃郁蛋香。","en":"Push noodles to wok edges, add 1 tsp oil to center, crack in 1 egg. Vigorously scramble with spatula until softly curdled, then fold steaming noodles over egg. Stir-fry for 20 secs so creamy golden egg ribbons weave through the noodles.","ms":"Tolak mee ke tepi kuali, pecahkan telur di tengah. Kacau telur hingga separuh masak kemudian lipat mee atas telur. Gaul laju 20 saat agar telur menyalut mee.","ja":"麺を端に寄せ、中央に油少々と卵を割り入れます。手早くかき混ぜて半熟状にし、麺を上から被せて20秒一気に炒め合わせます。","ko":"면을 웍 한쪽으로 밀고 중앙에 달걀을 깨 넣습니다. 빠르게 저어 반숙 스크램블 상태를 만든 뒤 면을 덮어 20초간 골고루 섞어줍니다."},"durationSeconds":45},{"stepNumber":4,"image":"/images/my/mee-goreng-mamak-step4.jpg","title":{"zh-TW":"擠入新鮮金桔汁・盛盤大快朵頤","en":"Spritz Fresh Calamansi Lime Juice & Plate Immediately","ms":"Perah Jus Limau Kasturi & Hidang Panas Berapi","ja":"カラマンシーライムを絞り、出来立て熱々をいただく","ko":"칼라만시 라임 즙을 짜 넣고 즉시 접시에 담아 서빙"},"instruction":{"zh-TW":"關火起鍋前，將 1 顆切半青金桔在鍋中大力擠入酸汁，翻拌兩下激發果香！滑入餐盤，頂部附上另半顆金桔與少許油蔥酥，可加煎一顆邊緣酥焦的半熟太陽蛋（Telur Mata Goyang）。趁熱入口，酸、甜、辣、香四重爆發！","en":"Right before removing from heat, squeeze juice of 1 halved calamansi lime directly into wok and give two swift tosses! Slide onto plate, garnished with fried shallots and an extra lime wedge (optionally topped with a crispy fried sunny-side egg). Savor the thrilling explosion of tangy, sweet, spicy and savory flavors!","ms":"Tutup api, perahkan jus sebiji limau kasturi ke dalam kuali dan gaul pantas. Tuang atas pinggan bersama telur mata goyang dan bawang goreng.","ja":"火を止める直前にライム果汁をギュッと絞り入れ、ひと煽り！お皿に滑らせ、フライドエシャロットと目玉焼きを乗せて熱々をいただきます！","ko":"불을 끄기 직전 칼라만시 라임 즙을 짜 넣고 빠르게 두어 번 뒤섞어줍니다! 접시에 담고 바삭한 반숙 계란후라이를 얹어 서빙합니다."},"durationSeconds":30}],"troubleshooting":[{"id":"too-soggy","problem":{"zh-TW":"炒麵濕軟黏糊，缺乏嘛嘛檔焦香乾爽感","en":"Fried noodles turn soggy and mushy","ms":"Mee goreng berair dan lembik","ja":"麺がベチャベチャになり、屋台のような香ばしさがない","ko":"볶음면이 축축하고 마막 특유의 불맛이 나지 않음"},"cause":{"zh-TW":"醬料水分太多、鍋溫不足、或油麵汆燙過久吸收過多水分","en":"Excess sauce liquid, low pan temp, or boiled noodles too long beforehand","ms":"Sos terlalu berair atau kuali tidak cukup panas","ja":"水分が多すぎる、または鍋の火力が弱い","ko":"소스에 수분이 너무 많거나 웍의 화력이 약함"},"solution":{"zh-TW":"黃鹼麵直接下鍋乾炒（無須預先水煮！）；醬料保持濃稠泥狀，始終維持大火收汁。","en":"Toss fresh yellow noodles directly into searing wok without pre-boiling! Keep sauces thick.","ms":"Masukkan mee terus ke dalam kuali tanpa direbus dalam air; gunakan api kuat.","ja":"市販の生黄色麺は茹でずにそのまま強火の油で炒めてください。ソースの水分を極力減らすのがコツ。","ko":"노란 생면은 물에 데치지 말고 바로 웍에 넣어 센 불에서 빠르게 볶으세요!"}}],"proTips":[{"zh-TW":"嘛嘛檔至尊點法「Mee Goreng + Telur Mata Goyang」：點餐時交代老闆要加一顆「搖晃荷包蛋（Telur Mata Goyang）」，將流心生熟蛋黃戳破拌入熱騰騰的辣麵條中，蛋液包裹著微焦的土豆和豆腐，滑潤濃郁升天！","en":"Mamak Supreme Combo: Always ask for \"Telur Mata Goyang\" (Wobbly Sunny-Side Egg)! Poke the molten runny yolk so it blankets the fiery noodles and crispy potato cubes with golden, velvet silk.","ms":"Pesanan Paling Padu: Tambah \"Telur Mata Goyang\"! Pecahkan kuning telur cair ke atas mee goreng panas untuk rasa lemak berkrim yang memikat selera.","ja":"ママック最強の注文「テロール・マタ・ゴヤン（とろとろ目玉焼き付き）」：トロリとした半熟の黄身を崩して熱いスパイシー麺に絡めると、驚くほどまろやかでリッチな味わいになります！","ko":"마막 최고의 조합 \"미고랭 + 텔루르 마타 고양(반숙 계란)\": 노른자가 흐르는 반숙 프라이를 올려 노른자를 터뜨린 뒤 매콤한 면과 비벼 드세요! 고소함이 배가됩니다."}]},{"country":"my","id":"roti-jala","slug":"roti-jala","title":{"zh-TW":"網狀蕾絲馬來煎餅佐咖哩雞","en":"Golden Lace Net Crepes (Roti Jala) with Chicken Curry","ms":"Roti Jala Lembut Berenda & Kari Ayam Kentang Pekat","ja":"ロティ・ジャラ（黄金レースネットクレープ＆チキンカレー）","ko":"로티 잘라 (그물망 레이스 팬케이크 & 치킨 커리)"},"subtitle":{"zh-TW":"薑黃金黃蕾絲細網・入口鬆軟化開・濃醇椰漿馬來咖哩雞肉塊吸汁絕配","en":"Turmeric Golden Net Crepes, Tender Airy Folds & Rich Coconut Chicken Curry","ms":"Roti Jala Kunyit Emas Lembut & Gulai Kari Ayam Berempah Pekat","ja":"ターメリックが香る黄金の繊細なレース生地、ココナッツチキンカレーをたっぷり吸い込む逸品","ko":"강황을 넣어 고운 레이스 모양으로 구워낸 크레이프와 진한 코코넛 치킨 커리"},"tagline":{"zh-TW":"馬來傳統節慶與婚宴尊榮名點！宛如金色漁網的宮廷視覺奇蹟","en":"The royal lace crepe of Malay celebrations and weddings, resembling golden fishing nets","ms":"Hidangan tradisi majlis keraian Melayu yang anggun berenda indah bak jala emas","ja":"マレー伝統の祝宴に欠かせない宮廷料理。黄金の漁網を模した美しいレース状クレープ","ko":"말레이 전통 축제와 결혼식의 대표적인 궁중 요리. 황금빛 그물망 모양의 우아한 크레이프"},"heroImage":"/images/my/roti-jala.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":35,"defaultServings":4,"caloriesPerServing":480,"category":"mains","dietaryTags":["classic","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"西馬各州・馬來傳統鄉村與婚宴 (Malay Heritage)","en":"Nationwide / Traditional Malay Banquets","ms":"Seluruh Malaysia / Majlis Kenduri Tradisi","ja":"マレーシア全土・伝統祝宴料理","ko":"말레이시아 전역 / 전통 연회 요리"},"famousStreetMarkets":[{"zh-TW":"吉蘭丹哥打峇魯夜市","en":"Pasar Malam Kota Bharu, Kelantan","ms":"Pasar Malam Kota Bharu","ja":"コタバル夜市","ko":"코타바루 야시장"},{"zh-TW":"吉隆坡秋傑巴剎 (Chow Kit)","en":"Pasar Chow Kit, Kuala Lumpur","ms":"Pasar Chow Kit KL","ja":"チョーキット市場","ko":"초우킷 시장"}],"historyStory":{"zh-TW":"「Jala」在馬來語中即為「漁網」之意。早期沿海漁民的妻子，以漁民撒網捕魚的優美姿態為靈感，將特製的多孔漏斗杯裝入薑黃麵糊，在鐵盤上快速劃出交織如蕾絲般的金黃網紋。折疊成小巧圓卷後，氣孔能如海綿般吸飽濃郁的椰漿咖哩雞汁，是馬來皇室慶典與開齋節不可或缺的貴賓點心。","en":"In Malay, \"Jala\" literally means \"fishing net\". Inspired by coastal fishermen casting nets across the sea, homemakers used a specialized five-nozzle funnel to drizzle turmeric-scented batter in concentric loops across a griddle, creating delicate golden lace sheets. Rolled like spring rolls, the thousands of tiny mesh pores soak up thick chicken curry like magic.","ms":"Dinamakan \"Roti Jala\" kerana bentuknya yang menyerupai jala nelayan menangkap ikan. Menggunakan acuan berlubang khas untuk menebar adunan berenda atas kuali leper. Digulung kemas dan dicicah kari ayam berempah.","ja":"マレー語で「ジャラ（Jala）」は「漁網」を意味します。海に網を投げる漁師の姿から着想を得て、5つの穴が開いた専用カップから生地を細く流し込んでレース模様に焼き上げます。くるくると巻いたクレープの隙間にチキンカレーの濃厚なルーがたっぷり染み込みます。","ko":"말레이어로 \"잘라(Jala)\"는 \"어망(그물)\"을 뜻합니다. 바다에 그물을 던지는 어부의 모습에서 영감을 얻어 구멍 뚫린 틀로 반죽을 돌려가며 얇은 그물망 형태로 구워냅니다. 돌돌 만 크레이프가 치킨 커리를 듬뿍 머금어 환상적인 조화를 이룹니다."},"malayScript":"Roti Jala Kari Ayam","malayPhonetics":"Roh-tee Jah-lah Kah-ree Ah-yahm","audioPronunciationText":"Makcik, Roti Jala satu set, kuah kari ayam lebih ya!","communityHeritage":"Malay","nativeName":"Roti Jala Kari Ayam","nativePhonetics":"Roti Jala Kari Ayam"},"ingredients":[{"id":"roti-jala-flour","name":{"zh-TW":"中筋麵粉 (篩過)","en":"All-Purpose Flour (Sifted)","ms":"Tepung Gandum Diayak","ja":"中力粉（ふるったもの）","ko":"중력분 (체에 친 것)"},"amount":250,"unitMetric":"g","unitUS":"9 oz","isKeyFlavor":false,"malayName":"Tepung Gandum","malayPronunciation":"Teh-poong Gahn-doom"},{"id":"turmeric-powder-jala","name":{"zh-TW":"純薑黃粉 (染出天然金黃微香)","en":"Pure Ground Turmeric Powder (for golden color)","ms":"Serbuk Kunyit Asli","ja":"純ターメリックパウダー（美しい黄金色に）","ko":"순수 강황가루 (천연 황금빛 색감)"},"amount":4,"unitMetric":"g","unitUS":"1 tsp","isKeyFlavor":true,"malayName":"Serbuk Kunyit","malayPronunciation":"Sehr-book Koon-yeet"},{"id":"coconut-milk-crepe","name":{"zh-TW":"椰漿與全脂牛奶 (調和麵糊)","en":"Coconut Milk & Fresh Milk (1:1 blend)","ms":"Santan Kelapa Cair & Susu Segar","ja":"ココナッツミルク＆牛乳","ko":"코코넛 밀크 & 우유"},"amount":300,"unitMetric":"ml","unitUS":"10 fl oz","isKeyFlavor":true,"malayName":"Santan & Susu","malayPronunciation":"Sahn-tahn dahn Soo-soo"},{"id":"chicken-pieces-curry","name":{"zh-TW":"鮮雞腿肉塊 (帶骨剁塊)","en":"Bone-in Chicken Thigh Pieces (chopped)","ms":"Ketulan Ayam Bertulang","ja":"骨付き鶏もも肉ぶつ切り","ko":"뼈 있는 닭다리살 토막"},"amount":500,"unitMetric":"g","unitUS":"18 oz","isKeyFlavor":false,"malayName":"Daging Ayam","malayPronunciation":"Dah-geeng Ah-yahm"},{"id":"potatoes-curry","name":{"zh-TW":"馬鈴薯 (切滾刀大塊)","en":"Potatoes (Peeled, cut into chunks)","ms":"Ubi Kentang Potong Baji","ja":"ジャガイモ（乱切り）","ko":"감자 (큼직하게 썬 것)"},"amount":2,"unitMetric":"piece","unitUS":"2 medium","isKeyFlavor":false,"malayName":"Ubi Kentang","malayPronunciation":"Oo-bee Kehn-tahng"},{"id":"malay-curry-powder","name":{"zh-TW":"大馬峇峇肉類咖哩粉 (BABA’S Curry Powder) 與椰漿","en":"BABA’S Meat Curry Powder & Coconut Cream","ms":"Serbuk Kari Daging BABA’S & Pati Santan","ja":"BABA’S マレーカレーパウダー＆ココナッツクリーム","ko":"BABA’S 미트 커리 파우더 & 코코넛 크림"},"amount":180,"unitMetric":"g","unitUS":"6 oz","isKeyFlavor":true,"malayName":"Rempah Kari BABA’S","malayPronunciation":"Rehm-pah Kah-ree Bah-bahs"}],"steps":[{"stepNumber":1,"image":"/images/my/roti-jala-step1.jpg","title":{"zh-TW":"調配金黃絲滑蕾絲麵糊","en":"Whisk Silky Golden Turmeric Crepe Batter","ms":"Bancuh Adunan Roti Jala Kuning Bersinar","ja":"黄金色のなめらかなクレープ生地を混ぜ合わせる","ko":"황금빛의 부드러운 레이스 반죽 만들기"},"instruction":{"zh-TW":"大碗中篩入 250g 麵粉、1 茶匙薑黃粉、1/2 茶匙海鹽。打入 1 顆全蛋，倒入 150ml 椰漿、150ml 牛奶與 1 大匙融化黃油。用打蛋器順向攪勻成流質麵糊，過濾網兩次濾除顆粒，靜置 20 分鐘使質地完全均勻順滑無氣泡。","en":"Sift 250g flour, 1 tsp turmeric powder and salt into bowl. Whisk in 1 egg, 150ml coconut milk, 150ml milk and 1 tbsp melted butter into a thin runny batter. Strain through fine mesh twice to eliminate any lumps; rest 20 mins.","ms":"Ayak tepung, serbuk kunyit dan garam. Masukkan telur, santan, susu dan mentega cair. Kacau sebati hingga licin cair. Tapis dua kali dan rehatkan 20 minit.","ja":"ボウルに粉、ターメリック、塩をふるい入れます。卵、ココナッツミルク、牛乳、溶かしバターを加え、泡立て器でダマのないサラサラの生地に混ぜます。茶漉しで2回漉して20分休ませます。","ko":"볼에 밀가루, 강황가루, 소금을 체 쳐 넣습니다. 달걀, 코코넛 밀크, 우유, 녹인 버터를 넣고 거품기로 멍울 없이 섞습니다. 고운 체에 2번 걸러 20분간 휴지합니다."},"durationSeconds":360},{"stepNumber":2,"image":"/images/my/roti-jala-step2.jpg","title":{"zh-TW":"旋轉漏斗・平底鍋烙製透光金網 (Roti Jala)","en":"Swirl Lace Patterns on Pan & Roll Tender Crepes","ms":"Tebar Acuan Jala Atas Kuali & Gulung Kemas","ja":"フライパンの上で専用カップを回し、レース模様を焼いて巻く","ko":"팬 위에 그물망을 그리듯 구워 돌돌 말기"},"instruction":{"zh-TW":"平底不沾鍋抹薄薄一層油，開中小火。將麵糊舀入五孔沙拉擠醬瓶（或傳統漏網杯）。在離鍋面約 10 公分處迅速繞圈晃動，縱橫交錯擠出如精緻金色蕾絲般的網格！烘烤約 40-50 秒（表面凝固微起泡即可，無須翻面！）。滑出在砧板上，兩邊向內折起、往前捲成如雪茄般的鬆軟金網卷。","en":"Lightly oil non-stick crepe pan over medium-low heat. Fill a 5-nozzle bottle (or traditional Roti Jala cup) with batter. Hover 10cm above pan and rapidly swirl in overlapping circles to create delicate lace lattice. Cook 40-50 secs until set (do NOT flip!). Slide onto board, fold sides inward, and roll into a tender golden lace cylinder.","ms":"Sapu sedikit minyak atas kuali leper api sederhana kecil. Isikan adunan ke dalam acuan roti jala. Buat pusingan bulat bertindih membentuk jala halus. Masak 40-50 saat tanpa perlu dibalikkan. Angkat, lipat dua belah dan gulung kemas.","ja":"テフロンパンに薄く油を塗り中弱火に。5つ穴ボトルに生地を入れ、フライパンの上で素早く円を描くように重なり合うレース模様を絞り出します。40〜50秒焼いて表面が固まったら取り出します（裏返し不要）。両端を折りたたみ、くるくると棒状に巻きます。","ko":"약불로 달군 코팅 팬에 오일을 얇게 바릅니다. 구멍 뚫린 소스통에 반죽을 넣고 팬 위에서 빠르게 원을 그리며 교차하는 레이스 그물망을 짭니다. 40-50초간 윗면이 마르면 꺼내어 양옆을 접고 돌돌 말아줍니다 (뒤집지 않음!)."},"durationSeconds":720},{"stepNumber":3,"image":"/images/my/roti-jala-step3.jpg","title":{"zh-TW":"同場慢火燉煮香濃大馬椰漿咖哩雞 (Kari Ayam)","en":"Simmer Fragrant Coconut Malaysian Chicken Curry","ms":"Masak Gulai Kari Ayam Kentang Pekat Beraroma","ja":"濃厚なココナッツチキンカレーを煮込む","ko":"진하고 부드러운 코코넛 치킨 커리 끓이기"},"instruction":{"zh-TW":"油鍋爆香洋蔥、蒜末、咖哩葉、桂皮與八角。倒入用少許水調成糊狀的咖哩粉大火慢炒出紅油。放入剁塊雞腿肉與滾刀馬鈴薯塊翻炒 3 分鐘裹滿香料。倒入清水與濃椰漿，小火加蓋慢煨 25 分鐘，直到雞肉軟嫩、馬鈴薯粉糯化入濃稠咖哩湯中。","en":"Sauté onions, garlic, curry leaves, cinnamon and star anise. Stir in curry powder paste and cook until fragrant oil separates. Add chicken pieces and potato chunks; sear 3 mins. Pour in water and coconut cream; simmer covered on low heat for 25 mins until chicken is succulent and potatoes are fork-tender in rich gravy.","ms":"Tumis bawang, daun kari, kayu manis dan bunga lawang. Masukkan pes serbuk kari hingga terbit minyak. Masukkan ayam dan kentang, goreng 3 minit. Tuang air dan santan, reneh 25 minit hingga empuk pekat.","ja":"玉ねぎ、ニンニク、カレーリーフ、シナモンを炒め、カレーペーストを加えて油を分離させます。鶏肉とジャガイモを入れて炒め、水とココナッツクリームを注ぎます。弱火で25分煮込み、ジャガイモがホクホクになるまで仕上げます。","ko":"양파, 마늘, 커리 리프, 계피를 볶다가 커리 페이스트를 넣고 볶습니다. 닭고기와 감자를 넣어 볶은 뒤 물과 코코넛 크림을 부어 약불에서 25분간 닭고기와 감자가 부드러워질 때까지 졸입니다."},"durationSeconds":1500},{"stepNumber":4,"image":"/images/my/roti-jala-step4.jpg","title":{"zh-TW":"金網整齊排盤・大勺熱咖哩沾食","en":"Plate Golden Lace Rolls with Generous Chicken Curry","ms":"Susun Roti Jala Kemas & Hidang Bersama Semangkuk Kari","ja":"黄金レースクレープを並べ、熱々チキンカレーを添えて完成","ko":"황금 레이스 롤을 정갈하게 담고 뜨거운 치킨 커리 곁들여 완성"},"instruction":{"zh-TW":"盤中並排碼放金黃微香的蕾絲網餅卷，旁配上一深碗熱騰騰、漂浮著紅油的濃椰漿咖哩雞與大塊馬鈴薯。拿取一捲蕾絲煎餅，直接完全浸入咖哩汁中——成千上萬個細緻孔隙會在 2 秒內吸飽濃醇湯汁，送入口中瞬間爆汁化開！","en":"Arrange the golden lace cylinders neatly on a platter alongside a deep bowl of piping, oil-kissed coconut chicken curry. Grab a roll, dip it deeply into the sauce—the thousands of delicate webbed pores absorb the gravy in 2 seconds flat, melting in your mouth with sensational richness!","ms":"Susun gulungan roti jala kemas di atas pinggan bersama semangkuk kari ayam kentang panas. Ambil serelung roti jala, celup penuh dalam kuah kari dan nikmati ledakan rasa kuah yang menyerap padu!","ja":"お皿に美しい黄金のロールを並べ、熱々のチキンカレーを添えます。レース状のクレープをカレーに浸すと、無数の隙間にルーが一瞬で染み込み、口の中でジュワッと旨味が広がります！","ko":"접시에 황금빛 레이스 롤을 가지런히 담고 뜨거운 치킨 커리를 곁들입니다. 롤 하나를 집어 커리에 푹 찍으면 수많은 그물망 사이로 커리가 듬뿍 스며들어 입안 가득 감칠맛이 터집니다!"},"durationSeconds":30}],"troubleshooting":[{"id":"pattern-breaks","problem":{"zh-TW":"擠出的網格斷斷續續，無法連成漂亮蕾絲","en":"Lace pattern is broken and clumps together","ms":"Jala terputus-putus dan pekat berketul","ja":"レース模様が途切れたり、太すぎて固まる","ko":"그물망이 뚝뚝 끊기거나 뭉쳐서 예쁜 모양이 안 나옴"},"cause":{"zh-TW":"麵糊太稠或未充分過濾，顆粒堵住瓶孔","en":"Batter too thick or not strained, clogging nozzles","ms":"Adunan terlalu pekat atau tidak ditapis","ja":"生地が固すぎる、または漉していないため穴が詰まった","ko":"반죽이 너무 되직하거나 체에 거르지 않아 구멍이 막힘"},"solution":{"zh-TW":"麵糊質地應如稀鮮奶油般具良好流動性；若偏稠可多補 2 大匙牛奶或水，並務必過濾兩次。","en":"Batter should resemble runny heavy cream. Whisk in 2 tbsp extra milk if thick, strain thoroughly.","ms":"Adunan mesti cair seperti susu segar; tambah 2 sb air/susu jika pekat.","ja":"生クリームのようにサラサラ流れる固さに調整してください。牛乳を大さじ2足して再度漉します。","ko":"반죽은 묽은 생크림처럼 매끄럽게 흘러내려야 합니다. 뻑뻑하다면 우유 2큰술을 더 넣고 다시 걸러주세요."}}],"proTips":[{"zh-TW":"廚房神器替代：如果家裡沒有大馬傳統的「五孔小漏網杯（Acuan Roti Jala）」，只要去烘焙店或超市買一個塑料沙拉擠醬瓶（Squeeze Bottle），或者在紙杯底部用牙籤扎 5 個小孔，就能輕鬆做出五星級漂亮蕾絲！","en":"Kitchen DIY Hack: If you don’t have an authentic five-hole Roti Jala cup, use a cheap condiment squeeze bottle or poke 5 tiny holes in the bottom of a disposable paper cup!","ms":"Petua Jimat Dapur: Jika tiada acuan roti jala tembaga, gunakan botol sos plastik muncung halus atau cucuk 5 lubang kecil pada cawan kertas pakai buang!","ja":"代用裏ワザ：専用の穴あきカップがなくても、100円ショップの調味料絞りボトル（先が細いディスペンサー）や、紙コップの底に爪楊枝で5箇所穴を開けるだけで完璧なレースが作れます！","ko":"주방 꿀팁: 전용 틀이 없다면 소스용 플라스틱 디스펜서 병을 사용하거나, 종이컵 바닥에 이쑤시개로 구멍 5개를 뚫어 사용하면 완벽한 레이스를 만들 수 있습니다!"}]},{"country":"my","id":"ayam-percik","slug":"ayam-percik","title":{"zh-TW":"吉蘭丹椰香炭烤香茅雞","en":"Kelantan Spiced Coconut Basted Grilled Chicken (Ayam Percik)","ms":"Ayam Percik Kelantan Kuah Putih Berkrim Asli","ja":"アヤム・プルチック（吉蘭丹風・濃厚ココナッツグリルチキン）","ko":"아얌 뻐칙 (켈란탄식 코코넛 크림 바비큐 치킨)"},"subtitle":{"zh-TW":"竹夾炭火炙烤・反覆淋刷厚重椰奶香茅甜辣醬・外焦香內爆汁","en":"Bamboo-Clamped Charcoal Fire, Heavily Basted in Lemongrass Coconut Gravy","ms":"Ayam Dibakar Arang Disepit Buluh & Disiram Kuah Percik Pekat Berlemak","ja":"竹に挟み炭火で香ばしく焼き上げ、濃厚なココナッツレモングラスだれを幾重にも重ね塗り","ko":"대나무에 끼워 숯불에 구워내며 달콤매콤한 코코넛 그레이비를 듬뿍 바른 치킨"},"tagline":{"zh-TW":"東海岸吉蘭丹馬來皇室傳奇盛宴！每一寸雞肉都浸透椰香的街頭燒烤霸主","en":"The royal East Coast Kelantanese barbecue legend drenched in cascading coconut silk","ms":"Legenda barbeku Pantai Timur Kelantan yang disalut limpahan kuah santan wangi","ja":"東海岸ケランタン州の誇る宮廷炭火焼き！肉の芯までココナッツが染み渡る極上グリル","ko":"말레이시아 동해안 켈란탄주의 전설적인 바비큐! 코코넛 크림의 풍미가 촉촉하게 배어든 치킨"},"heroImage":"/images/my/ayam-percik.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":35,"defaultServings":4,"caloriesPerServing":520,"category":"mains","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"東海岸・吉蘭丹州與登嘉樓 (Kelantan & Terengganu)","en":"Kelantan & Terengganu (East Coast)","ms":"Kelantan & Terengganu","ja":"マレーシア東海岸・ケランタン州","ko":"말레이시아 동해안 켈란탄 & 트렝가누"},"famousStreetMarkets":[{"zh-TW":"哥打峇魯夜市 (Pasar Malam Kota Bharu)","en":"Kota Bharu Night Market, Kelantan","ms":"Pasar Malam Kota Bharu","ja":"コタバル夜市","ko":"코타바루 야시장"},{"zh-TW":"登嘉樓巴都布洛海濱夜市","en":"Batu Burok Night Beach Market, Terengganu","ms":"Pasar Malam Pantai Batu Burok","ja":"バトゥ・ブロク夜市","ko":"바투 부록 해변 야시장"}],"historyStory":{"zh-TW":"源於馬來半島東北部吉蘭丹蘇丹王宮的御膳。在馬來語中，「Percik」意為「飛濺 / 淋灑」。炭火大師將整隻大雞腿夾在劈開的青竹條中，置於紅火木炭上烘烤。在烤製過程中，大師拿著長柄大勺，不斷將熬得極其濃稠雪白（或橘紅）的香茅椰漿香料醬，豪邁地一勺勺「淋灑」在滋滋作響的雞肉表面，醬汁遇炭火蒸發結痂，層層封裝焦香與甜美肉汁！","en":"Born in the royal courts of the Sultanate of Kelantan. In Malay, \"Percik\" means \"to splatter or splash\". Pitmasters clamp marinated chicken in split bamboo tongs over smoldering mangrove charcoal. Throughout grilling, they continuously ladle and splash dense, creamy lemongrass coconut gravy onto the sizzling skin. The sauce caramelizes into a thick, smoky, lacquer crust.","ms":"Bermula daripada hidangan istana Kesultanan Kelantan. Perkataan \"Percik\" merujuk kepada perbuatan menyiram atau memercikkan kuah santan berempah pekat ke atas ayam yang sedang membakar di atas bara arang.","ja":"ケランタン州の王室料理が発祥。マレー語で「プルチック（Percik）」は「飛び散る、浴びせかける」の意味。竹串に挟んだ鶏肉を炭火で焼きながら、煮詰めた濃厚なココナッツソースを豪快に何度も何度も振りかけて香ばしい衣をまとわせます。","ko":"켈란탄 술탄 왕실 요리에서 유래했습니다. 말레이어로 \"뻐칙(Percik)\"은 \"뿌리다, 끼얹다\"를 의미합니다. 대나무에 끼운 닭고기를 숯불에 구우면서 진한 코코넛 레몬그라스 소스를 반복해서 끼얹어 바삭하고 달콤한 양념 껍질을 만듭니다."},"malayScript":"Ayam Percik Kelantan","malayPhonetics":"Ah-yahm Pehr-cheek Keh-lahn-tahn","audioPronunciationText":"Mokcik, Ayam Percik paha satu, kuah percik banjir atas nasi ya!","communityHeritage":"Malay","nativeName":"Ayam Percik Kelantan","nativePhonetics":"Ayam Percik Kelantan"},"ingredients":[{"id":"whole-chicken-legs-percik","name":{"zh-TW":"帶皮全雞大腿骨肉 (全腿 2 隻 / 切刀口便於入味)","en":"Bone-in Skin-on Whole Chicken Legs (scored deeply)","ms":"Paha Ayam Penuh (Dikelar Dalam)","ja":"骨付き鶏モモ肉（皮付き・火が通りやすいよう切り込みを入れる）","ko":"뼈 있는 닭다리살(장각) (칼집을 깊게 넣은 것)"},"amount":600,"unitMetric":"g","unitUS":"21 oz","isKeyFlavor":true,"malayName":"Paha Ayam","malayPronunciation":"Pah-hah Ah-yahm"},{"id":"pure-santan-percik","name":{"zh-TW":"純濃特級鮮椰漿 (Santan Pekat)","en":"Pure Thick Coconut Milk (Santan)","ms":"Pati Santan Kelapa Pekat Segar","ja":"濃厚ココナッツクリーム（一番搾り）","ko":"진한 순수 코코넛 크림"},"amount":400,"unitMetric":"ml","unitUS":"14 fl oz","isKeyFlavor":true,"malayName":"Pati Santan","malayPronunciation":"Pah-tee Sahn-tahn"},{"id":"percik-spice-paste","name":{"zh-TW":"吉蘭丹香料泥：香茅 4 根、紅蔥頭、大蒜、老薑、南薑、乾辣椒","en":"Percik Paste: 4 lemongrass stalks, shallots, garlic, ginger, galangal, dried chili","ms":"Pes Kisar: Serai, bawang merah, bawang putih, halia, lengkuas, cili kering","ja":"香辛ペースト：レモングラス4本、エシャロット、ニンニク、生姜、唐辛子","ko":"향신 페이스트: 레몬그라스 4대, 샬롯, 마늘, 생강, 갈랑갈, 건고추"},"amount":150,"unitMetric":"g","unitUS":"5 oz","isKeyFlavor":true,"malayName":"Pes Percik Kisar","malayPronunciation":"Pehs Pehr-cheek Kee-sahr"},{"id":"asam-keping-percik","name":{"zh-TW":"亞參果乾片 (Asam Gelugur)","en":"Dried Tamarind Peel Slice (Asam Gelugur / Keping)","ms":"Asam Keping Gelugur","ja":"アサム果皮片","ko":"말린 아삼 조각"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":true,"malayName":"Asam Keping","malayPronunciation":"Ah-sahm Keh-peeng"},{"id":"palm-sugar-percik","name":{"zh-TW":"馬六甲椰糖或天然紅糖","en":"Gula Melaka Palm Sugar or Brown Sugar","ms":"Gula Melaka / Gula Perang","ja":"パームシュガー（または黒糖）","ko":"굴라 말라카 흑당 (또는 흑설탕)"},"amount":35,"unitMetric":"g","unitUS":"2 tbsp","isKeyFlavor":true,"malayName":"Gula Melaka","malayPronunciation":"Goo-lah Meh-lah-kah"}],"steps":[{"stepNumber":1,"image":"/images/my/ayam-percik-step1.jpg","title":{"zh-TW":"調配慢熬極濃椰漿香茅烤醬 (Kuah Percik)","en":"Simmer Thick Lemongrass Coconut Basting Gravy (Kuah Percik)","ms":"Masak Kuah Percik Santan Pekat Memikat Selera","ja":"濃厚なココナッツレモングラスたれをじっくり煮詰める","ko":"걸쭉한 코코넛 레몬그라스 바비큐 소스 끓이기"},"instruction":{"zh-TW":"鍋中倒入 400ml 濃椰漿、磨碎的香茅紅蔥辣椒泥、2 片亞參果乾片、35g 馬六甲椰糖與 1 茶匙海鹽。開中小火慢熬，用木勺不停畫圈攪動防止椰漿燒糊。煮約 15 分鐘，直至水分收乾、醬汁轉為雪白中透著紅亮、濃稠如絲絨布丁膏狀（Kuah Percik），關火取一半備用。","en":"Combine 400ml thick coconut milk, blended aromatics (lemongrass, shallots, chili), 2 asam keping slices, 35g Gula Melaka and 1 tsp salt in saucepan. Simmer over medium-low, stirring constantly to prevent scorching. Cook 15 mins until luscious, velvety and thick enough to coat a spoon heavily. Reserve half for basting.","ms":"Didihkan 400ml pati santan bersama pes kisar, asam keping, gula Melaka dan garam atas api sederhana. Kacau sentiasa selama 15 minit sehingga kuah menjadi pekat berkrim cantik.","ja":"小鍋にココナッツミルク400ml、ペースト、乾燥アサム果皮、パームシュガー、塩を入れます。底が焦げ付かないよう弱火でかき混ぜながら15分煮詰めます。スプーンの背にぽってり乗る濃度の極上ソース（クア・プルチック）を作ります。","ko":"냄비에 코코넛 밀크 400ml, 향신 페이스트, 아삼 조각, 흑당, 소금을 넣습니다. 타지 않게 저어가며 약불에서 15분간 주걱을 들었을 때 걸쭉하게 떨어질 때까지 조려줍니다."},"durationSeconds":900},{"stepNumber":2,"image":"/images/my/ayam-percik-step2.jpg","title":{"zh-TW":"雞腿入濃醬預煮鎖汁 (半熟入味)","en":"Par-Cook Chicken in Aromatic Coconut Gravy for Succulence","ms":"Rebus Paha Ayam Separuh Masak Dalam Kuah Percik","ja":"鶏肉をソースで下煮して芯まで味を染み込ませる","ko":"닭다리를 소스에 넣고 초벌로 삶아 속까지 양념 배게 하기"},"instruction":{"zh-TW":"將劃好刀口的全雞腿放入煮好的熱椰漿醬汁鍋中，開小火加蓋燜煮 12 分鐘（中途翻面一次）。這一步讓雞肉內部吸飽香茅與椰奶鮮甜，同時達到 7 分熟，烤製時絕不會內生外焦！撈出雞腿瀝去多餘湯汁。","en":"Submerge deeply scored chicken legs into the hot coconut gravy. Cover and gently poach on low heat for 12 mins, turning once. This ensures the meat absorbs the lemongrass-coconut essence right to the bone and reaches 70% doneness so it stays outrageously juicy on the grill!","ms":"Masukkan paha ayam ke dalam kuah percik. Tutup dan reneh api kecil 12 minit (balikkan sekali). Kaedah ini memastikan isi ayam menyerap pati santan dan empuk berjus tanpa hangus.","ja":"切り込みを入れた鶏モモ肉をソース鍋に入れ、蓋をして弱火で12分下煮します（途中で一度裏返す）。中までしっかり火が通り、骨の周りまでココナッツの甘みが浸透します。","ko":"칼집을 넣은 닭다리를 조린 소스에 넣고 뚜껑을 덮어 약불에서 12분간 앞뒤로 익힙니다. 이렇게 하면 속까지 양념이 깊게 배고 그릴에서 겉만 타는 것을 방지할 수 있습니다."},"durationSeconds":720},{"stepNumber":3,"image":"/images/my/ayam-percik-step3.jpg","title":{"zh-TW":"炭火或氣炸炙烤・反覆重刷厚重椰漿醬 (Percik 靈魂)","en":"Charcoal Grill or Air Fry & Continually Splash Cascading Gravy","ms":"Bakar Atas Arang / Air Fryer & Siram Kuah Percik Berkali-kali","ja":"炭火またはエアフライヤーで焼き、ソースを何度も重ね塗りする","ko":"숯불 또는 에어프라이어에 구우며 코코넛 소스를 반복해서 바르기"},"instruction":{"zh-TW":"炭烤爐（或氣炸鍋）：將下煮好的雞腿置於烤架上大火炙烤。每烤 2 分鐘翻面一次，每一次翻面都用大勺將濃稠的椰漿烤醬厚厚地「淋灑刷覆（Percik）」在雞皮上，重複刷塗 4-5 次！高溫炭火將外層椰漿焦糖化，形成金黃斑駁、微焦酥香的絕美厚醬殼！","en":"Place par-cooked chicken on hot grill grate (or air fryer basket). Flip every 2 mins. With every single flip, heavily splash and brush a thick ladleful of the reserved coconut gravy onto the bubbling skin. Repeat 4-5 times until layers of coconut caramelize into a smoky, golden-brown crackly armor!","ms":"Bakar ayam atas bara arang. Balikkan setiap 2 minit sambil menyiram kuah percik tebal ke atas kulit berkali-kali. Kuah akan berkaramel menghasilkan kerak keemasan yang harum.","ja":"鶏肉を網に乗せて強火でグリル（またはエアフライヤー）。2分ごとに裏返し、その度に濃厚ソースをたっぷり重ね塗りします。4〜5回繰り返すことで、ココナッツが香ばしくキャラメリゼされ、パリッとした極上の香ばしい衣が完成します！","ko":"닭고기를 그릴(또는 에어프라이어)에 올립니다. 2분마다 뒤집어가며 매번 조려둔 코코넛 소스를 듬뿍 덧발라줍니다. 4-5회 반복하면 코코넛 소스가 노릇하게 캐러멜라이징되어 기가 막힌 껍질을 만듭니다!"},"durationSeconds":600,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) 12-14 mins, brushing sauce every 3 mins","instructionOverride":{"zh-TW":"氣炸鍋模式：放入炸籃 190°C 烤，每隔 3 分鐘拉出炸籃厚厚刷上一層椰漿醬，烤 12-14 分鐘即可外脆內爆汁！","en":"Air Fryer: At 190°C (375°F), slide basket out every 3 mins to heavily brush coconut gravy. Cook 12-14 mins.","ms":"Air Fryer: Bakar pada 190°C, sapu kuah percik setiap 3 minit selama 12-14 minit.","ja":"エアフライヤー：190℃で加熱し、3分ごとに引き出してソースを重ね塗り。計12〜14分で絶品に仕上がります。","ko":"에어프라이어: 190℃에서 조리하며 3분마다 바스켓을 꺼내 소스를 덧발라줍니다. 총 12-14분 조리."}}]},{"stepNumber":4,"image":"/images/my/ayam-percik-step4.jpg","title":{"zh-TW":"裝盤淋上熱烤醬・搭配白飯享用","en":"Serve Piping Hot Doused in Extra Hot Percik Gravy","ms":"Hidang Panas Bersama Limpahan Kuah Percik & Nasi","ja":"お皿に盛り、残りの熱々ソースをたっぷりかけていただく","ko":"접시에 담고 남은 뜨거운 소스를 듬뿍 부어 완성"},"instruction":{"zh-TW":"烤至邊緣金黃微焦、香氣四溢的香茅烤雞出爐裝盤。將鍋中剩餘的熱椰漿醬汁，大方地淋在烤雞表面。雞皮酥脆微焦、雞肉撕開肉汁四濺，濃厚的椰香與香茅清新在舌尖狂野迸發！配上一大碗熱白飯或藍花飯，令人欲罷不能！","en":"Transfer the glistening, smoky-charred chicken leg onto serving platter. Lavishly douse remaining piping hot coconut percik gravy all over the chicken. The skin is blistered and crisp, the meat gushes seasoned juices, and the sweet-savory coconut richness is pure heaven!","ms":"Angkat ayam bakar beraroma ke atas pinggan. Curahkan baki kuah percik panas ke atas ayam. Kulit garing berkaramel, isi berjus dan lemak manis santan sangat padu dinikmati bersama nasi panas!","ja":"香ばしい焦げ目がついたチキンをお皿に盛り、残った熱々のソースを豪快に回しかけます。皮はパリッと香ばしく、中は驚くほどジューシー！ココナッツの優しい甘みとレモングラスの清涼感が最高です。","ko":"노릇하게 구워진 치킨을 접시에 담고 남은 따뜻한 코코넛 소스를 듬뿍 끼얹어냅니다. 겉은 바삭하고 속은 촉촉한 육즙이 터지며 코코넛의 부드러움과 레몬그라스의 상큼함이 입안을 가득 채웁니다!"},"durationSeconds":30}],"troubleshooting":[{"id":"sauce-burnt","problem":{"zh-TW":"烤雞表面醬汁焦黑發苦，但裡面肉還帶血","en":"Skin blackened and burnt while inside is still undercooked","ms":"Kulit hangus pahit tetapi isi dalam masih mentah","ja":"外側のタレが焦げて苦いのに、中が生焼け","ko":"겉의 양념은 새까맣게 탔는데 속은 덜 익음"},"cause":{"zh-TW":"火力太猛且跳過了「醬汁鍋中預煮 12 分鐘」的關鍵步驟","en":"Fire too hot and skipped the vital par-cooking step in gravy","ms":"Api terlalu besar dan tidak merebus ayam terlebih dahulu","ja":"火力が強すぎる、または事前の下煮工程を省いた","ko":"불이 너무 세거나 소스에 넣고 초벌로 삶는 과정을 건너뜀"},"solution":{"zh-TW":"務必先在熱醬鍋中小火燜煮 12 分鐘至 7 分熟；烤製時火候轉中火，專注讓外層椰糖焦糖化即可。","en":"Always par-boil chicken in gravy for 12 mins first to ensure interior safety before quick-caramelizing over medium coals.","ms":"Wajib reneh ayam dalam kuah selama 12 minit sebelum membakar di atas api sederhana.","ja":"必ず事前にソースで12分間下煮してください。中火で表面のココナッツをキャラメリゼするだけに集中できます。","ko":"반드시 소스에서 12분간 초벌로 익힌 뒤 구워주세요. 그릴에서는 겉면을 노릇하게 캐러멜라이징하는 것에만 집중하면 됩니다."}}],"proTips":[{"zh-TW":"正宗吉蘭丹秘訣：椰漿一定要用「鮮榨第一道濃椰漿（Pati Santan）」，油脂豐富且天然甘甜，不需要加太多的糖，烤出來的焦糖香氣自然醇厚迷人。","en":"Pitmaster Secret: Use first-press thick coconut milk (Pati Santan)! Its rich natural lipids caramelize with zero scorched bitterness, delivering a silk-textured golden crust.","ms":"Petua Tok Guru: Wajib guna pati santan perahan pertama yang pekat berlemak untuk aroma karamel asli yang memukau.","ja":"本場の極意：必ず高濃度の生ココナッツミルク（一番搾り）を使用してください。上質な脂分が焦げ付かずに美しい黄金色のキャラメル膜を作ります。","ko":"장인의 비법: 반드시 처음 착즙한 진한 코코넛 밀크를 사용하세요! 풍부한 천연 유지방이 타지 않고 아름다운 황금빛 캐러멜 껍질을 완성합니다."}]},{"country":"my","id":"otak-otak-muar","slug":"otak-otak-muar","title":{"zh-TW":"麻坡香烤香蕉葉烏達魚肉糕","en":"Muar Grilled Banana Leaf Fish Custard (Otak-Otak)","ms":"Otak-Otak Ikan Tenggiri Muar Bakar Daun Pisang","ja":"ジョホール・ムアル名物・バナナの葉包み焼きスパイシー魚ムース（オタオタ）","ko":"무아르 바나나잎 직화 생선 수플레 핫바 (오탁오탁)"},"subtitle":{"zh-TW":"野生馬鮫魚細打肉蓉・椰奶香茅咖哩辛香・芭蕉葉炭烤焦香彈牙","en":"Spanish Mackerel Mousse, Coconut Milk, Lemongrass & Grilled in Smoky Banana Leaves","ms":"Isi Ikan Tenggiri Tumbuk Halus, Santan, Serai & Daun Limau Dibakar Arang","ja":"新鮮なサワラのすり身、ココナッツミルクとレモングラスの風味、炭火で香ばしく焦がしたバナナ葉","ko":"신선한 삼치 살을 곱게 갈아 코코넛 밀크와 향신료로 반죽한 뒤 바나나 잎에 구운 피시 케이크"},"tagline":{"zh-TW":"柔佛麻坡（Muar）第一名產！打開焦脆香蕉葉瞬間香氣撲鼻的街頭神話","en":"The crown culinary glory of Muar, Johor! An explosion of fragrance upon unwrapping charred leaves","ms":"Kemegahan warisan bandar Muar, Johor! Haruman memikat sejurus membuka bungkusan daun pisang bakar","ja":"ジョホール州ムアルの誇る名物！焦げたバナナの葉を開いた瞬間に広がるスパイスと魚の芳香","ko":"조호르주 무아르(Muar)의 자부심! 불에 탄 바나나 잎을 펼치는 순간 향긋한 바다의 풍미가 가득"},"heroImage":"/images/my/otak-otak-muar.jpg","difficulty":"medium","prepTimeMinutes":30,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":280,"category":"streetSnacks","dietaryTags":["classic","pescatarian","halal","glutenFree"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"南馬・柔佛麻坡 (Muar, Johor)","en":"Muar, Johor (Otak-Otak Capital)","ms":"Muar, Johor","ja":"南マレーシア・ジョホール州ムアル","ko":"말레이시아 남부 / 조호르 무아르"},"famousStreetMarkets":[{"zh-TW":"麻坡貪吃街 (Jalan Haji Abu)","en":"Glutton Street (Jalan Haji Abu), Muar","ms":"Jalan Haji Abu (Glutton Street) Muar","ja":"ムアル貪吃街（食いしん坊通り）","ko":"무아르 먹자골목 (잘란 하지 아부)"},{"zh-TW":"新山老街陳旭年夜市","en":"Jalan Tan Hiok Nee Night Bazaar, JB","ms":"Jalan Tan Hiok Nee JB","ja":"JBタン・ヒオク・ニー通り","ko":"조호르바루 탄히옥니 문화 거리"}],"historyStory":{"zh-TW":"「Otak」在馬來語中本意為「大腦」，因魚肉泥混合蛋液蒸熟後質地軟嫩如腦髓而得名。柔佛麻坡靠海，潮州與娘惹漁民將當天捕獲的極鮮馬鮫魚（Ikan Tenggiri）刮下肉蓉，加入石臼舂搗的香茅、南薑、乾辣椒、薑黃、濃椰漿與新鮮雞蛋，順時針反覆摔打上勁。用裁好的芭蕉葉或尼芭葉（Attap Leaf）包成扁長條，以牙籤固定兩端，放在炭火上翻烤至葉面微焦起泡，鮮甜微辣，回味無窮。","en":"In Malay, \"Otak\" means \"brains\", playfully named for the soft, cloud-like soufflé custard texture of spiced steamed fish paste. In the coastal town of Muar, Teochew and Peranakan fisherfolk scraped wild Spanish mackerel into paste, whipped it with pounded lemongrass, galangal, turmeric, coconut cream and eggs, then wrapped it into slender parcels using banana or attap leaves before grilling over charcoal.","ms":"Dinamakan \"Otak-otak\" kerana teksturnya yang lembut gebu bak otak apabila dikukus. Masyarakat Muar mengadun isi ikan tenggiri segar bersama rempah kunyit, cili dan santan, dibungkus daun pisang/nipah dan dibakar atas bara arang.","ja":"マレー語で「オタッ（Otak）」は「脳」の意味。スパイスと卵で練り上げた魚のすり身が、フワフワの脳みそのような柔らかい食感になることから名付けられました。ムアルの漁師町で獲れたてのサワラをすり身にし、バナナの葉で平たく包んで炭火で香ばしく焼き上げます。","ko":"말레이어로 \"오탁(Otak)\"은 \"뇌\"를 뜻하며, 부드러운 수플레 같은 생선 살의 식감에서 유래했습니다. 조호르 무아르의 어민들이 신선한 삼치 살을 으깨어 코코넛 밀크, 강황, 고추와 버무려 바나나 잎에 싸서 숯불에 구워낸 전통 스낵입니다."},"malayScript":"Otak-Otak Muar Bakar","malayPhonetics":"Oh-tahk Oh-tahk Moo-ahr Bah-kahr","audioPronunciationText":"Amoi, Otak-Otak bakar sepuluh keping, bungkus ya!","communityHeritage":"Peranakan","nativeName":"Otak-Otak Muar Bakar","nativePhonetics":"Otak-Otak Muar Bakar"},"ingredients":[{"id":"mackerel-fillet-otak","name":{"zh-TW":"新鮮馬鮫魚肉 (土魠魚 / 刮下肉泥)","en":"Fresh Spanish Mackerel Fillet (Ikan Tenggiri, scraped)","ms":"Isi Ikan Tenggiri Segar (Kikis Halus)","ja":"新鮮なサワラ（鰆）の切り身（スプーンで身をこそげる）","ko":"신선한 삼치 살 (숟가락으로 살만 긁어낸 것)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"malayName":"Isi Ikan Tenggiri","malayPronunciation":"Ee-see Ee-kahn Tehng-gee-ree"},{"id":"otak-rempah-paste","name":{"zh-TW":"烏達香料泥：乾辣椒、紅蔥頭、香茅、大蒜、南薑、薑黃、烤 Belacan","en":"Otak Rempah: Dried chilies, shallots, lemongrass, garlic, galangal, turmeric, toasted belacan","ms":"Pes Rempah Otak-otak (Serai, cili, bawang, lengkuas, kunyit, belacan)","ja":"オタオタ香辛ペースト（唐辛子、エシャロット、レモングラス、ブラチャン）","ko":"오탁오탁 향신 페이스트 (건고추, 샬롯, 레몬그라스, 갈랑갈, 벨라찬)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"malayName":"Pes Rempah Otak","malayPronunciation":"Pehs Rehm-pah Oh-tahk"},{"id":"thick-coconut-milk-otak","name":{"zh-TW":"純濃椰漿 (Santan Pekat)","en":"Pure Thick Coconut Milk (Santan)","ms":"Pati Santan Kelapa Asli","ja":"濃厚純ココナッツミルク","ko":"진한 순수 코코넛 밀크"},"amount":120,"unitMetric":"ml","unitUS":"4 fl oz","isKeyFlavor":true,"malayName":"Pati Santan","malayPronunciation":"Pah-tee Sahn-tahn"},{"id":"egg-and-tapioca","name":{"zh-TW":"全蛋 1 顆 + 樹薯澱粉 (木薯粉)","en":"1 Whole Egg + Tapioca Starch (for bouncy springiness)","ms":"Telur Ayam & Tepung Ubi Kayu","ja":"全卵1個＋タピオカ澱粉（弾力を生むつなぎ）","ko":"달걀 1개 + 타피오카 전분 (탱글탱글한 탄력)"},"amount":40,"unitMetric":"g","unitUS":"2.5 tbsp","isKeyFlavor":false,"malayName":"Tepung Ubi","malayPronunciation":"Teh-poong Oo-bee"},{"id":"banana-leaves-otak","name":{"zh-TW":"鮮芭蕉葉 (裁成 15x18cm 矩形 / 微烤軟化)","en":"Banana Leaves (cut to 15x18cm sheets, warmed to soften)","ms":"Daun Pisang Bersih (Layur Lembut)","ja":"バナナの葉（15×18cmにカットし軽く火で炙って柔らかくしたもの）","ko":"바나나 잎 (15x18cm 재단 후 살짝 불에 쬐어 부드럽게 한 것)"},"amount":12,"unitMetric":"piece","unitUS":"12 sheets","isKeyFlavor":true,"malayName":"Daun Pisang","malayPronunciation":"Dah-oon Pee-sahng","substitute":{"substituteName":{"zh-TW":"烘焙不沾鋁箔紙 (外層) 抹薄油直接烤","en":"Baking Foil lightly oiled or parchment paper","ms":"Kertas aluminium disapu minyak","ja":"アルミホイル（内側に薄く油を塗る）","ko":"알루미늄 호일 (안쪽에 오일 살짝 바름)"},"ratio":"1:1","explanation":{"zh-TW":"買不到芭蕉葉時，鋁箔紙是極佳替代方案，方便氣炸鍋或烤箱操作。","en":"Aluminum foil works wonderfully for oven or air fryer if leaves are unavailable.","ms":"Aluminium foil boleh digunakan untuk bakar dalam oven atau air fryer.","ja":"バナナの葉がない場合はアルミホイルで代用でき、魚焼きグリルでも作れます。","ko":"바나나 잎이 없다면 알루미늄 호일로 감싸 에어프라이어에 구워도 좋습니다."},"whereToBuy":{"zh-TW":"一般超市","en":"Any supermarket","ms":"Pasar raya","ja":"スーパー","ko":"일반 마트"}}}],"steps":[{"stepNumber":1,"image":"/images/my/otak-otak-muar-step1.jpg","title":{"zh-TW":"刮取馬鮫魚泥・順時針摔打起膠上勁","en":"Scrape Mackerel & Slap Paste into Springy Elastic Mousse","ms":"Kikis Isi Ikan Tenggiri & Banting Hingga Kenyal Anjal","ja":"サワラの身をこそげ、叩きつけるように練り混ぜて弾力を出す","ko":"삼치 살을 긁어내 치대며 찰진 탄력 만들기"},"instruction":{"zh-TW":"將新鮮馬鮫魚肉用金屬金屬匙順著魚刺方向刮下細膩魚肉蓉（挑出筋膜與碎刺）。放入攪拌盆中，加 1 茶匙海鹽，用手指張開順同一個方向劇烈攪打 5 分鐘，並不時抓起魚泥在盆中大力摔打（Banting），直到魚肉吸收鹽分蛋白質起膠、呈現極具彈性的黏稠膠質狀態！","en":"Scrape fresh mackerel fillets with a metal spoon along the spine to harvest pure flesh without bones. Place in bowl with 1 tsp salt. Vigorously whip in one direction with fingers for 5 mins, repeatedly lifting and slapping the paste against the bowl (Banting) until the proteins gel into a bouncy, elastic paste!","ms":"Kikis isi ikan tenggiri dengan sudu besi. Masukkan garam dan gaul satu arah secara laju selama 5 minit. Banting isi ikan ke dalam mangkuk berkali-kali hingga kenyal melekit.","ja":"サワラの身を金属スプーンで骨に沿ってこそげ取ります。塩小さじ1を加え、指先で同じ方向に5分間激しく練り混ぜ、ボウルにバシバシ叩きつけて粘りを出します。","ko":"숟가락으로 삼치의 가시를 피해 살만 곱게 긁어냅니다. 소금 1작은술을 넣고 한 방향으로 5분간 힘차게 저은 뒤 볼 바닥에 내리치며 탄력 있는 찰기가 생길 때까지 치댑니다."},"durationSeconds":360},{"stepNumber":2,"image":"/images/my/otak-otak-muar-step2.jpg","title":{"zh-TW":"混入香料泥、特濃椰漿與全蛋調勻","en":"Fold in Otak Rempah, Pure Coconut Milk & Egg Custard","ms":"Gaul Pes Rempah, Pati Santan, Telur & Tepung Ubi","ja":"スパイスペースト、ココナッツミルク、卵を加えて混ぜ合わせる","ko":"향신 페이스트, 코코넛 밀크, 달걀, 전분을 넣고 고루 섞기"},"instruction":{"zh-TW":"在起膠的魚蓉中倒入 100g 炒香的烏達香料泥、120ml 濃純椰漿、1 顆全蛋、40g 樹薯木薯粉、1 大匙糖與少許白胡椒粉。繼續用手順向充分拌勻，直至成為橘紅油亮、如絲滑舒芙蕾慕斯般的豐潤魚肉糊。","en":"Add 100g sautéed Otak rempah paste, 120ml thick coconut milk, 1 whole egg, 40g tapioca starch, 1 tbsp sugar and white pepper to the fish paste. Mix thoroughly in the same direction until it transforms into a glossy, fragrant, salmon-orange mousse emulsion.","ms":"Masukkan pes rempah, santan pekat, telur, tepung ubi kayu, gula dan lada putih. Gaul sebati sehingga menjadi adunan kastard ikan berwarna oren kemerahan yang berkilat.","ja":"魚すり身に、スパイスペースト100g、ココナッツミルク120ml、卵1個、タピオカ粉40g、砂糖、白胡椒を加えます。全体が艶やかなオレンジ色のスフレ状ムースになるまでしっかり混ぜ合わせます。","ko":"치댄 생선 반죽에 볶은 향신 페이스트 100g, 진한 코코넛 밀크 120ml, 달걀 1개, 타피오카 전분 40g, 설탕, 백후추를 넣고 매끄러운 주황빛 무스 상태가 될 때까지 섞어줍니다."},"durationSeconds":300},{"stepNumber":3,"image":"/images/my/otak-otak-muar-step3.jpg","title":{"zh-TW":"芭蕉葉包裹定型・牙籤封口","en":"Enfold Fish Mousse in Banana Leaves & Pin with Toothpicks","ms":"Bungkus Inti Ikan Dalam Daun Pisang & Semat Lidi","ja":"バナナの葉で魚ムースを細長く包み、爪楊枝で留める","ko":"바나나 잎에 생선 반죽을 올리고 감싸 이쑤시개로 고정하기"},"instruction":{"zh-TW":"取一片過火軟化的芭蕉葉，光面朝上。在中央抹上約 2-3 大匙長條狀厚魚肉糊（約 1.5 公分厚）。將芭蕉葉上下對折包裹住魚肉，再將兩端稍微折疊，用木牙籤（或釘書針）橫向穿透固定兩端，整形成扁平條狀。","en":"Lay a softened banana leaf sheet shiny side up. Spoon 2-3 heaped tbsp of fish mousse along the center into a long strip (1.5cm thick). Fold top and bottom leaves over the filling to overlap snugly. Secure both open ends tightly with toothpicks (or staples) to create a neat flat rectangular packet.","ms":"Bentang daun pisang lembut. Letakkan 2-3 sb adunan ikan di tengah secara memanjang. Lipat daun menutupi inti dan sematkan lidi di kedua-dua hujung kemas.","ja":"火で炙って柔らかくしたバナナの葉の中央に、魚ムースを大さじ2〜3杯細長く乗せます。上下を折りたたんで包み、両端を爪楊枝で留めて平たい長方形に整えます。","ko":"부드러워진 바나나 잎 중앙에 생선 반죽을 2-3큰술 길게 올립니다. 잎을 위아래로 감싸 덮은 뒤 양쪽 끝을 접어 이쑤시개로 고정해 납작한 직사각형 모양으로 만듭니다."},"durationSeconds":480},{"stepNumber":4,"image":"/images/my/otak-otak-muar-step4.jpg","title":{"zh-TW":"炭火翻烤或氣炸出焦香・趁熱撕開享用","en":"Grill over Coals or Air Fry until Leaf Blisters & Savor","ms":"Bakar Arang / Air Fryer Hingga Daun Garing Beraroma","ja":"炭火またはエアフライヤーで葉が焦げるまで香ばしく焼いて完成","ko":"숯불 또는 에어프라이어에 잎이 그을릴 때까지 구워 완성"},"instruction":{"zh-TW":"置於炭火烤架（或平底鍋 / 氣炸鍋）：中火每面慢烤約 4-5 分鐘，中途翻面兩次。烤到芭蕉葉外皮焦黑鼓起、散發濃郁植物焦香，內部魚糕凝固彈牙！取下牙籤，雙手一拉撕開焦香芭蕉葉——熱氣蒸騰、橘紅誘人的烏達魚糕微焦彈嫩，入口即化、香辣回甘！","en":"Place parcels on charcoal grill grate (or dry pan / air fryer). Grill over medium heat for 4-5 mins per side, flipping twice. Cook until banana leaves char and blister with intense herbal smoke while the interior puffs into a bouncy custard! Unpin toothpicks, pull open the smoking leaf, and devour the warm, spicy, velvety fish cake directly!","ms":"Bakar atas bara arang atau kuali leper selama 4-5 minit setiap belah. Daun pisang akan garing hangus dan mengeluarkan aroma daun wangi. Buka lidi dan nikmati otak-otak panas yang gebu kenyal dan pedas lemak manis!","ja":"炭火（またはフライパン/エアフライヤー）に乗せ、両面を4〜5分ずつ返しながら焼きます。バナナの葉がこんがり焦げて香ばしい煙が立ち、中のすり身がふっくら膨らんだら完成！葉を開けて熱々をハフハフと頬張ります。","ko":"숯불(또는 마른 팬/에어프라이어)에 올리고 양면을 4-5분씩 뒤집어가며 굽습니다. 바나나 잎이 거뭇하게 그을리며 특유의 향이 배어들고 속의 생선살이 탱글하게 익으면 완성입니다! 잎을 펼쳐 뜨거울 때 바로 드세요."},"durationSeconds":600,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) 10-12 mins, flipping halfway","instructionOverride":{"zh-TW":"氣炸鍋模式：包好的烏達平鋪炸籃，190°C 烤 10-12 分鐘，中途翻面一次，葉片微焦內部鮮美多汁！","en":"Air Fryer: Place packets in single layer. Air fry at 190°C (375°F) for 10-12 mins, flipping halfway.","ms":"Air Fryer: Susun dalam bakul, bakar 190°C selama 10-12 minit, balikkan separuh masa.","ja":"エアフライヤー：重ならないように並べ、190℃で10〜12分（途中で一度裏返す）。手軽に極上の仕上がりに。","ko":"에어프라이어: 겹치지 않게 넣고 190℃에서 10-12분간 조리 (중간에 한 번 뒤집기)."}}]}],"troubleshooting":[{"id":"texture-grainy","problem":{"zh-TW":"烏達口感粗糙散碎，缺乏彈牙細滑感","en":"Otak-otak is crumbly and lacks bouncy, springy custard texture","ms":"Otak-otak berderai dan tidak kenyal anjal","ja":"仕上がりがボソボソして弾力がない","ko":"오탁오탁 식감이 푸석하고 탱글탱글하지 않음"},"cause":{"zh-TW":"刮魚肉時帶入粗筋膜、未順同一個方向攪打上勁、或缺少木薯粉與雞蛋乳化","en":"Included tough connective tissue, didn’t whip in single direction, or missing starch/egg","ms":"Tisu urat ikan tidak dibuang atau tidak dibanting secukupnya","ja":"筋を取り除いていない、または一方向への練り・叩きつけ工程が不足","ko":"힘줄을 제거하지 않았거나 한 방향으로 충분히 치대지 않음"},"solution":{"zh-TW":"務必用匙只刮取純淨魚肉；加鹽後必須同方向攪打 5 分鐘並大力摔打起膠，雞蛋與椰漿提供絲滑乳化。","en":"Scrape only tender meat with spoon; whip strictly in one direction with salt to extract actomyosin proteins.","ms":"Kikis isi sahaja dan banting dalam mangkuk hingga melekit kenyal sebelum campur santan.","ja":"必ずスプーンで純粋な身だけをこそげ、塩を加えてから粘りが出るまで徹底的に叩きつけてください。","ko":"숟가락으로 살만 긁어내고 소금을 넣은 뒤 찰기가 생길 때까지 충분히 치대어 단백질을 활성화하세요."}}],"proTips":[{"zh-TW":"麻坡在地老饕吃法：去麻坡貪吃街，一坐下老闆就會直接把熱騰騰剛烤好的 20 支 Otak-Otak 整捆擺在桌上！吃一支拿一支，吃完數空竹籤算錢。夾進剛烤好的白土司裡當「烏達夾心吐司」，是當地最強隱藏吃法！","en":"Muar Street Custom: In Muar, vendors drop a bundle of 20 sizzling grilled packets right on your table! You eat as many as you crave and pay by counting the empty skewers. Pro-tip: Stuff a smoking hot Otak-Otak between toasted white bread for the ultimate sandwich!","ms":"Budaya Unik Muar: Peniaga akan meletakkan 20 keping otak-otak panas atas meja anda! Makan berapa banyak yang anda mahu dan bayar mengikut lidi kosong. Cuba kapit otak-otak panas dalam roti bakar!","ja":"ムアルの屋台流儀：席に着くと店主が焼き立てのオタオタを20本ドンと机に置いてくれます！好きなだけ食べ、最後に空の串を数えてお会計。トーストした食パンに挟んで食べる「オタオタ・サンド」は現地最高の裏ワザ！","ko":"무아르 현지 문화: 자리에 앉으면 갓 구운 오탁오탁 20개를 테이블에 놓아줍니다! 원하는 만큼 먹고 남은 꼬치 개수로 계산합니다. 바삭하게 구운 토스트 사이에 끼워 먹으면 기가 막힙니다!"}]},{"country":"my","id":"kaya-toast","slug":"kaya-toast","title":{"zh-TW":"南洋咖椰牛油烤吐司佐生熟蛋","en":"Nanyang Kaya Butter Toast & Half-Boiled Eggs","ms":"Roti Bakar Kaya Butter & Telur Separuh Masak","ja":"南洋カヤバタートースト＆半熟卵セット（コピティアム朝食の女王）","ko":"남양 카야 버터 토스트 & 반숙란 세트 (코피티암 전통 조식)"},"subtitle":{"zh-TW":"炭烤酥脆薄吐司・天然香蘭手工咖椰醬・冰凍厚切有鹽牛油・黑醬油流心蛋","en":"Charcoal Crisp Toast, Homemade Pandan Kaya Jam, Slab of Chilled Butter & Runny Eggs","ms":"Roti Bakar Rangup, Kaya Pandan Asli, Mentega Sejuk Tebal & Telur Goyang Kicap","ja":"炭火で香ばしく焼いた薄切りパン、自家製パンダンカヤジャム、冷たい厚切り有塩バター、黒醤油と白胡椒の温泉卵","ko":"바삭하게 구운 토스트, 수제 판단 카야잼, 차가운 두툼한 버터, 흑간장 백후추 반숙란"},"tagline":{"zh-TW":"大馬百年南洋茶室最神聖的開晨儀式！冰火交融與甜鹹爆擊的極致經典","en":"The century-old sacred morning ritual of Malaysian Kopitiams—an exquisite dance of ice and fire","ms":"Ritual sarapan pagi paling legenda di kedai kopi warisan Kopitiam Malaysia","ja":"マレーシアの喫茶店（コピティアム）100年の歴史が誇る朝食の王者！温かさと冷たさの絶妙な調和","ko":"말레이시아 전통 다방 코피티암의 100년 역사를 대표하는 영혼의 아침 식사 세트"},"heroImage":"/images/my/kaya-toast.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":380,"category":"desserts","dietaryTags":["classic","vegetarian","halal"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"全馬全境・發源於海南傳統南洋茶室 (Kopitiam Heritage)","en":"Nationwide / Hainanese Kopitiam Heritage","ms":"Seluruh Malaysia / Kedai Kopi Warisan Hainan","ja":"マレーシア全土・海南系伝統喫茶店","ko":"말레이시아 전역 / 하이난 전통 코피티암"},"famousStreetMarkets":[{"zh-TW":"吉隆坡茨廠街何九海南茶店 (百年老字號)","en":"Ho Kow Hainam Kopitiam (Est. 1956), Petaling Street, KL","ms":"Ho Kow Hainam Kopitiam KL","ja":"何九海南茶店（1956年創業・ペタリン通り）","ko":"허카우 하이난 다방 (1956년 창업)"},{"zh-TW":"霹靂怡保新源隆茶室 (白咖啡發源地)","en":"Sin Yoon Loong White Coffee Kopitiam, Ipoh","ms":"Kedai Kopi Sin Yoon Loong Ipoh","ja":"新源隆（ホワイトコーヒー発祥の店）","ko":"신윤롱 (화이트 커피 발상지)"}],"historyStory":{"zh-TW":"20 世紀初海南人渡海南下，在英殖民大戶人家擔任私廚。受英國管家早晨享用「英式果醬吐司與半熟蛋」的習慣啟發，海南名廚發揮南洋智慧，用新鮮香蘭葉萃取汁液，慢火攪拌椰漿、雞蛋與糖，熬出比果醬更芬芳柔滑的天然抹醬「Kaya（咖椰，馬來語意為富有、濃郁）」。搭配炭火烤得薄脆如餅乾的吐司，夾入厚切冰涼有鹽牛油，以及淋上深黑大馬老抽與白胡椒的養生生熟蛋，造就了南洋人百年來不可動搖的靈魂早茶。","en":"Hainanese chefs working in British colonial households innovated an Asian counterpoint to Western fruit marmalade toast. They slow-stirred eggs, thick coconut milk, sugar and fresh aromatic pandan juice into \"Kaya\" (meaning \"rich\" in Malay). Paired with charcoal-toasted bread, a thick slab of freezing cold salted butter, and two half-boiled eggs laced with dark caramel soy sauce and Sarawak white pepper.","ms":"Dicipta oleh tukang masak Hainan yang mengadaptasi sarapan barat Inggeris. Menggunakan santan, telur, gula dan daun pandan untuk menghasilkan jem \"Kaya\" yang berlemak manis. Diapit bersama kepingan mentega sejuk dan dimakan bersama telur separuh masak kicap.","ja":"英国人のハウスボーイや料理人を務めた海南島出身者が西洋のマーマレードトーストをヒントに開発。ココナッツミルク、卵、砂糖にパンダンリーフを加えて煮詰めた濃厚な「カヤジャム（Kayaはマレー語で豊かなという意味）」を考案。冷たい有塩バターを挟み、黒醤油と胡椒を垂らした温泉卵にディップして食べる文化を定着させました。","ko":"영국 식민지 시절 서양식 잼 토스트에서 힌트를 얻어 탄생했습니다. 코코넛 밀크, 달걀, 판단잎으로 달콤하고 고소한 \"카야(풍요로움을 뜻함)\" 잼을 개발하여, 바삭한 빵에 차가운 버터와 함께 샌드하고 반숙란을 곁들였습니다."},"malayScript":"Roti Bakar Kaya Butter","malayPhonetics":"Roh-tee Bah-kahr Kah-yah Boo-tehr","audioPronunciationText":"Tauke, Roti Bakar Kaya Butter satu set, telur separuh masak dua biji, Kopi O Peng satu!","communityHeritage":"Chinese","nativeName":"Roti Bakar Kaya Butter","nativePhonetics":"Roti Bakar Kaya Butter"},"ingredients":[{"id":"white-bread-thin","name":{"zh-TW":"傳統白吐司切片 (切除厚皮)","en":"White Sandwich Bread (Crust trimmed, sliced thin)","ms":"Roti Benggali / Roti Putih","ja":"食パン（8〜10枚切りの薄切り、耳をカット）","ko":"하얀 식빵 (얇게 썬 것, 테두리 제거)"},"amount":4,"unitMetric":"piece","unitUS":"4 slices","isKeyFlavor":false,"malayName":"Roti Putih","malayPronunciation":"Roh-tee Poo-teeh"},{"id":"salted-butter-block","name":{"zh-TW":"特級純有鹽牛油 (SCS / Anchor / 冰凍厚切厚片)","en":"Pure Salted Butter (SCS or Anchor, chilled & sliced into thick slabs)","ms":"Mentega Bergaram Asli (Potong Tebal Sejuk)","ja":"高級有塩バター（キンキンに冷やした厚切りスライス）","ko":"순수 가염 버터 (차갑게 보관한 두툼한 조각)"},"amount":40,"unitMetric":"g","unitUS":"2.5 tbsp","isKeyFlavor":true,"malayName":"Mentega Bergaram","malayPronunciation":"Mehn-teh-gah Behr-gah-rahm"},{"id":"pandan-kaya-jam","name":{"zh-TW":"天然香蘭手工咖椰醬 (Kaya)","en":"Handmade Pandan Coconut Egg Jam (Kaya)","ms":"Jem Kaya Pandan Tradisional","ja":"自家製パンダンカヤジャム","ko":"수제 판단 카야잼"},"amount":60,"unitMetric":"g","unitUS":"4 tbsp","isKeyFlavor":true,"malayName":"Jem Kaya Pandan","malayPronunciation":"Jehm Kah-yah Pahn-dahn"},{"id":"fresh-eggs-halfboiled","name":{"zh-TW":"超新鮮生雞蛋 (製作生熟蛋)","en":"Fresh Grade-A Eggs (for half-boiled eggs)","ms":"Telur Ayam Gred A Segar","ja":"新鮮な生卵（半熟卵用）","ko":"신선한 특란 (반숙란용)"},"amount":2,"unitMetric":"piece","unitUS":"2 eggs","isKeyFlavor":true,"malayName":"Telur Ayam","malayPronunciation":"Teh-loor Ah-yahm"},{"id":"dark-soy-and-white-pepper","name":{"zh-TW":"大馬老老抽黑醬油與砂拉越頂級純白胡椒粉","en":"Thick Caramel Dark Soy Sauce & Sarawak White Pepper","ms":"Kicap Pekat Manis & Serbuk Lada Putih Sarawak","ja":"マレーシア濃厚黒醤油＆サラワク産白胡椒","ko":"말레이시아 흑간장 & 사라왁 백후추"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","isKeyFlavor":true,"malayName":"Kicap & Lada Putih","malayPronunciation":"Kee-chahp dahn Lah-dah Poo-teeh"}],"steps":[{"stepNumber":1,"image":"/images/my/kaya-toast-step1.jpg","title":{"zh-TW":"精準沸水燜蒸完美 6 分鐘生熟蛋 (Telur Goyang)","en":"Boil & Rest 6 Minutes for Flawless Half-Boiled Eggs","ms":"Rendam Telur Dalam Air Mendidih Tepat 6 Minit","ja":"沸騰した湯の余熱で6分間！完璧な半熟温泉卵を作る","ko":"끓인 물에 불을 끄고 정확히 6분간 뜸 들여 반숙란 만들기"},"instruction":{"zh-TW":"小鍋中將 600ml 水完全燒至大滾，關火！立刻將 2 顆室溫雞蛋輕輕放入熱水中，蓋上鍋蓋，嚴格計時「燜蒸 6 分鐘」（切勿開火煮！）。時間一到立刻撈出衝涼水 5 秒阻斷餘溫。敲破蛋殼打入小瓷碗中——蛋白如絲絨豆花般半凝固，蛋黃金黃飽滿搖晃流心！","en":"Bring 600ml water to a rolling boil in small pot, then turn off heat completely! Immediately lower 2 room-temperature eggs into the water, cover tightly with lid, and time precisely 6 MINUTES without heat. Lift out and rinse with tap water 5 secs. Crack into a small ceramic saucer: silky, custardy egg whites with a gorgeous molten wobbly yolk!","ms":"Didihkan 600ml air hingga menggelegak, padamkan api. Masukkan 2 biji telur suhu bilik, tutup periuk dan biarkan terendam tepat 6 MINIT tanpa api. Angkat dan pecahkan ke dalam piring seramik.","ja":"小鍋で水600mlを沸騰させたら、火を完全に止めます！常温の卵2個を静かに入れ、蓋をして余熱で【正確に6分間】放置（火はつけない）。取り出して小皿に割り入れます。白身はフルプルの飲むカスタード状、黄身はとろとろの完璧な半熟卵が完成！","ko":"냄비에 물 600ml를 팔팔 끓인 뒤 불을 완전히 끕니다! 실온의 달걀 2개를 넣고 뚜껑을 덮어 불을 켜지 않은 채 【정확히 6분간】 그대로 둡니다. 꺼내서 작은 볼에 깨 넣으면 흰자는 푸딩처럼 부드럽고 노른자는 주르륵 흐르는 완벽한 반숙란이 됩니다."},"durationSeconds":360,"crucialTips":{"zh-TW":"雞蛋必須是「常溫蛋」！若是冷藏蛋請先泡溫水 5 分鐘回溫，否則放入沸水會因溫差裂殼且熟度不均。","en":"Eggs MUST be room temperature! If straight from the fridge, warm them in lukewarm water for 5 mins first to avoid cracked shells and cold yolks.","ms":"Gunakan telur pada suhu bilik. Jika dari peti sejuk, rendam dalam air suam seketika agar kulit tidak retak.","ja":"卵は必ず「常温」に戻して使ってください！冷蔵庫から出したてだと殻が割れたり火の通りが甘くなります。","ko":"반드시 \"실온 달걀\"을 사용하세요! 냉장고에서 바로 꺼낸 달걀은 깨지기 쉽고 속까지 고루 익지 않습니다."}},{"stepNumber":2,"image":"/images/my/kaya-toast-step2.jpg","title":{"zh-TW":"烤爐或氣炸鍋烘烤酥脆雙面吐司","en":"Toast Bread to Crisp, Golden Crackly Perfection","ms":"Bakar Roti Hingga Garing Keemasan Nipis","ja":"トースターまたはエアフライヤーでパンをカリカリに焼き上げる","ko":"토스터 또는 에어프라이어에 식빵을 바삭하게 굽기"},"instruction":{"zh-TW":"將薄切吐司切去四邊厚皮。放入烤箱、烤麵包機或氣炸鍋（180°C 烤 3-4 分鐘），烤至雙面金黃焦香、質地如同餅乾般薄脆清響，切成兩半。","en":"Trim crusts from thin white bread. Toast in toaster, oven broiler, or air fryer at 180°C (350°F) for 3-4 mins until both sides are pale golden, brittle and crackly like a wafer. Slice into halves.","ms":"Buang kerak tepi roti. Bakar dalam pembakar roti atau air fryer 180°C selama 3-4 minit sehingga kedua-dua belah garing rangup biskut.","ja":"食パンの耳を落とします。トースターまたはエアフライヤー（180℃で3〜4分）で、両面がサクサクとクラッカーのように香ばしくなるまでトーストし、半分にカットします。","ko":"식빵의 테두리를 잘라냅니다. 토스터기 또는 에어프라이어(180℃ 3-4분)에서 양면이 과자처럼 바삭바삭해질 때까지 구운 뒤 반으로 자릅니다."},"durationSeconds":240,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 180°C (350°F) for 3-4 mins","instructionOverride":{"zh-TW":"氣炸鍋模式：吐司平鋪炸籃 180°C 烤 3 分鐘，翻面再烤 1 分鐘，極致酥脆！","en":"Air Fryer: 180°C (350°F) for 3 mins, flip and toast 1 min for ultimate wafer crispness.","ms":"Air Fryer: 180°C selama 3 minit, balikkan dan bakar 1 minit lagi.","ja":"エアフライヤー：180℃で3分、裏返して1分。極薄パリパリの仕上がりに。","ko":"에어프라이어: 180℃에서 3분 조리 후, 뒤집어 1분 더 구워 바삭함을 극대화합니다."}}]},{"stepNumber":3,"image":"/images/my/kaya-toast-step3.jpg","title":{"zh-TW":"厚抹香蘭咖椰・夾入冰凍有鹽厚牛油 (冰火交融)","en":"Slather Pandan Kaya & Sandwich Chilled Salted Butter Slabs","ms":"Sapu Jem Kaya Tebal & Selit Mentega Sejuk Tebal Beku","ja":"カヤジャムを厚塗りし、冷たい厚切り有塩バターを挟む（氷火の融合）","ko":"카야잼을 듬뿍 바르고 차가운 가염 버터 조각을 샌드하기"},"instruction":{"zh-TW":"【關鍵精髓：牛油一定要厚且冰凍！】在熱烤吐司的一面厚厚抹上一層芳香翠綠的香蘭咖椰醬（Kaya）。從冰箱取出剛切好的「厚切冷藏有鹽牛油片」（約 0.5 公分厚），直接鋪在咖椰上，隨即蓋上另一片熱吐司。熱麵包的酥脆、溫熱甜蜜的椰香咖椰，與冷冽鹹香的固體厚牛油在口中交融，形成無法言喻的「冰火神級反差」！","en":"[The Golden Rule: Butter MUST be cold and thick!] Generously slather warm crispy toast with velvety pandan Kaya jam. Retrieve thick (0.5cm) cold salted butter slabs straight from the fridge, lay them over the kaya, and cap immediately with top toast. The hot crackly toast, sweet fragrant coconut egg jam, and freezing cold savory butter melt together in an unearthly sensation of heat and ice!","ms":"Sapu jem kaya tebal pada sekeping roti bakar panas. Letakkan kepingan mentega bergaram sejuk beku tebal (0.5cm) di atas kaya, dan tangkupkan sekeping lagi roti. Kontras sejuk mentega dan panas roti menghasilkan rasa luar biasa!","ja":"【最大の秘訣：バターは必ず厚切り＆冷えたてを使うこと！】熱々のトーストにパンダンカヤジャムをたっぷり塗ります。冷蔵庫から出したての冷たい厚切り有塩バター（約5mm厚）を豪快に乗せ、もう一枚のパンで挟みます。熱々のサクサクパン、甘いジャム、そしてひんやり塩気のあるバターが口の中で溶け合う「温冷コントラスト」が昇天ものの美味さ！","ko":"【가장 중요한 비법: 버터는 반드시 차갑고 두툼해야 합니다!】구운 뜨거운 빵 위에 수제 카야잼을 듬뿍 바릅니다. 냉장고에서 바로 꺼낸 차가운 가염 버터(두께 약 0.5cm)를 올리고 다른 빵으로 덮습니다. 뜨겁고 바삭한 빵과 달콤한 카야잼, 차갑고 짭조름한 버터가 입안에서 녹아내리며 천상의 맛을 선사합니다!"},"durationSeconds":120},{"stepNumber":4,"image":"/images/my/kaya-toast-step4.jpg","title":{"zh-TW":"生熟蛋淋黑老抽白胡椒・吐司沾蛋開動","en":"Season Eggs with Dark Soy & Pepper, Dip Toast & Slurp","ms":"Renjis Kicap Pekat & Lada Putih, Cicah Roti Bakar","ja":"半熟卵に黒醤油と白胡椒を垂らし、トーストを浸して食べる","ko":"반숙란에 흑간장과 백후추를 뿌리고 토스트를 찍어 먹기"},"instruction":{"zh-TW":"在打好的生熟蛋碗中，淋入 1 茶匙濃甜黑老抽、撒上兩抖砂拉越白胡椒粉。用湯匙輕輕攪拌成如絲絨般的大理石紋蛋液。拿起一塊咖椰牛油烤吐司，直接浸入溫熱流心的黑醬油蛋液中沾滿，大口咬下！接著把剩餘的蛋液當作熱布丁呼嚕喝光，再配上一口濃熱南洋咖啡，大馬早晨圓滿無憾！","en":"Drizzle 1 tsp thick caramel dark soy sauce and two generous shakes of white pepper over the half-boiled eggs. Whisk gently into a marbled savory custard. Dip a crispy corner of kaya butter toast deep into the runny seasoned yolk, take a massive bite, and slurp the rest of the eggs from the dish like warm silk. Wash down with Kopitiam hot Kopi!","ms":"Renjiskan kicap pekat karamel dan serbuk lada putih ke atas telur goyang. Kacau perlahan. Cicah roti bakar kaya butter ke dalam telur separuh masak dan hirup saki-baki telur hingga licin!","ja":"半熟卵の器に、濃厚黒醤油小さじ1と白胡椒を2振り。スプーンで軽く混ぜてマーブル模様にします。カヤバタートーストをこの濃厚な卵液にたっぷりディップしてガブリ！残った卵液はそのままズズッと飲み干し、熱いコピ（コーヒー）を一口すするのが伝統スタイル。","ko":"반숙란 볼에 달콤한 흑간장 1작은술과 백후추를 톡톡 뿌려 가볍게 섞습니다. 카야 버터 토스트를 노른자 소스에 푹 찍어 한 입 베어 물고, 남은 달걀을 호로록 마신 뒤 따뜻한 코피 한 모금을 곁들이면 완벽한 아침이 완성됩니다!"},"durationSeconds":60}],"troubleshooting":[{"id":"butter-melted-too-fast","problem":{"zh-TW":"牛油在端上桌前就全部化成黃油水流出","en":"Butter melted into grease puddle before reaching the table","ms":"Mentega cair meleleh sebelum sempat dimakan","ja":"テーブルに出す前にバターが完全に溶けて流れてしまった","ko":"버터가 테이블에 내기도 전에 녹아 기름처럼 흘러내림"},"cause":{"zh-TW":"牛油切得太薄、或者使用了常溫軟化的牛油","en":"Butter sliced too paper-thin or left at room temperature before assembling","ms":"Mentega dipotong terlalu nipis atau dibiarkan pada suhu bilik","ja":"バターが薄すぎる、または常温で柔らかくなったバターを使った","ko":"버터를 너무 얇게 썰었거나 실온에 두어 녹은 버터를 사용함"},"solution":{"zh-TW":"牛油必須切成 0.5 公分厚的「冰塊磚片」，組裝前一直保存在冰箱最冷處，夾入後 1 分鐘內立刻享用！","en":"Cut butter into thick 0.5cm slabs and keep in freezer/fridge until the exact second of assembly!","ms":"Potong mentega tebal 0.5cm dan simpan dalam peti sejuk sehingga saat akhir sebelum dihidang.","ja":"バターは必ず5mm以上の厚さに切り、挟む直前まで冷蔵庫（または冷凍庫）でキンキンに冷やしておきます。","ko":"버터는 두께 0.5cm 이상 두툼하게 썰어 샌드하기 직전까지 냉장고에 차갑게 보관하세요."}}],"proTips":[{"zh-TW":"老饕靈魂吃法「浸蛋沾汁」：很多第一次吃南洋早餐的外國人不敢把甜吐司沾進生熟蛋裡，但這正是南洋最偉大的發明！微鹹的黑醬油蛋液包裹住甜蜜的咖椰與冰牛油，甜鹹交織、絲滑爆汁，吃過一次終生難忘！","en":"The Kopitiam Revelation: Skeptics may hesitate to dip sweet toast into runny eggs, but this sweet-savory synergy is Southeast Asia’s greatest morning miracle. The umami-laden peppered yolk cuts the sweetness and elevates the butter to unimaginable heights!","ms":"Keajaiban Kopitiam: Jangan ragu-ragu untuk mencicah roti bakar manis ke dalam telur separuh masak kicap lada! Gabungan manis kaya, lemak mentega dan masin telur menghasilkan rasa harmoni yang tiada tandingan.","ja":"コピティアムの奇跡：甘いトーストを胡椒醤油の半熟卵につけるのに抵抗があるかもしれませんが、これぞ東南アジアが誇る至極の食文化！卵のコクがジャムの甘みを引き締め、信じられないほど美味になります。","ko":"코피티암의 기적: 달콤한 카야 토스트를 짭조름한 반숙란에 찍어 먹는 것이야말로 남양 조식의 진수입니다! 흑간장 노른자가 단맛을 부드럽게 감싸며 폭발적인 풍미를 만듭니다."}]},{"country":"my","id":"cendol-melaka","slug":"cendol-melaka","title":{"zh-TW":"馬六甲古法純椰糖煎蕊刨冰 (晶露)","en":"Melaka Pure Gula Melaka Cendol Shaved Ice","ms":"Cendol Gula Melaka Asli Santan Sawit Melaka","ja":"マラッカ名物・純黒糖チェンドルかき氷（生ココナッツミルク＆パンダンゼリー）","ko":"말라카 순수 흑당 첸돌 빙수 (생코코넛 밀크 & 판단 젤리 누들)"},"subtitle":{"zh-TW":"翠綠天然斑蘭粉條・純手工煙燻馬六甲椰糖・鮮榨濃郁椰漿・慢熬紅豆","en":"Pandan Green Jelly Noodles, Smoky Wood-Fired Gula Melaka & Fresh Coconut Cream","ms":"Cendol Hijau Pandan Asli, Gula Melaka Berkaramel Pekat & Santan Segar Berkrim","ja":"翡翠色の天然パンダンゼリー麺、薪火で煮詰めたマラッカ純黒糖、絞りたてココナッツミルクと小豆","ko":"천연 판단 초록 젤리 국수, 스모키한 전통 야자 흑당, 신선한 코코넛 밀크와 통단팥"},"tagline":{"zh-TW":"CNN 評選全球 50 大甜品之一！南洋赤道酷暑下最銷魂的透心涼救贖","en":"Named one of the World’s 50 Best Desserts by CNN! The ultimate equatorial thirst-quencher","ms":"Tersohor sebagai antara 50 Pencuci Mulut Terbaik Dunia oleh CNN! Penyejuk tekak tropika terunggul","ja":"CNN世界50大デザート選出！熱帯のうだるような暑さを一瞬で吹き飛ばす極上スイーツ","ko":"CNN 선정 세계 50대 디저트! 적도의 무더위를 한순간에 씻어주는 궁극의 빙수"},"heroImage":"/images/my/cendol-melaka.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":320,"category":"desserts","dietaryTags":["classic","vegetarian","vegan","halal","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"南馬・馬六甲古城 (Melaka)","en":"Historic City of Melaka","ms":"Bandar Warisan Melaka","ja":"南マレーシア・歴史都市マラッカ","ko":"말레이시아 남부 / 역사 도시 말라카"},"famousStreetMarkets":[{"zh-TW":"馬六甲雞場街大寶小食 (Jonker 88 Cendol)","en":"Jonker 88 (Famous Cendol), Jonker Walk, Melaka","ms":"Jonker 88 Melaka","ja":"ジョンカー88（名物チェンドル）","ko":"존커 88 (유명 첸돌 전문점)"},{"zh-TW":"檳城潮州煎蕊老店 (景貴街)","en":"Penang Road Famous Teochew Chendul (Keng Kwee St)","ms":"Penang Road Teochew Chendul","ja":"ペナン・潮州チェンドル（景貴街）","ko":"페낭 로드 유명 조주 첸돌"}],"historyStory":{"zh-TW":"相傳發源於馬六甲海峽繁華港口。赤道烈日下，港口苦力與旅人需要消暑聖品。主婦將綠豆粉與鮮榨斑蘭葉汁混合煮成米糊，用底部有孔洞的濾篩壓擠入冰水中，冷卻成一條條形似小青蟲的碧綠粉條（Cendol，印尼/馬來語原意為「凸起/小條狀物」）。鋪在細密碎冰上，淋上馬六甲特產的柴火純椰糖漿（Gula Melaka）與初榨鮮椰奶，甜、香、滑、涼，驚艷世界。","en":"Flourished in the bustling maritime port of Melaka. To combat tropical heat, cooks pressed cooked mung bean and pandan batter through a perforated sieve into ice water, creating worm-like emerald green jelly droplets (called \"Cendol\", meaning swollen/droplet). Layered over finely shaved ice, doused with smoky, caramel-rich wood-fired Gula Melaka syrup and fresh coconut cream.","ms":"Bermula di pelabuhan bersejarah Selat Melaka. Adunan tepung beras/kacang hijau dan jus pandan ditekan melalui acuan berlubang ke dalam air ais menjadi titisan cendol hijau. Dihidang atas ais kepal bersama sirap gula Melaka pekat dan santan segar.","ja":"マラッカ海峡の貿易港で誕生。緑豆粉と生のパンダン果汁を練り上げ、穴あき器から氷水に押し出して緑色の小粒ゼリー麺（チェンドル）を作ります。ふわふわのかき氷の上に盛り付け、薪火で煮詰めたマラッカ特産の純パームシュガーと濃厚ココナッツミルクをかけて味わう伝統氷菓。","ko":"말라카 해협의 무역항에서 발전한 전통 디저트입니다. 녹두 녹말과 신선한 판단 즙을 끓인 반죽을 구멍 뚫린 틀로 얼음물에 눌러 짜내어 초록색 올챙이 국수(첸돌)를 만듭니다. 고운 얼음 위에 얹고 스모키한 야자 흑당과 생코코넛 밀크를 부어 먹습니다."},"malayScript":"Cendol Gula Melaka","malayPhonetics":"Chehn-dohl Goo-lah Meh-lah-kah","audioPronunciationText":"Boss, Cendol Gula Melaka mangkuk besar satu, santan lebih, kacang merah taruk banyak!","communityHeritage":"Peranakan","nativeName":"Cendol Gula Melaka","nativePhonetics":"Cendol Gula Melaka"},"ingredients":[{"id":"cendol-jelly-noodles","name":{"zh-TW":"天然香蘭斑蘭煎蕊粉條 (Cendol)","en":"Fresh Pandan Cendol Green Jelly Noodles","ms":"Cendol Hijau Pandan Segar","ja":"生パンダンチェンドルゼリー（緑のゼリー麺）","ko":"신선한 판단 첸돌 그린 젤리 누들"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"malayName":"Cendol Segar","malayPronunciation":"Chehn-dohl Seh-gahr"},{"id":"pure-gula-melaka-syrup","name":{"zh-TW":"馬六甲純手工椰糖漿 (柴火慢熬濃縮)","en":"Pure Thick Gula Melaka Syrup (Smoky Palm Sugar)","ms":"Sirap Gula Melaka Pekat Wangi","ja":"マラッカ産純パームシュガー黒蜜（スモーキーなコク）","ko":"말라카 순수 야자 흑당 시럽 (스모키한 풍미)"},"amount":60,"unitMetric":"ml","unitUS":"4 tbsp","isKeyFlavor":true,"malayName":"Sirap Gula Melaka","malayPronunciation":"See-rahp Goo-lah Meh-lah-kah"},{"id":"fresh-coconut-milk-cendol","name":{"zh-TW":"鮮榨純濃冷藏椰漿 (加微量鹽激發甜度)","en":"Chilled Pure Fresh Coconut Milk (with a tiny pinch of salt)","ms":"Pati Santan Segar Sejuk (Secubit Garam)","ja":"冷たい生搾りココナッツミルク（塩ひとつまみ入り）","ko":"차갑게 보관한 신선한 코코넛 밀크 (소금 한 꼬집)"},"amount":120,"unitMetric":"ml","unitUS":"4 fl oz","isKeyFlavor":true,"malayName":"Pati Santan Sejuk","malayPronunciation":"Pah-tee Sahn-tahn Seh-jook"},{"id":"sweet-red-beans-cendol","name":{"zh-TW":"慢火蜜煮大紅豆 (軟爛綿密)","en":"Sweet Stewed Red Kidney Beans (Soft & tender)","ms":"Kacang Merah Rebus Manis","ja":"じっくり煮込んだ大粒甘煮小豆","ko":"부드럽게 졸인 달콤한 통단팥"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":false,"malayName":"Kacang Merah","malayPronunciation":"Kah-chahng Meh-rah"},{"id":"fine-shaved-ice","name":{"zh-TW":"細密綿花碎冰 (刨冰)","en":"Finely Shaved Ice (Snow Ice consistency)","ms":"Ais Mesin Halus / Ais Kepal","ja":"ふわふわ微細かき氷","ko":"곱게 간 눈꽃 얼음"},"amount":300,"unitMetric":"g","unitUS":"2 big bowls","isKeyFlavor":false,"malayName":"Ais Kisar Halus","malayPronunciation":"Ah-yees Kee-sahr Hah-loos"}],"steps":[{"stepNumber":1,"image":"/images/my/cendol-melaka-step1.jpg","title":{"zh-TW":"古法慢熬濃稠馬六甲椰糖蜜","en":"Simmer Smoky Gula Melaka into Glossy Amber Syrup","ms":"Masak Gula Melaka & Daun Pandan Menjadi Sirap Pekat","ja":"パームシュガーとパンダンを煮詰めて濃厚な黒蜜を作る","ko":"야자 흑당과 판단잎을 끓여 짙은 흑당 시럽 만들기"},"instruction":{"zh-TW":"小鍋中放入 100g 碎馬六甲純椰糖、50ml 清水與 1 根打結的香蘭葉。開微火慢煮約 8 分鐘，輕輕攪拌直至椰糖完全融化，起稠密細泡，散發濃烈的煙燻焦糖芳香。離火放涼，糖蜜會自然轉為如楓糖漿般濃稠有光澤。","en":"In small saucepan, combine 100g shaved pure Gula Melaka, 50ml water and 1 knotted pandan leaf. Simmer gently over low heat for 8 mins until sugar dissolves into a glossy, bubbling, molasses-thick syrup packed with smoky butterscotch notes. Discard leaf and cool completely.","ms":"Campurkan 100g gula Melaka hiris, 50ml air dan sehelai daun pandan simpul. Masak api kecil 8 minit hingga gula larut dan pekat berbuih wangi karamel. Sejukkan.","ja":"小鍋に刻んだパームシュガー100g、水50ml、パンダンリーフ1枚を入れ弱火で8分加熱。完全に溶けて細かい泡が立ち、スモーキーなキャラメルの香りが立ったら火を止め冷まします。冷めるととろみが増します。","ko":"작은 냄비에 흑당 100g, 물 50ml, 판단잎 1장을 넣고 약불에서 8분간 졸입니다. 완전히 녹아 캐러멜 향의 진한 시럽이 되면 불을 끄고 식혀둡니다."},"durationSeconds":480},{"stepNumber":2,"image":"/images/my/cendol-melaka-step2.jpg","title":{"zh-TW":"堆疊雪白細密刨冰山","en":"Mound Finely Shaved Ice Mountain in Vintage Bowls","ms":"Kisar Ais Halus Membentuk Gunung Dalam Mangkuk","ja":"器にふわふわの微細氷を山盛りに盛る","ko":"그릇에 고운 눈꽃 얼음을 산처럼 소복하게 담기"},"instruction":{"zh-TW":"使用刨冰機將純淨冰塊刨成如初雪般細密柔軟的綿綿碎冰，大方地在兩個復古玻璃碗或瓷碗中堆起一座高聳的冰山，用手掌輕輕拍實頂部。","en":"Using a shaved ice machine, shave pure ice into a cloud of snowy, micro-fine powder. Mound generously into two chilled vintage bowls or highball glasses, patting gently with palm into a neat dome.","ms":"Kisar ais sehingga halus bak salji gebu. Sendukkan ke dalam mangkuk membentuk kubah ais yang kemas.","ja":"かき氷機で氷を削り、パウダースノーのようなふわふわの氷を器にこんもりと山型に盛り付けます。","ko":"빙수기로 얼음을 갈아 눈처럼 부드러운 빙수를 그릇에 둥근 돔 모양으로 소복하게 담습니다."},"durationSeconds":120},{"stepNumber":3,"image":"/images/my/cendol-melaka-step3.jpg","title":{"zh-TW":"鋪上斑蘭煎蕊粉條與綿密紅豆","en":"Crown with Emerald Pandan Jelly Noodles & Soft Red Beans","ms":"Taburkan Cendol Hijau Pandan & Kacang Merah Manis","ja":"翡翠色のパンダンゼリーと甘煮小豆をトッピングする","ko":"초록빛 판단 젤리 국수와 달콤한 통단팥 올리기"},"instruction":{"zh-TW":"在潔白冰山周圍與頂部，鋪上晶瑩碧綠、帶有淡淡草本清香的香蘭煎蕊粉條（Cendol），以及 2 大勺慢燉至鬆化起沙的甜紅豆粒。綠紅相映，色澤無比誘人！","en":"Spoon a generous cascade of emerald pandan cendol jelly noodles around and atop the snowy ice dome. Flank with two big scoops of sweet, creamy stewed red kidney beans. The visual contrast of jade green, ruby red and snowy white is breathtaking!","ms":"Susun cendol hijau pandan wangi di sekeliling dan atas gunung ais. Letakkan dua sudu besar kacang merah empuk manis di tepi.","ja":"氷山の周りに鮮やかな翡翠色のチェンドルゼリー麺をたっぷり散らし、甘く煮た小豆を添えます。緑、赤、白のコントラストが南国の涼を演出します！","ko":"얼음 돔 위에 산뜻한 초록빛 판단 첸돌 젤리 누들과 부드럽게 삶은 통단팥을 듬뿍 둘러 올립니다."},"durationSeconds":60},{"stepNumber":4,"image":"/images/my/cendol-melaka-step4.jpg","title":{"zh-TW":"澆淋微鹹純椰漿與濃黑馬六甲椰糖蜜","en":"Drizzle Salted Coconut Milk & Cascading Smoky Gula Melaka","ms":"Siram Santan Berlemak & Curah Sirap Gula Melaka Mengalir","ja":"ほんのり塩気のココナッツミルクと黒蜜を滝のように回しかけて完成","ko":"소금을 살짝 탄 코코넛 밀크와 진한 흑당 시럽을 흘러내리듯 부어 완성"},"instruction":{"zh-TW":"在鮮榨冷藏純椰漿中加入 1/8 茶匙海鹽攪勻（微鹹是引出椰子醇甜的靈魂！），均勻淋在冰山頂端。最後將濃黑發亮的馬六甲純椰糖漿，如瀑布般淋下！拿長匙從底部往上輕輕翻拌，碎冰、椰奶、煙燻焦糖與滑溜彈牙的斑蘭條融合在舌尖，透心冰爽！","en":"Whisk a pinch of sea salt into chilled coconut milk (the salt is the secret key that catapults the coconut richness to celestial heights!), and ladle over the peak. Finally, drizzle dark smoky Gula Melaka syrup in a dramatic cascading ribbon! Dig a long spoon to bottom, lift and slurp: icy cold, salty-sweet coconut cream, smoky butterscotch, and slippery jade noodles!","ms":"Kacau secubit garam ke dalam santan segar dan curahkan ke atas ais. Akhir sekali, tuang sirap gula Melaka likat bak air terjun keemasan. Gaul sebati dan nikmati kesegaran tropika yang menyejukkan tekak!","ja":"塩ひとつまみを混ぜた冷たいココナッツミルクを回しかけます（塩気がココナッツの甘みを何倍にも引き立てます！）。最後に濃厚な黒蜜を滝のように垂らして完成！スプーンでザクザク崩しながら、極上の冷たさと深いコクを味わいます。","ko":"소금 한 꼬집을 탄 시원한 코코넛 밀크를 빙수 위에 붓습니다 (약간의 소금이 코코넛의 단맛을 극대화합니다!). 마지막으로 진한 흑당 시럽을 폭포처럼 둘러 완성합니다. 바닥부터 숟가락으로 섞어 시원하게 떠드세요!"},"durationSeconds":45}],"troubleshooting":[{"id":"cendol-hard","problem":{"zh-TW":"煎蕊綠粉條碰到冰塊後變得硬邦邦不滑溜","en":"Cendol jelly noodles turn hard and rubbery upon touching ice","ms":"Cendol menjadi keras liat bila terkena ais","ja":"氷に触れたチェンドルが固くなって食感が悪い","ko":"얼음에 닿은 첸돌 젤리가 딱딱하게 굳어 식감이 나빠짐"},"cause":{"zh-TW":"使用了過多普通粘米粉而缺少綠豆粉/澄粉，澱粉在低溫下急速老化回生","en":"Used too much rice flour without green bean/mung bean starch, retrograding in cold temp","ms":"Guna tepung beras berlebihan tanpa tepung kacang hijau/ubi","ja":"米粉の比率が高すぎ、低温でデンプンが老化（硬化）した","ko":"멥쌀가루 비율이 너무 높아 저온에서 전분이 딱딱하게 노화됨"},"solution":{"zh-TW":"製作煎蕊粉條務必以「綠豆粉 (Hoon Kwe Flour) 或澄粉」為主體，能在冰水中始終維持驚人的滑嫩彈性！","en":"Must formulate batter with Mung Bean Starch (Hoon Kwe), which retains super-soft slippery texture even in ice!","ms":"Gunakan tepung kacang hijau (Hoon Kwe) yang kekal lembut licin dalam ais sejuk.","ja":"必ず「緑豆粉（ホングエ粉）」をベースに作ってください。氷水の中でも硬くならず、ちゅるんとした食感が持続します。","ko":"반드시 \"녹두 전분(훈퀘 가루)\"을 주원료로 만들어야 얼음 속에서도 끝까지 부드럽고 쫄깃한 식감이 유지됩니다."}}],"proTips":[{"zh-TW":"大馬老茶室不可不知的秘訣——「那一撮海鹽」：在椰漿裡加入極微量的一撮海鹽，是讓整碗 Cendol 從平庸糖水躍升為國寶甜點的最神奇魔法！微鹹能瞬間激活椰奶的乳脂香氣，並與深沉的煙燻黑糖產生極致高雅的甜鹹對位！","en":"The Kopitiam Secret Ingredient: The pinch of sea salt in the coconut milk is the ultimate alchemy! It cuts right through the cloying sweetness, awakening the plant fats in coconut cream and turning the smoky Gula Melaka into a sublime salted-caramel symphony.","ms":"Rahsia Teragung Kopitiam: Secubit garam dalam santan adalah magis sebenar! Garam membangkitkan lemak santan dan mengimbangi kemanisan gula Melaka persis karamel bergaram bertaraf dunia.","ja":"大師直伝の秘密「ひとつまみの塩」：ココナッツミルクにほんの少しの海塩を加えるのが、大馬チェンドル最大の魔法！塩気がくどさを消し、パームシュガーの深い甘みを塩キャラメルのような至高のハーモニーへと昇華させます。","ko":"코피티암 장인의 특급 비법 \"소금 한 꼬집\": 코코넛 밀크에 넣는 약간의 소금이야말로 첸돌의 신의 한 수입니다! 소금이 코코넛의 느끼함을 지우고 야자 흑당과 만나 고급스러운 솔티드 캐러멜 같은 조화를 완성합니다."}]},{"country":"my","id":"kuih-dadar","slug":"kuih-dadar","title":{"zh-TW":"娘惹香蘭椰絲班蘭卷 (香煎椰絲卷)","en":"Nyonya Pandan Coconut Crepe Rolls (Kuih Dadar / Ketayap)","ms":"Kuih Dadar / Ketayap Inti Kelapa Gula Melaka","ja":"クエ・ダダール（娘惹風・パンダンクレープの黒糖ココナッツロール）","ko":"퀴에 다다르 / 끄타얍 (판단 코코넛 크레이프 롤)"},"subtitle":{"zh-TW":"天然翡翠斑蘭薄煎皮・馬六甲純椰糖慢煨多汁椰絲餡・入口爆漿椰香芬芳","en":"Emerald Pandan Crepe Skin Stuffed with Juicy Gula Melaka Grated Coconut","ms":"Kulit Crepe Hijau Pandan Lembut Diisi Kelapa Parut Gula Melaka Lembap Berjus","ja":"天然パンダンの翡翠色モチモチ生地、パームシュガーで煮詰めたジューシーなココナッツ餡","ko":"천연 판단 즙으로 부쳐낸 쫄깃한 초록 크레이프와 흑당에 졸인 촉촉한 코코넛 소"},"tagline":{"zh-TW":"娘惹糕點皇冠上的碧玉翡翠！咬下瞬間滿口爆出椰糖香甜肉汁","en":"The emerald jewel in the Peranakan Kuih crown—gushing with caramelized coconut nectar in every bite","ms":"Permata hijau zamrud dalam alam kuih-muih tradisional Nyonya yang manis memikat","ja":"ニョニャ伝統菓子の代表格！噛んだ瞬間にジューシーな黒糖ココナッツ果汁が溢れ出す逸品","ko":"페라나칸 전통 떡의 에메랄드 보석! 한 입 베어 무는 순간 달콤한 코코넛 시럽이 촉촉하게 배어납니다"},"heroImage":"/images/my/kuih-dadar.jpg","difficulty":"easy","prepTimeMinutes":25,"cookTimeMinutes":20,"defaultServings":4,"caloriesPerServing":240,"category":"desserts","dietaryTags":["classic","vegetarian","vegan","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"馬六甲與檳城・海峽娘惹家族 (Peranakan Nyonya Heritage)","en":"Melaka & Penang / Peranakan Nyonya Heritage","ms":"Melaka & Pulau Pinang / Warisan Baba Nyonya","ja":"マラッカおよびペナン・ババ・ニョニャ文化","ko":"말라카 & 페낭 페라나칸 뇨냐 전통"},"famousStreetMarkets":[{"zh-TW":"馬六甲小娘惹傳統糕點","en":"Baba Charlie Nyonya Kuih, Melaka","ms":"Baba Charlie Nyonya Kuih Melaka","ja":"ババ・チャーリー・ニョニャ菓子（マラッカ）","ko":"바바 찰리 뇨냐 퀴에 (말라카)"},{"zh-TW":"檳城七條路巴剎娘惹糕攤","en":"Cecil Street Market Nyonya Kuih, Penang","ms":"Pasar Cecil Street Penang","ja":"セシル・ストリート市場","ko":"세실 스트리트 시장"}],"historyStory":{"zh-TW":"馬來西亞與海峽娘惹（Peranakan）家族最引以為傲的午後茶點。在馬來語中又名「Kuih Ketayap」或「Kuih Gulung」（卷餅）。娘惹女性採集自家花園種植的翠綠香蘭葉，以石臼搗出濃綠芬芳的天然香草汁，加入麵粉、椰漿調成翡翠色粉漿在平底熱鑊中攤成蕾絲薄皮。內餡選用新刨嫩椰絲，與柴火慢熬的馬六甲純椰糖（Gula Melaka）翻炒至深褐透亮、濕潤多汁，緊緊捲起如綠玉春卷，甜而不膩。","en":"The darling afternoon treat of Straits Peranakan households, also known as \"Kuih Ketayap\" or \"Kuih Gulung\". Nyonya ladies pounded fresh garden pandan leaves into vibrant emerald juice to perfume thin, mottled green crepes. The filling features freshly grated coconut simmered in melting Gula Melaka until glossy, moist and intoxicatingly sweet, rolled into neat jade parcels.","ms":"Kuih minum petang tradisional masyarakat Melayu dan Baba Nyonya. Dikenali juga sebagai Kuih Ketayap atau Kuih Gulung. Menggunakan jus daun pandan asli untuk warna hijau semula jadi dan diisi kelapa parut manis gula Melaka.","ja":"海峡植民地時代のニョニャ家庭で受け継がれる伝統菓子。「クエ・クタイヤップ」や「クエ・グルン（巻き菓子）」とも呼ばれます。庭先の生パンダンリーフを絞った天然の翡翠色クレープに、削りたてのココナッツをマラッカ黒糖で甘く煮詰めたジューシーな餡を巻き込みます。","ko":"해협 식민지 시절 페라나칸 가문에서 즐겨먹던 대표적인 티타임 디저트입니다. \"퀴에 끄타얍\"이라고도 불리며, 천연 판단 즙으로 반죽한 얇고 쫄깃한 초록색 크레이프에 야자 흑당으로 졸인 촉촉한 코코넛 소를 넣어 돌돌 말아냅니다."},"malayScript":"Kuih Dadar Gulung","malayPhonetics":"Koo-eeh Dah-dahr Goo-loong","audioPronunciationText":"Amoi, Kuih Dadar lima biji, bungkus bawa balik!","communityHeritage":"Peranakan","nativeName":"Kuih Dadar Gulung","nativePhonetics":"Kuih Dadar Gulung"},"ingredients":[{"id":"fresh-pandan-juice-dadar","name":{"zh-TW":"新鮮香蘭葉萃取濃汁 (6片打碎過濾)","en":"Fresh Pandan Leaf Juice (6 leaves blended with water & strained)","ms":"Air Ekstrak Daun Pandan Asli","ja":"生パンダンリーフの濃厚絞り汁（6枚を粉砕・濾したもの）","ko":"신선한 판단잎 착즙 원액 (6장을 갈아 체에 거른 것)"},"amount":120,"unitMetric":"ml","unitUS":"4 fl oz","isKeyFlavor":true,"malayName":"Air Daun Pandan","malayPronunciation":"Ah-yeer Dah-oon Pahn-dahn"},{"id":"crepe-flour-mix","name":{"zh-TW":"中筋麵粉 + 樹薯木薯粉 (增加彈韌不易破)","en":"All-Purpose Flour + Tapioca Starch (for elastic chew)","ms":"Tepung Gandum & Tepung Ubi Kayu","ja":"中力粉＋タピオカ澱粉（モチモチ食感と破れ防止）","ko":"중력분 + 타피오카 전분 (쫄깃하고 찢어지지 않는 반죽)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":false,"malayName":"Tepung Campur","malayPronunciation":"Teh-poong Chahm-poor"},{"id":"coconut-milk-crepe-dadar","name":{"zh-TW":"濃椰漿與清水各半","en":"Coconut Milk & Water (1:1 ratio)","ms":"Santan Kelapa Cair","ja":"ココナッツミルクと水のブレンド","ko":"코코넛 밀크와 물 (1:1)"},"amount":180,"unitMetric":"ml","unitUS":"6 fl oz","isKeyFlavor":false,"malayName":"Santan Cair","malayPronunciation":"Sahn-tahn Chah-eer"},{"id":"fresh-grated-coconut","name":{"zh-TW":"新鮮刨絲白嫩椰肉 (勿帶黑硬內殼皮)","en":"Freshly Grated White Coconut Flesh (skin-free)","ms":"Kelapa Parut Putih Segar","ja":"削りたて生ココナッツ果肉（黒い皮を取り除いた白い部分）","ko":"신선하게 간 흰 코코넛 과육 (갈색 껍질 제외)"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"malayName":"Kelapa Parut Putih","malayPronunciation":"Keh-lah-pah Pah-root Poo-teeh"},{"id":"gula-melaka-filling","name":{"zh-TW":"馬六甲純椰糖 (切細碎) 與香蘭葉","en":"Pure Gula Melaka (Finely chopped) & Knotted Pandan","ms":"Gula Melaka Asli & Daun Pandan","ja":"マラッカ産純パームシュガー＆パンダンリーフ","ko":"말라카 순수 야자 흑당 (잘게 썬 것) & 판단잎"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"malayName":"Gula Melaka Inti","malayPronunciation":"Goo-lah Meh-lah-kah Een-tee"}],"steps":[{"stepNumber":1,"image":"/images/my/kuih-dadar-step1.jpg","title":{"zh-TW":"慢火翻炒黑金多汁椰糖椰絲餡 (Inti Kelapa)","en":"Cook Moist, Caramelized Gula Melaka Coconut Filling (Inti)","ms":"Masak Inti Kelapa Gula Melaka Berkaramel Lembap","ja":"黒糖とココナッツを弱火で煮詰め、ジューシーな餡を作る","ko":"약불에서 흑당과 코코넛을 볶아 촉촉한 코코넛 소 만들기"},"instruction":{"zh-TW":"平底鍋中放入 120g 切碎馬六甲椰糖、50ml 清水與 1 根打結香蘭葉。小火煮至椰糖完全融化成濃郁焦糖漿。倒入 200g 新鮮刨白椰絲與 1/4 茶匙鹽。中小火不停翻炒約 8-10 分鐘，讓椰絲完全吸飽深黑糖漿，保持濕潤多汁、表面油亮閃爍（切勿炒乾！）。離火放涼備用。","en":"In pan, dissolve 120g chopped Gula Melaka in 50ml water with knotted pandan leaf over low heat into bubbling amber syrup. Fold in 200g grated fresh coconut and 1/4 tsp salt. Stir-fry gently over medium-low for 8-10 mins until coconut shreds absorb the glossy dark caramel while staying gorgeously moist and juicy. Do not dry out! Cool.","ms":"Cairkan 120g gula Melaka hiris bersama 50ml air dan daun pandan atas api kecil. Masukkan 200g kelapa parut putih dan secubit garam. Kacau rata 8-10 minit sehingga kelapa berkilat gelap dan lembap berjus. Sejukkan.","ja":"小鍋にパームシュガー120g、水50ml、パンダン1枚を入れ弱火で溶かして黒蜜を作ります。削りココナッツ200gと塩ひとつまみを加え、中弱火で8〜10分炒め煮にします。ココナッツが黒蜜を吸って艶やかでしっとりジューシーな状態を保ちます（炒めすぎによる乾燥に注意！）。冷まします。","ko":"팬에 흑당 120g, 물 50ml, 판단잎을 넣고 약불에서 녹여 시럽을 만듭니다. 신선한 코코넛 가루 200g과 소금 약간을 넣고 8-10분간 중약불에서 볶아 흑당 시럽이 촉촉하게 배어들도록 졸입니다 (너무 바짝 볶지 마세요!). 식혀둡니다."},"durationSeconds":600,"crucialTips":{"zh-TW":"椰絲餡一定要保持「濕潤爆漿感（Moist & Juicy）」！若水分炒得太乾，捲起來吃時口感會如同嚼乾草渣。","en":"The filling must stay glossy and moist! If overcooked until dry, it loses its sensational burst of coconut nectar upon biting.","ms":"Pastikan inti kelapa kekal lembap dan berkilat. Jangan masak terlalu kering agar kuah manisnya meletup dalam mulut!","ja":"餡は必ず「しっとりジューシー」に仕上げること！水分を飛ばしすぎるとパサついて口当たりが悪くなります。","ko":"코코넛 소는 반드시 촉촉하고 윤기가 흐르는 상태여야 합니다! 너무 졸여서 수분이 마르면 씹을 때 퍽퍽해집니다."}},{"stepNumber":2,"image":"/images/my/kuih-dadar-step2.jpg","title":{"zh-TW":"調製天然碧玉香蘭粉漿","en":"Whisk Silky Emerald Pandan Batter & Strain","ms":"Bancuh Adunan Tepung Hijau Pandan Halus","ja":"鮮やかな天然パンダンクレープ液を混ぜて漉す","ko":"천연 판단 즙을 넣어 부드러운 초록색 반죽 만들기"},"instruction":{"zh-TW":"盆中放入 150g 麵粉、1 大匙木薯粉、1/4 茶匙鹽。打入 1 顆雞蛋，倒入 120ml 純香蘭天然濃汁、180ml 椰漿牛奶液與 1 茶匙油。用打蛋器攪拌成無顆粒的滑順薄粉漿，過濾網兩次濾出細膩翠綠粉漿，靜置 15 分鐘消泡。","en":"Whisk 150g flour, 1 tbsp tapioca starch and salt in bowl. Crack in 1 egg; stream in 120ml vibrant green fresh pandan juice, 180ml coconut milk and 1 tsp oil. Whisk into smooth runny batter. Strain through fine sieve twice; rest 15 mins.","ms":"Campurkan tepung gandum, tepung ubi dan garam. Masukkan telur, air pandan hijau asli, santan dan minyak. Kacau sebati hingga licin cair. Tapis dua kali dan rehatkan 15 minit.","ja":"ボウルに粉、タピオカ粉、塩、卵、生パンダン果汁120ml、ココナッツミルク180ml、油少々を合わせ、泡立て器でダマなく混ぜます。茶漉しで2回漉してなめらかな翡翠色の生地にし、15分休ませます。","ko":"볼에 밀가루, 전분, 소금, 달걀, 신선한 판단 즙 120ml, 코코넛 밀크 180ml, 오일 약간을 넣고 고루 섞습니다. 고운 체에 2번 걸러 기포 없이 15분간 휴지합니다."},"durationSeconds":300},{"stepNumber":3,"image":"/images/my/kuih-dadar-step3.jpg","title":{"zh-TW":"平底鍋慢煎透薄綠玉斑紋薄餅 (Dadar)","en":"Pan-Sear Thin, Mottled Jade Crepes without Flipping","ms":"Goreng Kulit Kuih Dadar Hijau Nipis Berlubang Halus","ja":"フライパンで極薄の翡翠色クレープ生地を焼く（裏返し不要）","ko":"팬에 얇은 에메랄드빛 크레이프 부쳐내기 (뒤집지 않음)"},"instruction":{"zh-TW":"平底不沾鍋抹極薄一層油，開小火加熱。舀入約半勺（約 45ml）綠粉漿，迅速離火轉動鍋身，將粉漿薄薄鋪滿鍋底成圓形薄片。微火慢煎約 1 分鐘，看到邊緣微微捲起、表面凝固呈現均勻微細透氣斑紋，直接滑扣在乾淨砧板上放涼（切勿翻面！）。","en":"Lightly oil a non-stick crepe pan over low heat. Pour in 45ml green batter, immediately swirl pan in circular motion to spread into paper-thin circular disc. Cook for 1 min until edges peel away and small porous craters form on top (do NOT flip!). Slide onto a clean board to cool.","ms":"Sapu kuali leper dengan sedikit minyak atas api kecil. Tuang 45ml adunan hijau pandan dan putar kuali pantas membentuk bulat nipis. Masak 1 minit hingga permukaan masak berpori halus. Angkat atas papan landas tanpa dibalikkan.","ja":"テフロンフライパンに極薄く油を塗り弱火に。生地45mlを流し入れ、手早く鍋を回して底一面に丸く薄く広げます。弱火で約1分焼き、縁が自然と浮き上がり表面が乾いたらまな板に滑らせて冷まします（裏返し不要！）。","ko":"약불로 달군 팬에 오일을 얇게 바르고 반죽 45ml를 부어 팬을 둥글게 돌려 얇게 펼칩니다. 1분간 익혀 가장자리가 일어나고 윗면이 보송해지면 도마로 부드럽게 미끄러뜨려 식힙니다 (뒤집지 않음!)."},"durationSeconds":480},{"stepNumber":4,"image":"/images/my/kuih-dadar-step4.jpg","title":{"zh-TW":"鋪上多汁黑椰糖餡・捲成精緻春卷狀","en":"Enclose Gula Melaka Coconut & Roll into Jade Cylinder","ms":"Letak Inti Kelapa Manis & Gulung Kemas Seperti Popia","ja":"ジューシーな黒糖ココナッツ餡を乗せ、春巻き状に美しく巻く","ko":"촉촉한 코코넛 소를 올리고 춘권처럼 단단하게 말아 완성"},"instruction":{"zh-TW":"將煎好的薄餅斑紋面朝下、光滑面朝上平鋪。在靠近身側的一端，整齊橫放 2 大匙多汁的馬六甲椰糖椰絲餡。將底邊向上折起覆蓋住餡料，隨後將左右兩側向內折緊，往前輕柔推捲成如碧玉春卷般結實飽滿的長條圓卷。切開剖面，深黑糖汁與翠綠薄皮層次分明，一口咬下，多汁爆漿！","en":"Lay crepe textured side down on cutting board. Place 2 generous tablespoons of juicy Gula Melaka coconut filling horizontally across bottom third. Fold bottom edge up tightly over filling, tuck both sides inwards neatly, and roll forward into a plump, snug jade cylinder. Cut in half to showcase the dark, glistening caramelized coconut core!","ms":"Bentang kulit dadar. Letakkan 2 sb inti kelapa gula Melaka melintang di bahagian bawah. Lipat bahagian bawah menutupi inti, lipat kedua-dua belah sisi ke dalam dan gulung ke depan kemas. Potong serong untuk hidang.","ja":"クレープの気泡面を下にして置きます。手前にジューシーな黒糖ココナッツ餡を大さじ2杯細長く乗せます。手前からひと巻きし、左右の端を内側に折り込んで、前へキュッと巻き上げます。斜めにカットすると、鮮やかな緑と黒糖のコントラストが美しい絶品スイーツが完成！","ko":"크레이프의 매끄러운 면이 위로 오게 둡니다. 아래쪽에 촉촉한 코코넛 소를 2큰술 길게 올립니다. 아랫면을 덮고 양옆을 접은 뒤 앞쪽으로 단단하게 돌돌 말아줍니다. 사선으로 자르면 초록빛 피와 검은 코코넛 소의 환상적인 단면이 드러납니다!"},"durationSeconds":300}],"troubleshooting":[{"id":"crepe-tears","problem":{"zh-TW":"煎餅皮太脆或一捲就碎裂破洞","en":"Crepe skin is brittle and tears when rolled","ms":"Kulit dadar rapuh dan koyak bila digulung","ja":"生地が破れやすく、巻くときに裂けてしまう","ko":"크레이프가 바삭하거나 뻣뻣해서 말 때 찢어짐"},"cause":{"zh-TW":"火力太猛煎得過乾、或缺少木薯粉提供柔韌筋度","en":"Heat too high; dried out during cooking or omitted tapioca starch","ms":"Api terlalu kuat sehingga kulit garing atau tiada tepung ubi","ja":"焼き時間が長すぎて乾燥した、またはタピオカ粉の不足","ko":"너무 오래 구워 건조해졌거나 타피오카 전분이 부족함"},"solution":{"zh-TW":"粉漿中務必加入 1 大匙木薯粉增加彈韌度；平底鍋小火只需煎至表面凝固即出鍋，保持柔軟濕潤。","en":"Always include 1 tbsp tapioca starch for elasticity; cook on low heat just until set to keep it supple.","ms":"Wajib letak 1 sb tepung ubi kayu untuk keanjalan dan masak sekejap sahaja atas api kecil.","ja":"必ずタピオカ粉大さじ1を加えて弾力を出し、表面が乾いたらすぐ取り出してしっとり感を保ちます。","ko":"타피오카 전분 1큰술을 넣어 쫄깃함을 더하고, 약불에서 윗면이 굳자마자 바로 꺼내 부드러움을 유지하세요."}}],"proTips":[{"zh-TW":"天然翡翠綠秘訣：千萬不要用人工化學綠色色素！用 6 根新鮮香蘭葉加少許水打碎，靜置沉澱 2 小時取底部的深綠葉綠素沉澱汁，煎出來的班蘭卷顏色碧綠如玉、滿室散發天然東方香草的芬芳清香！","en":"The Master Herbalist Secret: Never use artificial neon green dye! Blend 6 fresh pandan leaves, let the juice settle in the fridge for 2 hours, and use the concentrated chlorophyll sedimentation at the bottom for pure natural jade beauty and enchanting vanilla aroma.","ms":"Rahsia Warna Zamrud Asli: Jangan guna pewarna tiruan! Kisar 6 helai daun pandan segar dan biarkan mendap di peti sejuk 2 jam. Ambil pati hijau pekat di dasar untuk warna hijau zamrud semulajadi.","ja":"大師直伝・翡翠色の極意：人工の着色料は絶対に使わないでください！生パンダンリーフ6枚をミキサーにかけ、冷蔵庫で2時間置いて沈殿した底の濃厚なクロロフィル液を使うと、天然とは思えないほど美しいエメラルドグリーンと極上の甘い香りに仕上がります。","ko":"장인의 천연 비법: 인공 색소는 쓰지 마세요! 신선한 판단잎 6장을 갈아 냉장고에서 2시간 가라앉힌 뒤, 바닥에 침전된 짙은 엽록소 진액만 사용하면 옥빛 천연 비취색과 그윽한 천연 바닐라 향이 완성됩니다."}]}];
